async function _loadRideshares(actId) {
  try {
    const rides = await api('/activities/' + actId + '/rideshares');
    const el = document.getElementById('rideshareList');
    if (!el) return;
    if (!rides.length) {
      el.innerHTML = '<p style="opacity:.6">Aucun covoiturage proposé pour le moment.</p>';
      return;
    }
    el.innerHTML = rides.map(r => {
      const placesLibres = r.places - (r.places_prises || 0);
      const myReq = r.my_request;
      const isOwner = r.user_id === USER.id;
      return '<div style="background:rgba(255,255,255,.1);border-radius:12px;padding:14px 18px;margin-bottom:10px">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">' +
          '<div>' +
            '<strong>' + escHtml(r.prenom + ' ' + r.nom) + '</strong>' +
            (r.type === 'offer' ? ' — offre un trajet' : ' — cherche un trajet') +
            (r.depart ? '<br>📍 Départ : ' + escHtml(r.depart) : '') +
            (r.heure_depart ? ' | 🕐 ' + escHtml(r.heure_depart) : '') +
            (r.type === 'offer' ? '<br>🪑 ' + placesLibres + ' place(s) libre(s) sur ' + r.places : '') +
            (r.note ? '<br>💬 ' + escHtml(r.note) : '') +
          '</div>' +
          '<div style="display:flex;gap:8px;flex-wrap:wrap">' +
            ((!isOwner && r.type === 'offer' && !myReq && placesLibres > 0)
              ? '<button onclick="_requestRideshare(' + r.id + ',' + actId + ')" style="background:#fff;color:#1b5e20;border:none;padding:6px 14px;border-radius:8px;font-weight:600;font-size:.82rem;cursor:pointer">Demander une place</button>'
              : '') +
            (myReq ? '<span style="background:rgba(255,255,255,.2);padding:4px 12px;border-radius:8px;font-size:.8rem">' + (myReq.statut === 'accepte' ? '✅ Accepté' : myReq.statut === 'refuse' ? '❌ Refusé' : '⏳ En attente') + '</span>' : '') +
            (isOwner && r.demandes_attente > 0
              ? '<button onclick="_manageRideshareRequests(' + r.id + ',' + actId + ')" style="background:#FFB300;color:#000;border:none;padding:6px 14px;border-radius:8px;font-weight:600;font-size:.82rem;cursor:pointer">📬 ' + r.demandes_attente + ' demande(s)</button>'
              : '') +
            (isOwner ? '<button onclick="_deleteRideshare(' + r.id + ',' + actId + ')" style="background:rgba(255,0,0,.3);color:#fff;border:none;padding:6px 14px;border-radius:8px;font-size:.82rem;cursor:pointer">🗑️</button>' : '') +
          '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  } catch(e) {
    const el = document.getElementById('rideshareList');
    if (el) el.innerHTML = '<p style="color:#ff9999">Erreur chargement covoiturages</p>';
  }
}

function openRideshareForm(actId) {
  openModal('Covoiturage', '<form id="rideshareForm">' +
    '<div class="form-group"><label>Type</label>' +
      '<select id="rs_type"><option value="offer">Je propose un trajet</option><option value="request">Je cherche un trajet</option></select></div>' +
    '<div class="form-group"><label>Lieu de départ</label><input id="rs_depart" placeholder="ex: Centre-ville Hamilton"/></div>' +
    '<div class="form-row">' +
      '<div class="form-group"><label>Places disponibles</label><input type="number" id="rs_places" value="1" min="1" max="8"/></div>' +
      '<div class="form-group"><label>Heure de départ</label><input type="time" id="rs_heure"/></div>' +
    '</div>' +
    '<div class="form-group"><label>Note</label><textarea id="rs_note" rows="2" placeholder="Infos supplémentaires..."></textarea></div>' +
    '<div class="form-actions">' +
      '<button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>' +
      '<button type="submit" class="btn btn-primary">Publier</button>' +
    '</div></form>');
  document.getElementById('rideshareForm').onsubmit = async function(e) {
    e.preventDefault();
    try {
      await api('/rideshares', { method:'POST', body: JSON.stringify({
        activity_id: actId,
        type: document.getElementById('rs_type').value,
        depart: document.getElementById('rs_depart').value,
        places: parseInt(document.getElementById('rs_places').value) || 1,
        heure_depart: document.getElementById('rs_heure').value,
        note: document.getElementById('rs_note').value
      })});
      toast('Covoiturage publié !');
      closeModal();
      openActivityDetail(actId);
    } catch(ex) { toast(ex.message, true); }
  };
}

async function _requestRideshare(rsId, actId) {
  try {
    await api('/rideshares/' + rsId + '/request', { method:'POST' });
    toast('Demande envoyée !');
    _loadRideshares(actId);
  } catch(e) { toast(e.message, true); }
}

async function _deleteRideshare(rsId, actId) {
  if (!confirm('Supprimer ce covoiturage ?')) return;
  try {
    await api('/rideshares/' + rsId, { method:'DELETE' });
    toast('Covoiturage supprimé');
    _loadRideshares(actId);
  } catch(e) { toast(e.message, true); }
}

async function _manageRideshareRequests(rsId, actId) {
  try {
    const reqs = await api('/rideshares/' + rsId + '/requests');
    openModal('Demandes de covoiturage', reqs.length === 0
      ? '<p style="color:var(--muted)">Aucune demande en attente.</p>'
      : '<div>' + reqs.map(function(r) {
          return '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)">' +
            '<div><strong>' + escHtml(r.prenom + ' ' + r.nom) + '</strong>' + (r.telephone ? ' | ' + escHtml(r.telephone) : '') +
              '<br><span style="font-size:.8rem;color:var(--muted)">' + (r.statut === 'en_attente' ? '⏳ En attente' : r.statut === 'accepte' ? '✅ Accepté' : '❌ Refusé') + '</span></div>' +
            (r.statut === 'en_attente' ? '<div style="display:flex;gap:6px">' +
              '<button onclick="_respondRideshareReq(' + rsId + ',' + r.id + ',\'accepte\',' + actId + ')" class="btn btn-sm btn-primary" style="font-size:.8rem">Accepter</button>' +
              '<button onclick="_respondRideshareReq(' + rsId + ',' + r.id + ',\'refuse\',' + actId + ')" class="btn btn-sm btn-ghost" style="font-size:.8rem">Refuser</button>' +
            '</div>' : '') +
          '</div>';
        }).join('') + '</div>' +
      '<div class="form-actions" style="margin-top:16px"><button class="btn btn-ghost" onclick="closeModal()">Fermer</button></div>'
    );
  } catch(e) { toast(e.message, true); }
}

async function _respondRideshareReq(rsId, reqId, statut, actId) {
  try {
    await api('/rideshares/' + rsId + '/requests/' + reqId, { method:'PUT', body: JSON.stringify({ statut: statut }) });
    toast(statut === 'accepte' ? 'Demande acceptée' : 'Demande refusée');
    _manageRideshareRequests(rsId, actId);
  } catch(e) { toast(e.message, true); }
}

function openActivityForm(a = null) {
  const isEdit = !!(a && a.id);  // seulement "edit" si l'objet a un id existant
  let rabais = {};
  try { rabais = JSON.parse(a?.rabais_json || '{}'); } catch {}

  openModal(isEdit ? 'Modifier l\'activité' : 'Nouvelle activité', `
    <form id="actForm">
      <div class="form-row">
        <div class="form-group"><label>Titre *</label><input id="a_titre" value="${a?.titre||''}" required/></div>
        <div class="form-group"><label>Type</label>
          <select id="a_type" onchange="document.getElementById('benevoleBlock').style.display=this.value==='benevolat'?'block':'none'">
            <option value="general" ${a?.type==='general'?'selected':''}>Général</option>
            <option value="culturel" ${a?.type==='culturel'?'selected':''}>Culturel</option>
            <option value="benevolat" ${a?.type==='benevolat'?'selected':''}>Bénévolat</option>
            <option value="reunion" ${a?.type==='reunion'?'selected':''}>Réunion</option>
            <option value="social" ${a?.type==='social'?'selected':''}>Social</option>
          </select></div>
      </div>
      <div id="benevoleBlock" style="${a?.type==='benevolat'?'':'display:none'}">
        <div style="background:var(--off);border-radius:10px;padding:14px;margin-bottom:12px;border:1px solid var(--border)">
          <div class="form-row">
            <div class="form-group"><label>Nombre de bénévoles requis</label><input type="number" id="a_benevoles_max" min="1" value="${a?.benevoles_max||''}" placeholder="ex: 5"/></div>
            <div class="form-group"><label>Prix spécial bénévole ($)</label><input type="number" id="a_prix_benevole" min="0" step="0.01" value="${a?.prix_benevole??''}" placeholder="Vide = prix régulier, 0 = gratuit"/></div>
          </div>
          <small style="color:var(--muted)">S'inscrire comme bénévole inscrit automatiquement à l'activité. Une fois le nombre requis atteint, seul le comité peut encore inscrire quelqu'un comme bénévole.</small>
        </div>
      </div>
      <div class="form-group">
        <label>Description</label>
        <div style="border:1.5px solid var(--border);border-radius:10px;overflow:hidden">
          <div style="display:flex;gap:2px;padding:6px 8px;background:var(--off);border-bottom:1px solid var(--border);flex-wrap:wrap">
            <button type="button" onclick="document.execCommand('bold')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-weight:900;font-size:.9rem" title="Gras">G</button>
            <button type="button" onclick="document.execCommand('italic')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-style:italic;font-size:.9rem" title="Italique"><em>I</em></button>
            <button type="button" onclick="document.execCommand('underline')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;text-decoration:underline;font-size:.9rem" title="Souligné">S</button>
            <span style="width:1px;background:var(--border);margin:2px 6px"></span>
            <button type="button" onclick="document.execCommand('fontSize','false','5')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-size:1.1rem;font-weight:700" title="Grand texte">A+</button>
            <button type="button" onclick="document.execCommand('fontSize','false','3')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-size:.75rem" title="Texte normal">A−</button>
            <span style="width:1px;background:var(--border);margin:2px 6px"></span>
            <button type="button" onclick="document.execCommand('insertUnorderedList')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-size:.85rem" title="Liste à puces">• Liste</button>
            <button type="button" onclick="document.execCommand('insertOrderedList')" style="border:none;background:none;cursor:pointer;padding:4px 8px;border-radius:4px;font-size:.85rem" title="Liste numérotée">1. Liste</button>
          </div>
          <div id="a_desc" contenteditable="true" style="min-height:120px;padding:12px 14px;font-size:.9rem;line-height:1.6;outline:none;color:var(--text)">${a?.description||''}</div>
        </div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Date début</label><input type="datetime-local" id="a_debut" value="${a?.date_debut||''}"/></div>
        <div class="form-group"><label>Date fin</label><input type="datetime-local" id="a_fin" value="${a?.date_fin||''}"/></div>
      </div>
      <div class="form-row">
        <div class="form-group">
          <label>Nombre d'heures</label>
          <input type="number" id="a_heures" min="0" step="0.25" placeholder="ex: 5"/>
          <small style="color:var(--muted)">Se remplit automatiquement avec la date de fin (dans un sens ou dans l'autre).</small>
        </div>
        <div class="form-group" style="display:flex;align-items:flex-end;padding-bottom:8px">
          <span id="a_dateErr" style="color:#c62828;font-size:.82rem;font-weight:600"></span>
        </div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Lieu</label><input id="a_lieu" value="${a?.lieu||''}"/></div>
        <div class="form-group"><label>Budget prévu ($)</label><input type="number" id="a_budget" value="${a?.budget_prevu||0}" step="0.01"/></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Max participants</label><input type="number" id="a_max" value="${a?.max_participants||''}"/></div>
        <div class="form-group"><label style="display:flex;align-items:center;gap:8px">
          <input type="checkbox" id="a_payant" style="width:auto" ${a?.paiement_requis?'checked':''} onchange="document.getElementById('payBlock').style.display=this.checked?'block':'none'"/>
          Activité payante
        </label></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Récurrence</label>
          <select id="a_recurrence">
            <option value="none" ${(!a?.recurrence||a?.recurrence==='none')?'selected':''}>Aucune</option>
            <option value="weekly" ${a?.recurrence==='weekly'?'selected':''}>Chaque semaine</option>
            <option value="biweekly" ${a?.recurrence==='biweekly'?'selected':''}>Aux 2 semaines</option>
            <option value="monthly" ${a?.recurrence==='monthly'?'selected':''}>Chaque mois</option>
          </select>
        </div>
        <div class="form-group"><label>Fin de récurrence</label>
          <input type="date" id="a_recurrence_end" value="${a?.recurrence_end||''}"/>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group"><label>Lien streaming (YouTube/Zoom)</label>
          <input id="a_stream" placeholder="https://..." value="${a?.stream_url||''}"/></div>
        <div class="form-group"><label style="display:flex;align-items:center;gap:8px">
          <input type="checkbox" id="a_stream_actif" style="width:auto" ${a?.stream_actif?'checked':''}/>
          Streaming en direct</label></div>
      </div>

      <!-- Bloc paiement -->
      <div id="payBlock" style="${a?.paiement_requis?'':'display:none'}">
        <div style="background:var(--off);border-radius:10px;padding:14px;margin-bottom:12px;border:1px solid var(--border)">
          <div class="form-group"><label>Prix ($) *</label><input type="number" id="a_prix" value="${a?.prix||''}" step="0.01" min="0" placeholder="ex: 15.00"/></div>
          ${canSetDiscount() ? `
          <div style="margin-top:8px"><label style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">Rabais par plan (VP/Présidente seulement)</label></div>
          <div class="form-row" style="margin-top:8px">
            <div class="form-group">
              <label>Plan Bienfaiteur</label>
              <div style="display:flex;gap:6px">
                <select id="r_bief_type" style="width:80px">
                  <option value="%" ${(rabais.bienfaiteur?.type||'%')==='%'?'selected':''}>%</option>
                  <option value="$" ${rabais.bienfaiteur?.type==='$'?'selected':''}>$</option>
                </select>
                <input type="number" id="r_bief_val" value="${rabais.bienfaiteur?.val||''}" min="0" placeholder="ex: 10"/>
              </div>
            </div>
            <div class="form-group">
              <label>Plan Partenaire</label>
              <div style="display:flex;gap:6px">
                <select id="r_part_type" style="width:80px">
                  <option value="%" ${(rabais.partenaire?.type||'%')==='%'?'selected':''}>%</option>
                  <option value="$" ${rabais.partenaire?.type==='$'?'selected':''}>$</option>
                </select>
                <input type="number" id="r_part_val" value="${rabais.partenaire?.val||''}" min="0" placeholder="ex: 5"/>
              </div>
            </div>
          </div>` : `<p style="font-size:.78rem;color:var(--muted)">Seuls VP et Présidente peuvent définir des rabais.</p>`}
          <div style="margin-top:12px;padding-top:10px;border-top:1px solid var(--border)">
            <label style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">Rabais Espace Jeunes</label>
            <div class="form-row" style="margin-top:8px">
              <div class="form-group">
                <label style="display:flex;align-items:center;gap:8px">
                  <input type="checkbox" id="a_rabais_jeune_actif" style="width:auto" ${a?.rabais_jeune>0?'checked':''} onchange="document.getElementById('rabaisJeuneVal').style.display=this.checked?'flex':'none'"/>
                  Offrir un rabais aux membres Espace Jeunes
                </label>
              </div>
            </div>
            <div id="rabaisJeuneVal" style="display:${a?.rabais_jeune>0?'flex':'none'};align-items:center;gap:8px;margin-top:6px">
              <label style="white-space:nowrap;margin:0">Rabais (%) :</label>
              <input type="number" id="a_rabais_jeune" value="${a?.rabais_jeune||50}" min="1" max="100" style="width:80px"/>
              <span style="font-size:.85rem;color:var(--muted)">% de réduction sur le prix de l'activité</span>
            </div>
          </div>
        </div>
      </div>

      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">${isEdit ? 'Enregistrer' : 'Créer'}</button>
      </div>
    </form>
  `);

  // ── Synchro Date début / Date fin / Nombre d'heures ──────────────────────
  const a_debut = document.getElementById('a_debut');
  const a_fin = document.getElementById('a_fin');
  const a_heures = document.getElementById('a_heures');
  const a_dateErr = document.getElementById('a_dateErr');
  let _actSyncing = false;

  function _actValidateDates() {
    if (a_debut.value && a_fin.value && new Date(a_fin.value) < new Date(a_debut.value)) {
      a_dateErr.textContent = '⚠️ La date de fin ne peut pas être avant la date de début';
      a_fin.style.borderColor = '#c62828';
      return false;
    }
    a_dateErr.textContent = '';
    a_fin.style.borderColor = '';
    return true;
  }
  function _actHeuresFromDates() {
    if (!a_debut.value || !a_fin.value || !_actValidateDates()) return;
    const diffH = (new Date(a_fin.value) - new Date(a_debut.value)) / 3600000;
    _actSyncing = true;
    a_heures.value = diffH > 0 ? Math.round(diffH * 100) / 100 : '';
    _actSyncing = false;
  }
  function _actFinFromHeures() {
    const h = parseFloat(a_heures.value);
    if (!a_debut.value || !h || h <= 0) return;
    const f = new Date(new Date(a_debut.value).getTime() + h * 3600000);
    f.setMinutes(f.getMinutes() - f.getTimezoneOffset());
    _actSyncing = true;
    a_fin.value = f.toISOString().slice(0, 16);
    _actSyncing = false;
    _actValidateDates();
  }
  a_debut.addEventListener('change', () => {
    if (_actSyncing) return;
    if (a_heures.value) _actFinFromHeures(); else _actValidateDates();
  });
  a_fin.addEventListener('change', () => {
    if (_actSyncing) return;
    if (_actValidateDates()) _actHeuresFromDates();
  });
  a_heures.addEventListener('input', () => {
    if (_actSyncing) return;
    _actFinFromHeures();
  });
  if (a_debut.value && a_fin.value) _actHeuresFromDates();

  document.getElementById('actForm').onsubmit = async e => {
    e.preventDefault();
    if (!_actValidateDates()) { toast('La date de fin ne peut pas être avant la date de début', 'error'); return; }
    const payant = document.getElementById('a_payant').checked;
    const rabaisJson = {};
    if (payant && canSetDiscount()) {
      const biefVal = parseFloat(document.getElementById('r_bief_val')?.value);
      const partVal = parseFloat(document.getElementById('r_part_val')?.value);
      if (biefVal > 0) rabaisJson.bienfaiteur = { type: document.getElementById('r_bief_type').value, val: biefVal };
      if (partVal > 0) rabaisJson.partenaire  = { type: document.getElementById('r_part_type').value, val: partVal };
    }
    const descEl = document.getElementById('a_desc');
    const descVal = descEl?.contentEditable === 'true' ? descEl.innerHTML : (descEl?.value || '');
    const body = { titre:document.getElementById('a_titre').value, type:document.getElementById('a_type').value,
      description:descVal, date_debut:document.getElementById('a_debut').value,
      date_fin:document.getElementById('a_fin').value, lieu:document.getElementById('a_lieu').value,
      budget_prevu:parseFloat(document.getElementById('a_budget').value)||0,
      max_participants:parseInt(document.getElementById('a_max').value)||null,
      paiement_requis: payant ? 1 : 0,
      prix: payant ? parseFloat(document.getElementById('a_prix').value)||0 : 0,
      rabais_json: JSON.stringify(rabaisJson),
      recurrence: document.getElementById('a_recurrence').value,
      recurrence_end: document.getElementById('a_recurrence_end').value || null,
      stream_url: document.getElementById('a_stream').value || null,
      stream_actif: document.getElementById('a_stream_actif').checked ? 1 : 0,
      rabais_jeune: (payant && document.getElementById('a_rabais_jeune_actif')?.checked)
        ? (parseInt(document.getElementById('a_rabais_jeune')?.value) || 0) : 0,
      benevoles_max: parseInt(document.getElementById('a_benevoles_max')?.value) || null,
      prix_benevole: document.getElementById('a_prix_benevole')?.value !== '' ? (parseFloat(document.getElementById('a_prix_benevole').value) || 0) : null };
    try {
      if (isEdit) {
        await api(`/activities/${a.id}`, { method:'PUT', body:JSON.stringify(body) });
        closeModal(); toast('Activité mise à jour'); activities();
      } else {
        const result = await api('/activities', { method:'POST', body:JSON.stringify(body) });
        closeModal();
        toast('Activité créée !');
        // Si payante, afficher le QR directement
        if (body.paiement_requis && result && result.id) {
          const titre = body.titre || 'Nouvelle activité';
          setTimeout(() => viewActivityQR(result.id, titre, result.qr_token), 300);
        } else {
          activities();
        }
        // Proposer le partage réseaux sociaux
        setTimeout(() => showSocialShareModal(body), 500);
      }
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function launchActivity(id, titre) {
  if (!confirm(`Lancer l'activité "${titre}" ? Une ligne financière sera créée.`)) return;
  try {
    await api(`/activities/${id}`, { method:'PUT', body: JSON.stringify({ statut:'en_cours' }) });
    toast('Activité lancée – ligne financière créée pour la trésorière'); activities();
  } catch(ex) { toast(ex.message, 'error'); }
}

async function viewRegistrations(id, titre) {
  const data = await api(`/activities/${id}/registrations`);
  openModal(`Inscriptions – ${titre}`, `
    <div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:10px;flex-wrap:wrap">
      ${can.executive() ? `<button class="btn btn-primary btn-sm" onclick="_ajouterMembreActivite(${id},'${titre.replace(/'/g,"\\'")}')">+ Ajouter un membre</button>` : ''}
      ${data.length && can.executive() ? `<button class="btn btn-outline btn-sm" onclick="openEmailInscritsForm(${id},'${titre.replace(/'/g,"\\'")}')">✉️ Envoyer un courriel aux inscrits</button>` : ''}
    </div>
    <div class="table-wrapper"><table>
      <thead><tr><th>Nom</th><th>Courriel</th><th>Téléphone</th><th>Statut</th><th>Date</th></tr></thead>
      <tbody>
        ${data.length ? data.map(r => `<tr><td>${escHtml(r.prenom)} ${escHtml(r.nom)}</td><td>${escHtml(r.email)}</td><td>${escHtml(r.telephone||'–')}</td><td>${statusPill(r.statut)}</td><td>${fmt(r.date_inscription)}</td></tr>`).join('') : '<tr><td colspan="5" style="text-align:center">Aucune inscription</td></tr>'}
      </tbody>
    </table></div>
  `);
}

function _amaResolveMembre(val) {
  const match = (window._amaUsers || []).find(u => _volMembreLabel(u) === val);
  document.getElementById('ama_user_id').value = match ? match.id : '';
}

async function _ajouterMembreActivite(activityId, titre) {
  const titreEsc = titre.replace(/'/g, "\\'");
  const allUsers = (await api('/users').catch(() => [])).filter(u => u.actif);
  window._amaUsers = allUsers;
  openModal(`+ Ajouter un membre — ${escHtml(titre)}`, `
    <form id="addMembreActForm">
      <div class="form-group"><label>Membre *</label>
        <input type="text" id="ama_search" list="ama_datalist" placeholder="Nom, courriel ou téléphone..." autocomplete="off" required oninput="_amaResolveMembre(this.value)"/>
        <datalist id="ama_datalist">
          ${allUsers.map(u => `<option value="${escHtml(_volMembreLabel(u))}">`).join('')}
        </datalist>
        <input type="hidden" id="ama_user_id"/>
      </div>
      <p style="font-size:.8rem;color:var(--muted)">La personne sera inscrite directement à l'activité, même si celle-ci est complète.</p>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="viewRegistrations(${activityId},'${titreEsc}')">Annuler</button>
        <button type="submit" class="btn btn-primary">Ajouter</button>
      </div>
    </form>
  `);
  document.getElementById('addMembreActForm').onsubmit = async e => {
    e.preventDefault();
    const uid = document.getElementById('ama_user_id').value;
    if (!uid) return toast('Choisissez un membre valide dans les suggestions', 'error');
    try {
      await api(`/activities/${activityId}/register`, { method:'POST', body: JSON.stringify({ user_id: parseInt(uid) }) });
      toast('✅ Membre ajouté à l\'activité');
      viewRegistrations(activityId, titre);
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

function openEmailInscritsForm(activityId, titre) {
  openModal(`Courriel aux inscrits – ${escHtml(titre)}`, `
    <form id="emailInscritsForm">
      <div class="form-group"><label>Sujet *</label><input id="ei_sujet" required placeholder="Ex. Rappel important pour l'activité"/></div>
      <div class="form-group"><label>Message *</label><textarea id="ei_message" rows="6" required placeholder="Votre message aux inscrits..."></textarea></div>
      <p style="font-size:.78rem;color:var(--muted)">Le courriel sera envoyé individuellement à chaque personne inscrite, signé en votre nom au nom du comité.</p>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Envoyer</button>
      </div>
    </form>
  `);
  document.getElementById('emailInscritsForm').onsubmit = async e => {
    e.preventDefault();
    const sujet = document.getElementById('ei_sujet').value.trim();
    const message = document.getElementById('ei_message').value.trim();
    if (!sujet || !message) return;
    try {
      const r = await api(`/activities/${activityId}/registrations/email`, { method:'POST', body: JSON.stringify({ sujet, message }) });
      closeModal();
      toast('✉️ Envoi en cours à ' + r.total + ' inscrit(s) — vous recevrez une alerte une fois terminé');
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function registerActivity(id) {
  try {
    const result = await api('/activities/' + id + '/register', { method:'POST' });
    if (result && result.waitlist) {
      toast('📋 Activité complète — vous êtes en liste d\'attente (position ' + result.position + ')');
    } else {
      toast('✅ Inscription confirmée !');
    }
    activities();
  } catch(ex) { toast(ex.message, 'error'); }
}

function _benevolePrixMessage(nom, r) {
  const gratuit = !r.paiement_requis || !r.prix_regulier;
  const prixBenevole = r.prix_benevole || 0;
  const prixRegulier = r.prix_regulier || 0;
  const reduction = Math.max(0, prixRegulier - prixBenevole);
  let priceHtml;
  if (gratuit) {
    priceHtml = `<div style="font-size:.95rem;color:var(--muted)">Cette activité est gratuite.</div>`;
  } else if (prixBenevole <= 0) {
    priceHtml = `
      <div style="font-size:.9rem;color:var(--muted);margin-bottom:6px">L'activité est de ${prixRegulier.toFixed(2)} $ mais</div>
      <div style="font-size:.9rem;margin-bottom:4px">gratuit pour les <b>Bénévoles</b> :</div>
      <div style="font-size:2.2rem;font-weight:800;color:#2e7d32;line-height:1.1">0,00 $</div>`;
  } else {
    priceHtml = `
      <div style="font-size:.9rem;color:var(--muted);margin-bottom:6px">En tant que bénévole pour <b>${escHtml(nom)}</b>, le montant à payer sera :</div>
      <div style="font-size:2.2rem;font-weight:800;color:#2e7d32;line-height:1.1">${prixBenevole.toFixed(2)} $</div>
      ${reduction > 0 ? `<div style="font-size:.82rem;color:var(--muted);margin-top:8px">soit une réduction de ${reduction.toFixed(2)} $ (prix régulier ${prixRegulier.toFixed(2)} $)</div>` : ''}`;
  }
  return priceHtml;
}

async function registerAsBenevole(id) {
  try {
    const r = await api(`/activities/${id}/register-benevole`, { method:'POST' });
    const act = (window._activitiesData || []).find(x => x.id === id);
    const nom = act ? act.titre : 'cette activité';
    openModal('🤝 Inscription bénévole confirmée', `
      <div style="text-align:center;padding:16px 0">
        <div style="font-size:2.6rem;margin-bottom:10px">✅</div>
        ${_benevolePrixMessage(nom, r)}
      </div>
      <div class="form-actions"><button type="button" class="btn btn-primary" onclick="closeModal()">Fermer</button></div>
    `);
  } catch(ex) { toast(ex.message, 'error'); }
}

async function genererHeuresBenevoles(actId, titre) {
  const presences = await api(`/activities/${actId}/presences`).catch(() => []);
  const act = (window._actById || {})[actId] || (window._activitiesData || []).find(x => x.id === actId);
  const presents = presences.filter(p => p.checked_in);
  const heuresAuto = act?.date_debut && act?.date_fin
    ? Math.max(0, Math.round(((new Date(act.date_fin) - new Date(act.date_debut)) / 3600000) * 100) / 100)
    : 0;
  openModal(`🤝 Générer les heures — ${escHtml(titre)}`, `
    ${presents.length ? `
    <div style="margin-bottom:16px">
      <div style="font-size:.85rem;color:var(--muted);margin-bottom:10px">${presents.length} membre(s) marqué(s) « Arrivé » vont recevoir une entrée d'heures en attente d'approbation (les membres qui en ont déjà une pour cette activité seront ignorés).</div>
      <ul style="margin:0 0 14px;padding-left:20px;font-size:.85rem">
        ${presents.map(p => `<li>${escHtml(p.prenom + ' ' + p.nom)}</li>`).join('')}
      </ul>
    </div>
    <form id="genHeuresForm">
      <div class="form-group"><label>Heures à créditer par bénévole</label><input type="number" step="0.5" min="0" id="genh_heures" value="${heuresAuto}"/>
        <small style="color:var(--muted)">${heuresAuto > 0 ? 'Calculé à partir de la durée de l\'activité — modifiable.' : 'Aucune durée détectée sur l\'activité — indiquez le nombre d\'heures.'}</small>
      </div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">🤝 Générer pour ${presents.length} bénévole(s)</button>
      </div>
    </form>` : `<div style="text-align:center;color:var(--muted);padding:20px 0">Aucun membre marqué « Arrivé » pour cette activité pour le moment.</div>
      <div class="form-actions"><button type="button" class="btn btn-ghost" onclick="closeModal()">Fermer</button></div>`}
  `);
  const form = document.getElementById('genHeuresForm');
  if (form) form.onsubmit = async e => {
    e.preventDefault();
    try {
      const r = await api(`/activities/${actId}/generer-heures-benevoles`, { method:'POST', body: JSON.stringify({
        heures: document.getElementById('genh_heures').value
      })});
      toast('✅ ' + r.message);
      closeModal();
      activities();
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function reparerInscriptionsBenevoles(actId, titre) {
  if (!confirm(`Corriger les inscriptions de « ${titre} » ?\n\nToute personne ayant déjà des heures de bénévolat (approuvées ou en attente) pour cette activité, mais absente de sa liste d'inscrits, sera ajoutée comme inscrite.`)) return;
  try {
    const r = await api(`/activities/${actId}/reparer-inscriptions-benevoles`, { method:'POST' });
    toast('🔧 ' + r.message);
    activities();
  } catch(ex) { toast(ex.message, 'error'); }
}

async function _comiteInscrireBenevole(actId) {
  const members = (await api('/users').catch(() => [])).filter(u => u.actif !== 0);
  openModal('🤝 Inscrire un bénévole', `
    <form id="comiteBenevoleForm">
      <div class="form-group"><label>Membre *</label>
        <select id="cbv_membre" required>
          <option value="">— Choisir —</option>
          ${members.map(u => `<option value="${u.id}">${escHtml(u.prenom + ' ' + u.nom)}</option>`).join('')}
        </select></div>
      <p style="font-size:.8rem;color:var(--muted)">L'inscription se fait même si le nombre de bénévoles requis est déjà atteint.</p>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="openActivityDetail(${actId})">Annuler</button>
        <button type="submit" class="btn btn-primary">🤝 Inscrire comme bénévole</button>
      </div>
    </form>
  `);
  document.getElementById('comiteBenevoleForm').onsubmit = async e => {
    e.preventDefault();
    const uid = document.getElementById('cbv_membre').value;
    if (!uid) return toast('Choisissez un membre', 'error');
    try {
      const r = await api(`/activities/${actId}/register-benevole`, { method:'POST', body: JSON.stringify({ user_id: uid }) });
      const membre = members.find(u => String(u.id) === String(uid));
      const act = (window._activitiesData || []).find(x => x.id === actId);
      const nom = act ? act.titre : 'cette activité';
      openModal('🤝 Bénévole inscrit(e)', `
        <div style="text-align:center;padding:16px 0">
          <div style="font-size:2.6rem;margin-bottom:10px">✅</div>
          <div style="font-weight:700;margin-bottom:14px">${escHtml(membre ? membre.prenom + ' ' + membre.nom : '')}</div>
          ${_benevolePrixMessage(nom, r)}
        </div>
        <div class="form-actions"><button type="button" class="btn btn-primary" onclick="openActivityDetail(${actId})">Fermer</button></div>
      `);
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

// ══ MEMBERS ════════════════════════════════════════════════════════════════
async function members() {
  const data = await api('/users');
  window._membersData = data;
  window._memberById = {}; data.forEach(u => window._memberById[u.id] = u);
  window._membersSort = { col:'nom', dir:1 };

  setContent(`
    <div class="page-header">
      <div><h2>Membres</h2><p id="membersCount">${data.length} membres enregistrés</p></div>
      <div class="page-actions">
        ${can.adminOrSec() ? `<a href="/api/export/membres.csv" class="btn btn-ghost" style="font-size:.82rem" target="_blank">⬇ CSV</a>` : ''}
        ${can.adminOrSec() ? '<button class="btn btn-primary" onclick="openMemberForm()">+ Ajouter un membre</button>' : ''}
      </div>
    </div>

    <div class="members-toolbar">
      <input id="memSearch" type="text" class="members-search"
        placeholder="🔍 Rechercher par nom, courriel ou téléphone…" oninput="filterMembers()"/>
      <select id="memRole" class="members-filter" onchange="filterMembers()">
        <option value="">Tous les rôles</option>
        <option value="admin">Admin</option>
        <option value="secretaire">Secrétaire</option>
        <option value="tresoriere">Trésorière</option>
        <option value="delegue">Accompagnateur</option>
        <option value="member">Membre</option>
      </select>
      <select id="memPlan" class="members-filter" onchange="filterMembers()">
        <option value="">Tous les plans</option>
        <option value="gratuit">Gratuit</option>
        <option value="bienfaiteur">💛 Bienfaiteur</option>
        <option value="partenaire">⭐ Partenaire</option>
      </select>
      <select id="memStatut" class="members-filter" onchange="filterMembers()">
        <option value="">Tous les statuts</option>
        <option value="1">Actif</option>
        <option value="0">Inactif</option>
      </select>
      <button class="btn btn-ghost btn-sm" onclick="resetMembersFilter()">✕ Effacer</button>
    </div>

    <div class="table-card">
      <div class="table-wrapper">
        <table id="membersTable">
          <thead><tr>
            <th class="th-sort" onclick="sortMembers('nom')">Nom <span id="si-nom" class="sort-ind">↕</span></th>
            <th class="th-sort" onclick="sortMembers('email')">Courriel <span id="si-email" class="sort-ind">↕</span></th>
            <th>Téléphone</th>
            <th class="th-sort" onclick="sortMembers('role')">Rôle <span id="si-role" class="sort-ind">↕</span></th>
            <th class="th-sort" onclick="sortMembers('plan')">Plan <span id="si-plan" class="sort-ind">↕</span></th>
            <th class="th-sort" onclick="sortMembers('actif')">Statut <span id="si-actif" class="sort-ind">↕</span></th>
            <th class="th-sort" onclick="sortMembers('date_inscription')">Inscription <span id="si-date_inscription" class="sort-ind">↕</span></th>
            <th>Actions</th>
          </tr></thead>
          <tbody id="membersBody"></tbody>
        </table>
      </div>
    </div>
  `);

  filterMembers();
}

function filterMembers() {
  const q      = (document.getElementById('memSearch')?.value  || '').toLowerCase().trim();
  const role   = document.getElementById('memRole')?.value    || '';
  const plan   = document.getElementById('memPlan')?.value    || '';
  const statut = document.getElementById('memStatut')?.value  ?? '';
  const data   = window._membersData || [];

  let filtered = data.filter(u => {
    if (q) {
      const hay = `${u.prenom} ${u.nom} ${u.email} ${u.telephone||''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    if (role   && u.role !== role)                   return false;
    if (plan   && (u.plan||'gratuit') !== plan)      return false;
    if (statut !== '' && String(u.actif) !== statut) return false;
    return true;
  });

  const { col, dir } = window._membersSort || { col:'nom', dir:1 };
  filtered.sort((a, b) => {
    let va = col === 'nom' ? `${a.prenom} ${a.nom}` : (a[col] ?? '');
    let vb = col === 'nom' ? `${b.prenom} ${b.nom}` : (b[col] ?? '');
    if (col === 'plan') { va = va||'gratuit'; vb = vb||'gratuit'; }
    if (typeof va === 'string') va = va.toLowerCase();
    if (typeof vb === 'string') vb = vb.toLowerCase();
    return va < vb ? -dir : va > vb ? dir : 0;
  });

  renderMembersTable(filtered, q);

  const cnt = document.getElementById('membersCount');
  if (cnt) cnt.textContent = filtered.length === data.length
    ? `${data.length} membres enregistrés`
    : `${filtered.length} résultat${filtered.length>1?'s':''} sur ${data.length} membres`;
}

function sortMembers(col) {
  const s = window._membersSort || { col:'nom', dir:1 };
  window._membersSort = { col, dir: s.col === col ? -s.dir : 1 };
  document.querySelectorAll('.sort-ind').forEach(el => el.textContent = '↕');
  const ic = document.getElementById(`si-${col}`);
  if (ic) ic.textContent = window._membersSort.dir === 1 ? '↑' : '↓';
  filterMembers();
}

function resetMembersFilter() {
  ['memSearch','memRole','memPlan','memStatut'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  window._membersSort = { col:'nom', dir:1 };
  document.querySelectorAll('.sort-ind').forEach(el => el.textContent = '↕');
  filterMembers();
}

function renderMembersTable(filtered, q) {
  const tbody = document.getElementById('membersBody');
  if (!tbody) return;
  if (!filtered.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:40px">Aucun membre ne correspond à la recherche</td></tr>';
    return;
  }
  function hl(text, q) {
    if (!q || text == null) return String(text ?? '–');
    const esc = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return String(text).replace(new RegExp(`(${esc})`, 'gi'),
      '<mark style="background:#fff3cd;border-radius:2px;padding:0 1px">$1</mark>');
  }
  tbody.innerHTML = filtered.map(u => `<tr>
    <td><strong style="cursor:pointer;color:var(--g2)" onclick="openMemberDetail(window._memberById[${u.id}])">${hl(u.prenom+' '+u.nom, q)}</strong></td>
    <td>${hl(u.email, q)}</td>
    <td>${hl(u.telephone||'–', q)}</td>
    <td>${pill(roleName(u.role), u.role==='admin'?'bp-orange':u.role==='member'?'bp-blue':'bp-green')}</td>
    <td>${can.executive()
      ? `<select class="plan-select" onchange="changePlan(${u.id},this.value)" style="font-size:.75rem;border:1px solid var(--border);border-radius:6px;padding:2px 6px;background:#fff">
           <option value="gratuit"     ${(u.plan||'gratuit')==='gratuit'    ?'selected':''}>Gratuit</option>
           <option value="bienfaiteur" ${(u.plan||'')==='bienfaiteur'?'selected':''}>💛 Bienfaiteur</option>
           <option value="partenaire"  ${(u.plan||'')==='partenaire' ?'selected':''}>⭐ Partenaire</option>
         </select>`
      : pill(u.plan||'gratuit', u.plan==='bienfaiteur'?'bp-orange':u.plan==='partenaire'?'bp-green':'bp-gray')}</td>
    <td>${u.actif ? pill('Actif','bp-green') : pill('Inactif','bp-red')}</td>
    <td>${fmt(u.date_inscription)}</td>
    <td>
      ${can.executive() ? `
        <button class="btn btn-sm btn-outline" onclick="openMemberForm(window._memberById[${u.id}])">✏️</button>
        ${u.actif
          ? `<button class="btn btn-sm btn-danger" onclick="toggleMember(${u.id},0)" title="Désactiver">🚫</button>`
          : `<button class="btn btn-sm btn-ghost"  onclick="toggleMember(${u.id},1)" title="Activer">✅</button>`}
        ${can.admin() ? `<button class="btn btn-sm btn-ghost" onclick="deleteMember(${u.id})" style="color:var(--red)" title="Supprimer définitivement">🗑</button>` : ''}` : ''}
      ${can.executive() ? `<button class="btn btn-sm btn-ghost" onclick="showVolunteerFor(${u.id},window._memberById[${u.id}].prenom+' '+window._memberById[${u.id}].nom)">🤝</button>` : ''}
      ${can.adminOrSec() ? `<button class="btn btn-sm btn-ghost" onclick="memberHistory(${u.id},window._memberById[${u.id}].prenom+' '+window._memberById[${u.id}].nom)" title="Historique">📋</button>` : ''}
    </td>
  </tr>`).join('');
}

function openMemberForm(u = null) {
  const isEdit = !!u;
  openModal(isEdit ? 'Modifier le membre' : 'Ajouter un membre', `
    <form id="memForm">
      <div class="form-row">
        <div class="form-group"><label>Prénom *</label><input id="m_prenom" value="${u?.prenom||''}" required/></div>
        <div class="form-group"><label>Nom *</label><input id="m_nom" value="${u?.nom||''}" required/></div>
      </div>
      <div class="form-group"><label>Courriel *</label><input type="email" id="m_email" value="${u?.email||''}" required/></div>
      <div class="form-row">
        <div class="form-group"><label>Téléphone</label><input id="m_tel" value="${u?.telephone||''}"/></div>
        <div class="form-group"><label>Date naissance</label><div style="display:flex;gap:6px">${htmlDobSelects('m_dob')}</div></div>
      </div>
      <div class="form-group"><label>Adresse</label><input id="m_addr" value="${u?.adresse||''}"/></div>
      ${can.admin() ? `<div class="form-group"><label>Rôle</label>
        <select id="m_role" onchange="document.getElementById('m_titre_wrap').style.display = ['delegue','secretaire','tresoriere','admin'].includes(this.value) ? 'block' : 'none'">
          <option value="member" ${u?.role==='member'?'selected':''}>Membre</option>
          <option value="delegue" ${u?.role==='delegue'?'selected':''}>Accompagnateur</option>
          <option value="secretaire" ${u?.role==='secretaire'?'selected':''}>Secrétaire</option>
          <option value="tresoriere" ${u?.role==='tresoriere'?'selected':''}>Trésorière</option>
          <option value="admin" ${u?.role==='admin'?'selected':''}>Admin</option>
        </select></div>` : ''}
      ${can.executive() ? `<div class="form-group" id="m_titre_wrap" style="display:${['delegue','secretaire','tresoriere','admin'].includes(u?.role)?'block':'none'}">
        <label>Titre affiché sur la carte de membre</label>
        <input id="m_titre" value="${escHtml(u?.titre_comite||'')}" placeholder="Ex. Présidente, Vice-président, Conseiller..."/>
      </div>` : ''}
      ${can.admin() ? `<div style="background:var(--off);border-radius:10px;padding:14px;margin-top:6px">
          <div style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px">📤 Courriel organisationnel (envoi externe)</div>
          <div class="form-row">
            <div class="form-group"><label>Courriel @ahhamilton.ca</label><input type="email" id="m_email_org" value="${u?.email_org||''}" placeholder="vp@ahhamilton.ca"/></div>
            <div class="form-group"><label>Mot de passe Hostinger</label><input type="password" id="m_smtp_pass" placeholder="Laisser vide = inchangé"/></div>
          </div>
        </div>` : ''}
      ${!isEdit ? `<div class="form-group"><label>Mot de passe *</label><input type="password" id="m_pw" required minlength="6"/></div>` : ''}
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">${isEdit ? 'Enregistrer' : 'Créer'}</button>
      </div>
    </form>
  `);
  fillDobSelects('m_dob', u?.date_naissance);
  document.getElementById('memForm').onsubmit = async e => {
    e.preventDefault();
    const body = { prenom:document.getElementById('m_prenom').value, nom:document.getElementById('m_nom').value,
      email:document.getElementById('m_email').value, telephone:document.getElementById('m_tel').value,
      adresse:document.getElementById('m_addr').value, date_naissance:readDobValue('m_dob') };
    if (can.admin()) {
      body.role = document.getElementById('m_role').value;
      body.email_org = document.getElementById('m_email_org').value.trim() || '';
      const smtpPass = document.getElementById('m_smtp_pass').value;
      if (smtpPass) body.smtp_pass_org = smtpPass;
    }
    const titreEl = document.getElementById('m_titre');
    if (titreEl) body.titre_comite = titreEl.value.trim();
    if (!isEdit) body.password = document.getElementById('m_pw').value;
    try {
      if (isEdit) {
        await api(`/users/${u.id}`, { method:'PUT', body:JSON.stringify(body) });
        const updated = await api(`/users/${u.id}`);
        const idx = (window._membersData || []).findIndex(m => m.id === u.id);
        if (idx !== -1) window._membersData[idx] = updated;
        closeModal(); toast('Membre mis à jour'); filterMembers();
      } else {
        await api('/users', { method:'POST', body:JSON.stringify(body) });
        window._membersData = await api('/annuaire');
        closeModal(); toast('Membre créé'); filterMembers();
      }
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function toggleMember(id, actif) {
  try {
    await api(`/users/${id}`, { method:'PUT', body: JSON.stringify({ actif }) });
    const u = (window._membersData || []).find(m => m.id === id);
    if (u) u.actif = actif;
    filterMembers();
    toast(actif ? 'Membre activé' : 'Membre désactivé');
  } catch(ex) { toast(ex.message, 'error'); }
}

async function sendResetPasswordLink(id, nom) {
  if (!confirm(`Envoyer un lien de réinitialisation de mot de passe à ${nom} ?`)) return;
  try {
    const r = await api(`/users/${id}/send-reset-password`, { method:'POST' });
    toast(r.message || 'Lien envoyé');
  } catch (ex) { toast(ex.message, 'error'); }
}

async function deleteMember(id) {
  const u = (window._membersData || []).find(m => m.id === id);
  const nom = u ? `${u.prenom} ${u.nom}` : `#${id}`;
  if (!confirm(`Supprimer définitivement ${nom} ?\nToutes ses données (inscriptions, heures, paiements) seront effacées. Action irréversible.`)) return;
  try {
    await api(`/users/${id}`, { method: 'DELETE' });
    window._membersData = (window._membersData || []).filter(m => m.id !== id);
    filterMembers();
    toast(`${nom} supprimé`);
  } catch (ex) { toast(ex.message, 'error'); }
}

async function changePlan(id, plan) {
  try {
    await api(`/users/${id}/plan`, { method:'PATCH', body: JSON.stringify({ plan }) });
    const u = (window._membersData || []).find(m => m.id === id);
    if (u) u.plan = plan;
    filterMembers();
    toast('Plan mis à jour : ' + plan);
  } catch(ex) {
    filterMembers(); // Revenir à l'ancienne valeur en cas d'erreur
    toast(ex.message, 'error');
  }
}

async function showVolunteerFor(userId, nom) {
  const data = await api('/volunteer');
  const filtered = data.filter(v => v.user_id === userId);
  const total = filtered.reduce((s, v) => s + v.heures, 0);
  openModal(`Bénévolat – ${nom}`, `
    <p style="margin-bottom:12px;font-weight:600">Total approuvé : ${filtered.filter(v=>v.statut==='approuve').reduce((s,v)=>s+v.heures,0)}h</p>
    <div class="table-wrapper"><table>
      <thead><tr><th>Activité</th><th>Heures</th><th>Date</th><th>Statut</th></tr></thead>
      <tbody>${filtered.map(v => `<tr><td>${v.activite||'–'}</td><td>${v.heures}h</td><td>${fmt(v.date_service)}</td><td>${statusPill(v.statut)}</td></tr>`).join('') || '<tr><td colspan="4" style="text-align:center">Aucune entrée</td></tr>'}</tbody>
    </table></div>
  `);
}

// ══ SUBCOMMITTEES ══════════════════════════════════════════════════════════

// Couleurs cycliques pour les cartes
const SC_COLORS = [
  {bg:'#1b5e20',light:'#e8f5e9'},{bg:'#0277bd',light:'#e3f2fd'},
  {bg:'#6a1b9a',light:'#f3e5f5'},{bg:'#bf360c',light:'#fbe9e7'},
  {bg:'#00695c',light:'#e0f2f1'},{bg:'#37474f',light:'#eceff1'},
];

async function subcommittees() {
  const [data, allUsers, allActs] = await Promise.all([
    api('/subcommittees'), api('/users'), api('/activities')
  ]);
  window._scAllUsers = allUsers;
  window._scAllActs = allActs;
  window._scData = {};
  data.forEach(sc => { window._scData[sc.id] = sc; });

  // Members only see their own subcommittees
  const visible = can.admin()
    ? data
    : data.filter(sc => sc.membres.some(m => m.id === USER.id));

  const emptyState = '<div class="empty-state"><div class="es-icon">🗂️</div>' +
    '<p>' + (can.admin() ? 'Aucun sous-comité créé. Commencez par en créer un !' : 'Vous ne faites partie d\'aucun sous-comité pour l\'instant.') + '</p></div>';

  setContent(
    '<div class="page-header">' +
      '<div><h2>🗂️ Sous-comités</h2><p>Mini-comités créés par l\'admin pour regrouper des membres autour d\'une mission</p></div>' +
      '<div class="page-actions">' +
        (can.admin() ? '<button class="btn btn-primary" onclick="openSubForm(null,window._scAllUsers,window._scAllActs)">+ Nouveau sous-comité</button>' : '') +
      '</div>' +
    '</div>' +

    (visible.length === 0 ? emptyState :
      '<div class="sc-grid">' +
      visible.map(function(sc, idx) {
        const col = SC_COLORS[idx % SC_COLORS.length];
        const chef = sc.membres.find(function(m) { return m.id === sc.chef_id; });
        const isMine = sc.membres.some(function(m) { return m.id === USER.id; });

        // Member avatars (max 6)
        const avatars = sc.membres.slice(0, 6).map(function(m) {
          const initials = (m.prenom[0] + m.nom[0]).toUpperCase();
          const isChef = m.id === sc.chef_id;
          return '<div class="sc-avatar' + (isChef ? ' sc-avatar--chef' : '') +
            '" style="background:' + col.bg + '" title="' + escHtml(m.prenom) + ' ' + escHtml(m.nom) + (isChef ? ' (chef)' : '') + '">' +
            initials + '</div>';
        }).join('');
        const extraCount = sc.membres.length > 6 ? sc.membres.length - 6 : 0;

        // Member list
        const memberRows = sc.membres.map(function(m) {
          const isChef = m.id === sc.chef_id;
          const initials = (m.prenom[0] + m.nom[0]).toUpperCase();
          return '<div class="sc-member-row">' +
            '<div class="sc-member-av" style="background:' + col.bg + '">' + initials + '</div>' +
            '<div class="sc-member-info">' +
              '<div class="sc-member-name">' + escHtml(m.prenom) + ' ' + escHtml(m.nom) + '</div>' +
              '<div class="sc-member-role">' + roleName(m.role) +
                (isChef ? ' · <span class="sc-chef-tag" style="color:' + col.bg + '">👑 Chef</span>' : '') +
              '</div>' +
            '</div>' +
          '</div>';
        }).join('');

        return '<div class="sc-card">' +
          // Header coloré
          '<div class="sc-card-header" style="background:' + col.bg + '">' +
            '<div class="sc-card-badge">' + sc.membres.length + ' membre' + (sc.membres.length>1?'s':'') + '</div>' +
            (isMine && !can.admin() ? '<div class="sc-card-mine">👤 Vous en faites partie</div>' : '') +
            (can.admin() ? '<div class="sc-card-actions">' +
              '<button class="sc-hdr-btn" onclick="openSubForm(window._scData[' + sc.id + '],window._scAllUsers,window._scAllActs)" title="Modifier">✏️</button>' +
              '<button class="sc-hdr-btn sc-hdr-btn--del" onclick="deleteSubcommittee(' + sc.id + ',\'' + sc.nom.replace(/'/g,"\\'") + '\')" title="Supprimer">🗑️</button>' +
            '</div>' : '') +
          '</div>' +

          // Corps
          '<div class="sc-card-body">' +
            '<h3 class="sc-card-title">' + sc.nom + '</h3>' +
            (sc.description ? '<p class="sc-card-desc">' + sc.description + '</p>' : '') +
            (sc.activite_titre ? '<div class="sc-card-act">📎 ' + sc.activite_titre + '</div>' : '') +
            (sc.chef_nom ? '<div class="sc-card-chef">👑 Chef : <strong>' + sc.chef_nom + '</strong></div>' : '') +

            // Avatars
            '<div class="sc-avatars">' +
              avatars +
              (extraCount > 0 ? '<div class="sc-avatar sc-avatar--more" style="background:' + col.bg + '">+' + extraCount + '</div>' : '') +
            '</div>' +

            // Liste dépliable
            '<details class="sc-details">' +
              '<summary class="sc-details-summary">Voir les ' + sc.membres.length + ' membre(s) →</summary>' +
              '<div class="sc-members-list">' + (memberRows || '<p style="color:var(--muted);font-size:.82rem;padding:8px">Aucun membre</p>') + '</div>' +
            '</details>' +
          '</div>' +
        '</div>';
      }).join('') +
      '</div>')
  );
}

async function deleteSubcommittee(id, nom) {
  if (!confirm('Supprimer le sous-comité « ' + nom + ' » ?')) return;
  try {
    await api('/subcommittees/' + id, { method: 'DELETE' });
    toast('Sous-comité supprimé');
    subcommittees();
  } catch(ex) { toast(ex.message, 'error'); }
}

// Sélecteur de membres par coches dans la modale
var _scSelectedIds = new Set();

function scToggleMember(id) {
  const was = _scSelectedIds.has(id);
  if (was) _scSelectedIds.delete(id);
  else _scSelectedIds.add(id);

  const now = !was;
  // Mettre à jour la coche visuelle
  const tick = document.getElementById('sctick_' + id);
  if (tick) {
    tick.textContent = now ? '✓' : '';
    tick.className = 'sc-tick' + (now ? ' sc-tick--on' : '');
  }
  const row = document.getElementById('scr_' + id);
  if (row) row.classList.toggle('sc-picker-row--selected', now);
  const counter = document.getElementById('scMemberCount');
  if (counter) counter.textContent = _scSelectedIds.size + ' membre(s) sélectionné(s)';
}

function openSubForm(sc, allUsers, allActs) {
  const isEdit = !!sc;
  _scSelectedIds = new Set((sc && sc.membres || []).map(function(m) { return m.id; }));
  const scSearch = '';

  const pickerRows = allUsers.filter(function(u) { return u.actif !== 0; }).map(function(u) {
    const initials = (u.prenom[0] + (u.nom[0]||'')).toUpperCase();
    const sel = _scSelectedIds.has(u.id);
    // div (pas label) pour éviter le double-déclenchement natif
    return '<div class="sc-picker-row' + (sel ? ' sc-picker-row--selected' : '') + '" id="scr_' + u.id + '" onclick="scToggleMember(' + u.id + ')">' +
      '<div class="sc-picker-av">' + initials + '</div>' +
      '<div class="sc-picker-info">' +
        '<div class="sc-picker-name">' + u.prenom + ' ' + u.nom + '</div>' +
        '<div class="sc-picker-role">' + roleName(u.role) + '</div>' +
      '</div>' +
      '<div class="sc-tick' + (sel ? ' sc-tick--on' : '') + '" id="sctick_' + u.id + '">' + (sel ? '✓' : '') + '</div>' +
    '</div>';
  }).join('');

  openModal(isEdit ? 'Modifier le sous-comité' : 'Nouveau sous-comité',
    '<form id="scForm">' +
      '<div class="form-group"><label>Nom du sous-comité *</label>' +
        '<input id="sc_nom" value="' + (sc && sc.nom ? sc.nom.replace(/"/g,'&quot;') : '') + '" placeholder="ex: Comité logistique Gala 2026" required/></div>' +
      '<div class="form-group"><label>Description / Mandat</label>' +
        '<textarea id="sc_desc" rows="2" placeholder="Quel est l\'objectif de ce comité ?">' + (sc && sc.description ? sc.description : '') + '</textarea></div>' +
      '<div class="form-row">' +
        '<div class="form-group"><label>Chef du comité</label>' +
          '<select id="sc_chef"><option value="">– Aucun –</option>' +
          allUsers.map(function(u) {
            return '<option value="' + u.id + '"' + (sc && sc.chef_id===u.id ? ' selected' : '') + '>' + u.prenom + ' ' + u.nom + '</option>';
          }).join('') + '</select></div>' +
        '<div class="form-group"><label>Activité liée</label>' +
          '<select id="sc_act"><option value="">– Aucune –</option>' +
          allActs.map(function(a) {
            return '<option value="' + a.id + '"' + (sc && sc.activity_id===a.id ? ' selected' : '') + '>' + a.titre + '</option>';
          }).join('') + '</select></div>' +
      '</div>' +

      // Sélecteur de membres
      '<div class="form-group">' +
        '<label>Membres <span id="scMemberCount" style="font-weight:400;color:var(--muted)">(' + _scSelectedIds.size + ' sélectionné(s))</span></label>' +
        '<input type="text" placeholder="🔍 Filtrer par nom…" style="margin-bottom:8px" oninput="scFilterPicker(this.value)"/>' +
        '<div class="sc-picker" id="scPicker">' + pickerRows + '</div>' +
      '</div>' +

      '<div class="form-actions">' +
        '<button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>' +
        '<button type="submit" class="btn btn-primary">' + (isEdit ? 'Enregistrer' : 'Créer') + '</button>' +
      '</div>' +
    '</form>'
  );

  document.getElementById('scForm').onsubmit = async function(e) {
    e.preventDefault();
    const btn = e.target.querySelector('[type=submit]');
    btn.disabled = true; btn.textContent = 'En cours…';

    const membres = [..._scSelectedIds].map(function(id) { return { user_id: id }; });
    const nom = document.getElementById('sc_nom').value.trim();
    const body = {
      nom: nom,
      description: document.getElementById('sc_desc').value,
      chef_id: parseInt(document.getElementById('sc_chef').value) || null,
      activity_id: parseInt(document.getElementById('sc_act').value) || null,
      membres: membres
    };

    try {
      if (isEdit) {
        await api('/subcommittees/' + sc.id, { method:'PUT', body:JSON.stringify(body) });
        closeModal(); toast('Sous-comité mis à jour'); subcommittees();
      } else {
        // 1. Créer le sous-comité
        await api('/subcommittees', { method:'POST', body:JSON.stringify(body) });

        const memberIds = [..._scSelectedIds];

        // 2. Envoyer un courriel interne à chaque membre sélectionné
        if (memberIds.length > 0) {
          const chefUser = allUsers.find(function(u) { return u.id === body.chef_id; });
          const chefNom = chefUser ? chefUser.prenom + ' ' + chefUser.nom : USER.prenom + ' ' + USER.nom;
          const contenu =
            '📢 Vous avez été ajouté(e) au sous-comité « ' + nom + ' ».\n\n' +
            (body.description ? 'Mandat : ' + body.description + '\n\n' : '') +
            'Chef du comité : ' + chefNom + '\n' +
            'Membres : ' + memberIds.length + ' personne(s)\n\n' +
            'Un salon de discussion privé a été créé pour votre équipe.\n\n' +
            '— ' + USER.prenom + ' ' + USER.nom + ', ' + roleName(USER.role);

          await api('/messages', {
            method: 'POST',
            body: JSON.stringify({
              sujet: '🗂️ Nouveau sous-comité : ' + nom,
              contenu: contenu,
              destinataires: memberIds
            })
          }).catch(function(ex) { console.warn('Courriel sous-comité:', ex.message); });
        }

        // 3. Créer un salon de chat privé pour le sous-comité
        if (memberIds.length > 0) {
          await api('/chat/rooms', {
            method: 'POST',
            body: JSON.stringify({
              name: '🗂️ ' + nom,
              member_ids: memberIds
            })
          }).catch(function(ex) { console.warn('Chat sous-comité:', ex.message); });
        }

        // Rafraîchir la liste des salons de chat pour que le nouveau salon apparaisse
        loadChatRooms().catch(function() {});

        closeModal();
        toast('✅ Sous-comité créé — courriel envoyé + salon de chat créé !');
        subcommittees();
      }
    } catch(ex) {
      toast(ex.message, 'error');
      btn.disabled = false; btn.textContent = isEdit ? 'Enregistrer' : 'Créer';
    }
  };
}

function scFilterPicker(q) {
  const picker = document.getElementById('scPicker');
  if (!picker) return;
  const lower = q.toLowerCase();
  picker.querySelectorAll('.sc-picker-row').forEach(function(row) {
    const name = (row.querySelector('.sc-picker-name') || {}).textContent || '';
    row.style.display = name.toLowerCase().includes(lower) ? '' : 'none';
  });
}

// ══ FINANCE ════════════════════════════════════════════════════════════════
const FIN_CATEGORIES = [
  ['loyer','🏠 Loyer / Location de salle'],
  ['nourriture','🍽️ Nourriture / Traiteur'],
  ['materiel','📦 Matériel / Fournitures'],
  ['transport','🚗 Transport'],
  ['communication','📣 Communication / Marketing'],
  ['assurance','🛡️ Assurance'],
  ['frais_bancaires','🏦 Frais bancaires'],
  ['dons','🎁 Dons reçus'],
  ['cotisations','💳 Cotisations'],
  ['commandites','🤝 Commandites'],
  ['subventions','🏛️ Subventions'],
  ['evenement','🎉 Événement / Activité'],
  ['autre','📁 Autre'],
];
function finCatLabel(id) { return (FIN_CATEGORIES.find(c => c[0] === id) || FIN_CATEGORIES[FIN_CATEGORIES.length-1])[1]; }
function finCatOptions(selected) {
  return FIN_CATEGORIES.map(([id,label]) => `<option value="${id}" ${selected===id?'selected':''}>${label}</option>`).join('');
}

async function finance() {
  const annee = window._finAnnee || new Date().getFullYear();
  const [lines, rep, summary, chartData, annualBudget] = await Promise.all([
    api('/finance/lines'), api('/finance/account'), api('/finance/summary').catch(() => ({})),
    api('/finance/chart').catch(() => []), api(`/finance/annual-budget/${annee}`).catch(() => null)
  ]);
  window._finLines = lines;
  window._finRep   = rep;
  window._finAllLines = lines;
  window._finAnnee = annee;
  const totalBudget = lines.reduce((s,l) => s + (l.budget_alloue||0), 0);
  const totalDep    = lines.reduce((s,l) => s + (l.depenses||0), 0);
  const totalRev    = lines.reduce((s,l) => s + (l.revenus||0), 0);
  const totalComm   = lines.reduce((s,l) => s + (l.commanditaires||0), 0);

  setContent(`
    <div class="page-header">
      <div><h2>Finance</h2><p>Gestion des fonds et lignes budgétaires</p></div>
      <div class="page-actions">
        ${can.adminOrTre() ? `<button class="btn btn-primary" onclick="openTransactionForm(null,window._finLines)">+ Transaction</button>` : ''}
        ${can.adminOrTre() ? `<button class="btn btn-outline" onclick="openAccountForm(window._finRep)">⚙️ Compte</button>` : ''}
        <button class="btn btn-ghost" onclick="showView('fournisseurs')">🏢 Fournisseurs</button>
        <button class="btn btn-ghost" onclick="printFinance()">🖨️ PDF</button>
        <a href="/api/export/paiements.csv" class="btn btn-ghost" style="font-size:.82rem" target="_blank">⬇ CSV</a>
      </div>
    </div>
    <div class="finance-summary">
      <div class="fin-card"><div class="fc-val">${fmtMoney(rep?.solde)}</div><div class="fc-label">Solde actuel</div></div>
      <div class="fin-card"><div class="fc-val">${summary?.projets_en_cours ?? '–'}</div><div class="fc-label">Projets en cours</div></div>
      <div class="fin-card"><div class="fc-val">${fmtMoney(totalBudget)}</div><div class="fc-label">Budget total alloué</div></div>
      <div class="fin-card"><div class="fc-val negative">${fmtMoney(totalDep)}</div><div class="fc-label">Total dépenses</div></div>
      <div class="fin-card"><div class="fc-val">${fmtMoney(totalRev)}</div><div class="fc-label">Total revenus</div></div>
      ${totalComm > 0 ? `<div class="fin-card"><div class="fc-val" style="color:#0277bd">${fmtMoney(totalComm)}</div><div class="fc-label">Commanditaires</div></div>` : ''}
    </div>
    <div class="table-card" style="padding:16px;margin-bottom:20px" id="annualBudgetCard"></div>
    <div style="display:flex;gap:16px;margin-bottom:20px;flex-wrap:wrap">
      <div class="table-card" style="flex:1;min-width:280px;padding:16px">
        <h4 style="margin:0 0 10px;font-size:.88rem;color:var(--text)">Budget vs Dépenses</h4>
        <canvas id="finBarChart" height="160"></canvas>
      </div>
      <div class="table-card" style="width:220px;flex-shrink:0;padding:16px;display:flex;flex-direction:column;align-items:center">
        <h4 style="margin:0 0 10px;font-size:.88rem;color:var(--text);align-self:flex-start">Répartition</h4>
        <canvas id="finDonut" style="max-width:180px;max-height:180px"></canvas>
      </div>
    </div>
    <div class="table-card" style="padding:16px;margin-bottom:20px">
      <h4 style="margin:0 0 10px;font-size:.88rem;color:var(--text)">📈 Revenus & Dépenses — 12 derniers mois</h4>
      <canvas id="finMonthChart" height="120"></canvas>
    </div>
    <div class="table-card">
      <div class="table-card-header" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <h3 style="margin:0">Lignes financières</h3>
        <input id="finSearch" type="text" class="members-search" style="max-width:260px;margin:0"
          placeholder="🔍 Rechercher…" oninput="filterFinLines()"/>
        <select id="finStatut" class="members-filter" onchange="filterFinLines()" style="margin:0">
          <option value="">Tous les statuts</option>
          <option value="actif">Actif</option>
          <option value="termine">Terminé</option>
          <option value="archive">Archivé</option>
        </select>
      </div>
      <div class="table-wrapper"><table>
        <thead><tr><th>Titre / Activité</th><th>Budget alloué</th><th>Dépenses</th><th>En attente</th><th>Revenus</th><th>Commanditaires</th><th>Solde</th><th>Solde total</th><th>Statut</th><th>Actions</th></tr></thead>
        <tbody id="finLinesBody"></tbody>
      </table></div>
    </div>
    <p style="font-size:.78rem;color:var(--muted);margin-top:-8px">Institution: ${rep?.institution||'–'} · Compte: ${rep?.numero_compte||'–'} · Titulaire: ${rep?.nom_titulaire||'–'}</p>
  `);
  filterFinLines();
  renderAnnualBudgetCard(annualBudget, annee);
  setTimeout(() => renderFinCharts(lines, chartData), 50);
}

function renderAnnualBudgetCard(b, annee) {
  const el = document.getElementById('annualBudgetCard');
  if (!el) return;
  b = b || { budget_revenus:0, budget_depenses:0, revenus_reel:0, depenses_reel:0, notes:'' };
  const thisYear = new Date().getFullYear();
  const years = [thisYear+1, thisYear, thisYear-1, thisYear-2, thisYear-3];
  const pctDep = b.budget_depenses > 0 ? Math.round(b.depenses_reel / b.budget_depenses * 100) : 0;
  const pctRev = b.budget_revenus > 0 ? Math.round(b.revenus_reel / b.budget_revenus * 100) : 0;
  const barDep = pctDep >= 100 ? 'var(--red)' : pctDep >= 80 ? '#e65100' : 'var(--g2)';
  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:12px">
      <h4 style="margin:0;font-size:.88rem;color:var(--text)">📅 Budget annuel global</h4>
      <div style="display:flex;align-items:center;gap:8px">
        <select id="annualBudgetYear" style="padding:4px 8px;border-radius:6px;border:1px solid var(--border)">
          ${years.map(y=>`<option value="${y}" ${y===annee?'selected':''}>${y}</option>`).join('')}
        </select>
        ${can.adminOrTre() ? `<button class="btn btn-sm btn-outline" onclick="openAnnualBudgetForm(${annee}, window._finAnnualBudget)">✏️ Modifier</button>` : ''}
      </div>
    </div>
    <div style="display:flex;gap:24px;flex-wrap:wrap">
      <div style="flex:1;min-width:220px">
        <div style="display:flex;justify-content:space-between;font-size:.82rem;margin-bottom:4px">
          <span>Dépenses : ${fmtMoney(b.depenses_reel)} / ${fmtMoney(b.budget_depenses)}</span>
          <strong style="color:${barDep}">${b.budget_depenses>0?pctDep+'%':'–'}</strong>
        </div>
        <div style="background:var(--off);border-radius:20px;height:8px;overflow:hidden">
          <div style="height:100%;width:${Math.min(pctDep,100)}%;background:${barDep};border-radius:20px"></div>
        </div>
      </div>
      <div style="flex:1;min-width:220px">
        <div style="display:flex;justify-content:space-between;font-size:.82rem;margin-bottom:4px">
          <span>Revenus : ${fmtMoney(b.revenus_reel)} / ${fmtMoney(b.budget_revenus)}</span>
          <strong style="color:var(--g2)">${b.budget_revenus>0?pctRev+'%':'–'}</strong>
        </div>
        <div style="background:var(--off);border-radius:20px;height:8px;overflow:hidden">
          <div style="height:100%;width:${Math.min(pctRev,100)}%;background:var(--g2);border-radius:20px"></div>
        </div>
      </div>
    </div>
    ${b.notes ? `<p style="font-size:.78rem;color:var(--muted);margin:10px 0 0">${escHtml(b.notes)}</p>` : ''}
  `;
  window._finAnnualBudget = b;
  document.getElementById('annualBudgetYear').onchange = async function() {
    window._finAnnee = parseInt(this.value);
    const nb = await api(`/finance/annual-budget/${window._finAnnee}`).catch(() => null);
    renderAnnualBudgetCard(nb, window._finAnnee);
  };
}

function openAnnualBudgetForm(annee, existing) {
  existing = existing || {};
  openModal(`Budget annuel ${annee}`, `
    <form id="annualBudgetForm">
      <div class="form-row">
        <div class="form-group"><label>Budget dépenses prévu ($)</label><input type="number" step="0.01" id="ab_dep" value="${existing.budget_depenses||0}"/></div>
        <div class="form-group"><label>Budget revenus prévu ($)</label><input type="number" step="0.01" id="ab_rev" value="${existing.budget_revenus||0}"/></div>
      </div>
      <div class="form-group"><label>Notes</label><textarea id="ab_notes" rows="2">${escHtml(existing.notes||'')}</textarea></div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Enregistrer</button>
      </div>
    </form>
  `);
  document.getElementById('annualBudgetForm').onsubmit = async e => {
    e.preventDefault();
    const body = { budget_depenses: parseFloat(document.getElementById('ab_dep').value)||0,
      budget_revenus: parseFloat(document.getElementById('ab_rev').value)||0,
      notes: document.getElementById('ab_notes').value };
    try {
      await api(`/finance/annual-budget/${annee}`, { method:'PUT', body: JSON.stringify(body) });
      closeModal(); toast('Budget annuel mis à jour');
      const nb = await api(`/finance/annual-budget/${annee}`).catch(() => null);
      renderAnnualBudgetCard(nb, annee);
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

function renderFinCharts(lines, monthlyData) {
  if (typeof Chart === 'undefined') return;
  const top = lines.slice(0, 10);
  const barEl = document.getElementById('finBarChart');
  if (barEl) {
    Chart.getChart(barEl)?.destroy();
    new Chart(barEl, {
      type: 'bar',
      data: {
        labels: top.map(l => (l.activite || l.titre || '').substring(0, 16)),
        datasets: [
          { label: 'Budget', data: top.map(l => l.budget_alloue || 0), backgroundColor: 'rgba(46,125,50,.65)', borderRadius: 4 },
          { label: 'Dépenses', data: top.map(l => l.depenses || 0), backgroundColor: 'rgba(211,47,47,.65)', borderRadius: 4 }
        ]
      },
      options: { responsive: true, plugins: { legend: { position: 'bottom', labels: { font: { size: 11, family: 'Poppins' } } } },
        scales: { y: { beginAtZero: true, ticks: { callback: v => '$' + v.toFixed(0), font: { size: 10 } } },
          x: { ticks: { font: { size: 10 } } } } }
    });
  }
  const donutEl = document.getElementById('finDonut');
  if (donutEl) {
    const totalBudget = lines.reduce((s,l) => s + (l.budget_alloue||0), 0);
    const totalDep    = lines.reduce((s,l) => s + (l.depenses||0), 0);
    const totalRev    = lines.reduce((s,l) => s + (l.revenus||0), 0);
    const totalComm   = lines.reduce((s,l) => s + (l.commanditaires||0), 0);
    Chart.getChart(donutEl)?.destroy();
    new Chart(donutEl, {
      type: 'doughnut',
      data: {
        labels: ['Budget', 'Dépenses', 'Revenus', 'Commanditaires'],
        datasets: [{ data: [totalBudget, totalDep, totalRev, totalComm],
          backgroundColor: ['rgba(46,125,50,.75)', 'rgba(211,47,47,.75)', 'rgba(25,118,210,.75)', 'rgba(2,119,189,.75)'],
          borderWidth: 2, borderColor: '#fff' }]
      },
      options: { responsive: true, cutout: '60%',
        plugins: { legend: { position: 'bottom', labels: { font: { size: 10, family: 'Poppins' }, boxWidth: 12 } } } }
    });
  }
  // Monthly revenue / expense line chart
  const monthEl = document.getElementById('finMonthChart');
  if (monthEl && Array.isArray(monthlyData) && monthlyData.length) {
    const MONTH_LABELS_FR = ['Jan','Fév','Mar','Avr','Mai','Jun','Jul','Aoû','Sep','Oct','Nov','Déc'];
    const labels = monthlyData.map(r => {
      const [y, m] = r.mois.split('-');
      return MONTH_LABELS_FR[parseInt(m) - 1] + ' ' + y.slice(2);
    });
    Chart.getChart(monthEl)?.destroy();
    new Chart(monthEl, {
      type: 'line',
      data: {
        labels,
        datasets: [
          { label: 'Revenus', data: monthlyData.map(r => r.revenus || 0), borderColor: '#2e7d32', backgroundColor: 'rgba(46,125,50,.1)', tension: .35, fill: true, pointRadius: 4 },
          { label: 'Dépenses', data: monthlyData.map(r => r.depenses || 0), borderColor: '#c62828', backgroundColor: 'rgba(198,40,40,.08)', tension: .35, fill: true, pointRadius: 4 },
        ]
      },
      options: {
        responsive: true,
        plugins: { legend: { position: 'bottom', labels: { font: { size: 11, family: 'Poppins' }, boxWidth: 14 } } },
        scales: {
          y: { beginAtZero: true, ticks: { callback: v => '$' + v.toFixed(0), font: { size: 10 } } },
          x: { ticks: { font: { size: 10 } } }
        }
      }
    });
  }
}

function printFinance() {
  const lines  = window._finAllLines || [];
  const rep    = window._finRep || {};
  const totalBudget = lines.reduce((s,l) => s + (l.budget_alloue||0), 0);
  const totalDep    = lines.reduce((s,l) => s + (l.depenses||0), 0);
  const totalRev    = lines.reduce((s,l) => s + (l.revenus||0), 0);
  const totalComm   = lines.reduce((s,l) => s + (l.commanditaires||0), 0);
  const html = `<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/>
  <title>Rapport financier – AHH</title>
  <style>
    body{font-family:Arial,sans-serif;font-size:12px;margin:24px;color:#222}
    h1{font-size:18px;color:#1b5e20;margin:0 0 4px}
    .meta{color:#666;font-size:11px;margin-bottom:16px}
    .summary{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:18px}
    .card{border:1px solid #e0e0e0;border-radius:6px;padding:10px 14px;min-width:110px}
    .cv{font-size:16px;font-weight:700;color:#1b5e20}.cl{font-size:10px;color:#666;margin-top:2px}
    table{width:100%;border-collapse:collapse}
    th{background:#1b5e20;color:#fff;padding:6px 8px;font-size:11px;text-align:left}
    td{padding:5px 8px;border-bottom:1px solid #eee;font-size:11px}
    .red{color:#c62828}.grn{color:#1b5e20}.bold{font-weight:700}
    @media print{@page{margin:18mm}button{display:none}}
  </style></head><body>
  <h1>Rapport financier — Association Haïtienne de Hamilton</h1>
  <div class="meta">Généré le ${new Date().toLocaleDateString('fr-CA')} · Compte : ${rep.numero_compte||'–'} · Titulaire : ${rep.nom_titulaire||'–'} · Solde actuel : <strong>$${(+rep.solde||0).toFixed(2)}</strong></div>
  <div class="summary">
    <div class="card"><div class="cv">$${totalBudget.toFixed(2)}</div><div class="cl">Budget total alloué</div></div>
    <div class="card"><div class="cv red">$${totalDep.toFixed(2)}</div><div class="cl">Total dépenses</div></div>
    <div class="card"><div class="cv grn">$${totalRev.toFixed(2)}</div><div class="cl">Total revenus</div></div>
    ${totalComm>0?`<div class="card"><div class="cv" style="color:#0277bd">$${totalComm.toFixed(2)}</div><div class="cl">Commanditaires</div></div>`:''}
  </div>
  <table><thead><tr><th>Titre / Activité</th><th>Budget</th><th>Dépenses</th><th>En attente</th><th>Revenus</th><th>Solde</th><th>Statut</th></tr></thead>
  <tbody>${lines.map(l=>{const solde=(l.budget_alloue||0)-(l.depenses||0)+(l.revenus||0)+(l.commanditaires||0);
    return`<tr><td class="bold">${l.activite||l.titre}</td><td>$${(l.budget_alloue||0).toFixed(2)}</td>
    <td class="red">$${(l.depenses||0).toFixed(2)}</td>
    <td>${(l.depenses_en_attente||0)>0?'⏳ $'+(l.depenses_en_attente||0).toFixed(2):'–'}</td>
    <td class="grn">$${(l.revenus||0).toFixed(2)}</td>
    <td class="${solde<0?'red':'grn'} bold">$${solde.toFixed(2)}</td>
    <td>${l.statut}</td></tr>`;}).join('')}
  </tbody></table>
  <script>window.print();<\/script></body></html>`;
  const w = window.open('', '_blank', 'width=900,height=700');
  w.document.write(html);
  w.document.close();
}

function filterFinLines() {
  const q      = (document.getElementById('finSearch')?.value || '').toLowerCase().trim();
  const statut = document.getElementById('finStatut')?.value || '';
  const lines  = window._finAllLines || [];
  const filtered = lines.filter(l => {
    if (q && !`${l.titre} ${l.activite||''} ${l.projet||''}`.toLowerCase().includes(q)) return false;
    if (statut && l.statut !== statut) return false;
    return true;
  });
  renderFinLines(filtered);
}

function renderFinLines(lines) {
  const tbody = document.getElementById('finLinesBody');
  if (!tbody) return;
  if (!lines.length) {
    tbody.innerHTML = '<tr><td colspan="10" style="text-align:center;color:var(--muted);padding:32px">Aucune ligne financière</td></tr>';
    return;
  }
  tbody.innerHTML = lines.map(l => {
    const solde      = (l.budget_alloue||0) - (l.depenses||0) + (l.revenus||0);
    const soldeTotal = solde + (l.commanditaires||0);
    const pending    = l.depenses_en_attente||0;
    const budget     = l.budget_alloue||0;
    const pct        = budget > 0 ? Math.round((l.depenses||0) / budget * 100) : 0;
    const barColor   = pct >= 100 ? 'var(--red)' : pct >= 80 ? '#e65100' : 'var(--g2)';
    const progressBar = budget > 0 ? `
      <div style="margin-top:6px;display:flex;align-items:center;gap:6px">
        <div style="flex:1;background:var(--off);border-radius:20px;height:6px;overflow:hidden;min-width:60px">
          <div style="height:100%;width:${Math.min(pct,100)}%;background:${barColor};border-radius:20px"></div>
        </div>
        <span style="font-size:.68rem;color:${barColor};font-weight:700;white-space:nowrap">${pct}%</span>
      </div>` : '';
    return `<tr>
      <td><strong>${l.activite||l.projet||l.titre}</strong><br><span style="font-size:.74rem;color:var(--muted)">${l.titre}</span>${progressBar}</td>
      <td>${fmtMoney(l.budget_alloue)}</td>
      <td style="color:var(--red);font-size:.86rem">${fmtMoney(l.depenses)}</td>
      <td style="color:#e65100;font-size:.86rem">${pending>0?'⏳ '+fmtMoney(pending):'–'}</td>
      <td style="color:var(--g2);font-size:.86rem">${fmtMoney(l.revenus)}</td>
      <td style="color:#0277bd;font-size:.86rem">${(l.commanditaires||0)>0?fmtMoney(l.commanditaires):'–'}</td>
      <td><strong style="color:${solde<0?'var(--red)':'var(--g2)'}">${fmtMoney(solde)}</strong></td>
      <td><strong style="color:${soldeTotal<0?'var(--red)':'#0277bd'}">${fmtMoney(soldeTotal)}</strong></td>
      <td>${l.statut === 'termine' ? pill('🔒 Fermé', 'bp-gray') : statusPill(l.statut)}</td>
      <td style="white-space:nowrap">
        <button class="btn btn-sm btn-ghost" onclick="viewTransactions(${l.id},'${l.titre.replace(/'/g,"\\'")}')">📊 Détails</button>
        ${can.adminOrTre() ? (
          l.statut === 'termine'
            ? (can.admin() ? `<button class="btn btn-sm btn-ghost" onclick="_finReopenLine(${l.id})" title="Rouvrir le projet">🔓 Rouvrir</button>` : '')
            : `<button class="btn btn-sm btn-ghost" onclick="_finCloseLineForm(${l.id},'${(l.activite||l.titre).replace(/'/g,"\\'")}')" title="Fermer le projet (2 signatures requises)">${l.ma_signature ? '✅' : '🔒'} Fermer (${l.nb_signatures||0}/2)</button>`
        ) : ''}
      </td>
    </tr>`;
  }).join('');
}

async function viewTransactions(lineId, titre) {
  const [transactions, allInvoices] = await Promise.all([
    api(`/finance/transactions?line_id=${lineId}`),
    api('/finance/invoices').catch(() => [])
  ]);
  const factures = allInvoices.filter(i => i.financial_line_id === lineId);
  window._txByLine = {}; transactions.forEach(t => window._txByLine[t.id] = t);
  window._txLines = window._finLines || [];

  openModal(`📊 Détails – ${escHtml(titre)}`, `
    <h4 style="margin:0 0 10px">Transactions (revenus & dépenses)</h4>
    <div class="table-wrapper" style="margin-bottom:24px"><table>
      <thead><tr><th>Date</th><th>Type</th><th>Catégorie</th><th>Montant</th><th>Description</th><th>Méthode</th>${can.adminOrTre() ? '<th>Actions</th>' : ''}</tr></thead>
      <tbody>${transactions.map(t=>`<tr>
        <td>${fmt(t.date_transaction)}</td>
        <td>${pill(t.type,t.type==='depense'?'bp-red':'bp-green')}</td>
        <td style="font-size:.78rem">${finCatLabel(t.categorie)}</td>
        <td><strong>${fmtMoney(t.montant)}</strong></td>
        <td>${escHtml(t.description||'–')}</td>
        <td>${t.methode||'–'}</td>
        ${can.adminOrTre() ? `<td style="white-space:nowrap">
          ${t.invoice_id ? '<span style="font-size:.72rem;color:var(--muted)">via facture</span>' : `
            <button class="btn btn-sm btn-ghost" onclick="openTransactionForm(window._txByLine[${t.id}],window._txLines)" title="Modifier">✏️</button>
            <button class="btn btn-sm btn-ghost" style="color:var(--red)" onclick="deleteTransaction(${t.id})" title="Supprimer">🗑</button>`}
        </td>` : ''}
      </tr>`).join('') || `<tr><td colspan="${can.adminOrTre()?7:6}" style="text-align:center">Aucune transaction</td></tr>`}</tbody>
    </table></div>

    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <h4 style="margin:0">Factures</h4>
      <button class="btn btn-ghost btn-sm" onclick="closeModal();showView('invoices')">📄 Voir toutes les factures →</button>
    </div>
    <div class="table-wrapper"><table>
      <thead><tr><th>Titre</th><th>Fournisseur</th><th>Catégorie</th><th>Montant</th><th>Date</th><th>Statut</th><th>Photo</th></tr></thead>
      <tbody>${factures.map(i=>`<tr>
        <td><strong>${escHtml(i.titre)}</strong></td>
        <td>${escHtml(i.fournisseur||'–')}</td>
        <td style="font-size:.78rem">${finCatLabel(i.categorie)}</td>
        <td>${fmtMoney(i.montant)}</td>
        <td>${fmt(i.date_facture)}</td>
        <td>${statusPill(i.statut)}</td>
        <td>${i.photo_path ? `<button type="button" onclick="openPhotoLightbox('${BASE}${i.photo_path}')" class="btn btn-sm btn-ghost">📷 Voir</button>` : '–'}</td>
      </tr>`).join('') || '<tr><td colspan="7" style="text-align:center">Aucune facture</td></tr>'}</tbody>
    </table></div>
  `);
}

function openTransactionForm(t, lines) {
  const isEdit = !!t;
  openModal(isEdit ? 'Modifier la transaction' : 'Nouvelle transaction', `
    <form id="txForm">
      <div class="form-group"><label>Type *</label>
        <select id="tx_type">
          <option value="depense" ${t?.type==='depense'?'selected':''}>Dépense</option>
          <option value="revenu" ${t?.type==='revenu'?'selected':''}>Revenu</option>
        </select></div>
      <div class="form-row">
        <div class="form-group"><label>Montant *</label><input type="number" id="tx_montant" step="0.01" value="${t?.montant??''}" required/></div>
        <div class="form-group"><label>Méthode</label>
          <select id="tx_methode">
            <option ${t?.methode==='cash'?'selected':''}>cash</option>
            <option ${t?.methode==='cheque'?'selected':''}>cheque</option>
            <option ${t?.methode==='virement'?'selected':''}>virement</option>
            <option ${t?.methode==='carte'?'selected':''}>carte</option>
          </select></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Ligne financière</label>
          <select id="tx_line"><option value="">– Générale –</option>
            ${lines.map(l=>`<option value="${l.id}" ${t?.financial_line_id===l.id?'selected':''}>${l.activite||l.titre}</option>`).join('')}
          </select></div>
        <div class="form-group"><label>Catégorie</label>
          <select id="tx_cat">${finCatOptions(t?.categorie||'autre')}</select></div>
      </div>
      <div class="form-group"><label>Description</label><textarea id="tx_desc" rows="2">${escHtml(t?.description||'')}</textarea></div>
      <div class="form-group"><label>Référence</label><input id="tx_ref" placeholder="N° chèque, reçu..." value="${escHtml(t?.reference||'')}"/></div>
      <div class="form-actions">
        ${isEdit ? `<button type="button" class="btn btn-ghost" style="color:var(--red)" onclick="deleteTransaction(${t.id})">🗑 Supprimer</button>` : ''}
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Enregistrer</button>
      </div>
    </form>
  `);
  document.getElementById('txForm').onsubmit = async e => {
    e.preventDefault();
    const body = { type:document.getElementById('tx_type').value, montant:parseFloat(document.getElementById('tx_montant').value),
      methode:document.getElementById('tx_methode').value, description:document.getElementById('tx_desc').value,
      reference:document.getElementById('tx_ref').value, categorie:document.getElementById('tx_cat').value,
      financial_line_id:parseInt(document.getElementById('tx_line').value)||null };
    try {
      if (isEdit) await api(`/finance/transactions/${t.id}`, { method:'PUT', body:JSON.stringify(body) });
      else await api('/finance/transactions', { method:'POST', body:JSON.stringify(body) });
      closeModal(); toast(isEdit ? 'Transaction mise à jour' : 'Transaction enregistrée');
      finance();
    } catch(ex) { toast(ex.message,'error'); }
  };
}

async function deleteTransaction(id) {
  if (!confirm('Supprimer cette transaction ? Son effet sur le solde sera annulé.')) return;
  try {
    await api(`/finance/transactions/${id}`, { method:'DELETE' });
    closeModal(); toast('Transaction supprimée'); finance();
  } catch(ex) { toast(ex.message, 'error'); }
}

// ── Fermeture d'un projet/activité (2 signatures requises, comme les rencontres comité) ──
async function _finCloseLineForm(lineId, titre) {
  const sigs = await api('/finance/lines/' + lineId + '/signatures').catch(() => []);
  openModal('🔒 Fermer le projet — ' + escHtml(titre), `
    <p style="font-size:.85rem;color:var(--muted);margin-bottom:12px">
      La fermeture d'un projet nécessite <strong>2 signatures</strong> de membres du comité (trésorière ou admin).<br>
      <strong style="color:#1b5e20">⚠️ Une fois 2 signatures obtenues, le projet sera fermé et les lignes financières verrouillées.</strong></p>
    ${sigs.length ? `<div style="margin-bottom:12px">${sigs.map(s => `<div style="font-size:.8rem;padding:6px 0;border-bottom:1px solid var(--border)">✅ <strong>${escHtml(s.nom_signataire)}</strong> — ${fmt(s.date_signature)}</div>`).join('')}</div>` : ''}
    <canvas id="finSigCanvas" width="540" height="160" style="border:1px solid #ccc;border-radius:8px;cursor:crosshair;display:block;width:100%;touch-action:none"></canvas>
    <div style="margin-top:8px;display:flex;gap:8px">
      <button class="btn btn-sm btn-ghost" onclick="_clearFinCanvas()">🗑 Effacer</button>
    </div>
    <div style="margin-top:16px;display:flex;gap:8px">
      <button class="btn btn-primary" onclick="_saveFinLineSignature(${lineId})">✅ Signer</button>
      <button class="btn btn-outline" onclick="closeModal()">Annuler</button>
    </div>
  `);
  setTimeout(() => {
    const canvas = document.getElementById('finSigCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let drawing = false;
    const getPos = e => {
      const r = canvas.getBoundingClientRect();
      const src = e.touches ? e.touches[0] : e;
      return { x: (src.clientX - r.left) * (canvas.width / r.width), y: (src.clientY - r.top) * (canvas.height / r.height) };
    };
    canvas.addEventListener('mousedown', e => { drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('mousemove', e => { if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); });
    canvas.addEventListener('mouseup', () => { drawing = false; });
    canvas.addEventListener('touchstart', e => { e.preventDefault(); drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }, { passive: false });
    canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); }, { passive: false });
    canvas.addEventListener('touchend', () => { drawing = false; });
  }, 50);
}

function _clearFinCanvas() {
  const c = document.getElementById('finSigCanvas');
  if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
}

async function _saveFinLineSignature(lineId) {
  const canvas = document.getElementById('finSigCanvas');
  if (!canvas) return;
  const blank = document.createElement('canvas'); blank.width = canvas.width; blank.height = canvas.height;
  if (canvas.toDataURL() === blank.toDataURL()) return toast('Veuillez dessiner votre signature', 'error');
  const signature_data = canvas.toDataURL('image/png');
  try {
    const r = await api('/finance/lines/' + lineId + '/close-signature', { method:'POST', body: JSON.stringify({ signature_data }) });
    closeModal();
    if (r.ferme) toast('🔒 Projet fermé : ' + r.nb_signatures + ' signatures collectées');
    else toast('✅ Signature enregistrée (' + r.nb_signatures + '/2 pour fermer)');
    finance();
  } catch(e) { toast(e.message, 'error'); }
}

async function _finReopenLine(lineId) {
  if (!confirm('Rouvrir ce projet ? Les signatures seront effacées.')) return;
  try { await api('/finance/lines/' + lineId + '/reopen', { method:'POST' }); toast('Projet rouvert'); finance(); }
  catch(e) { toast(e.message, 'error'); }
}

