// ══ MES BILLETS ════════════════════════════════════════════════════════════════
async function mes_billets() {
  const tickets = await api('/tickets/my');
  const now = Date.now();
  setContent(`
    <div class="page-header">
      <div><h2>🎟 Mes billets</h2><p>Vos billets et QR codes pour les activités</p></div>
    </div>
    ${tickets.length ? `
    <div class="m-chiprow" id="ticketChips" style="margin-bottom:16px">
      <span class="m-chip active" data-f="" onclick="_ticketChipClick(this)">Tous</span>
      <span class="m-chip" data-f="avenir" onclick="_ticketChipClick(this)">À venir</span>
      <span class="m-chip" data-f="passe" onclick="_ticketChipClick(this)">Passés</span>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px" id="ticketsGrid">
      ${tickets.map(t => {
        const upcoming = t.date_debut && new Date(t.date_debut).getTime() >= now;
        return `
        <div class="table-card ticket-entry" data-when="${upcoming?'avenir':'passe'}" style="overflow:hidden">
          <div style="background:linear-gradient(135deg,var(--g1),var(--g2));padding:16px 20px;color:#fff">
            <div style="font-weight:700;font-size:1rem">${t.activite}</div>
            <div style="font-size:.78rem;opacity:.8;margin-top:4px">📅 ${fmt(t.date_debut)} · 📍 ${t.lieu||'–'}</div>
          </div>
          <div style="padding:16px;display:flex;gap:16px;align-items:center">
            <img src="${BASE}/api/tickets/${t.id}/qr?token=${encodeURIComponent(TOKEN)}" alt="QR" style="width:110px;height:110px;border:2px solid var(--border);border-radius:8px"/>
            <div>
              <div style="font-size:.82rem;color:var(--muted);margin-bottom:6px">
                ${t.table_numero ? `🪑 Table ${t.table_numero}` : '🪑 Table à confirmer'}<br/>
                ${t.vendeur_nom ? `👤 Vendu par ${t.vendeur_nom}` : '🌐 Acheté en ligne'}<br/>
                💰 $${(t.prix||0).toFixed(2)}
              </div>
              <button class="btn btn-sm btn-outline" onclick="window.open('${BASE}/api/tickets/${t.id}/qr?token=${encodeURIComponent(TOKEN)}','_blank')">📥 Télécharger QR</button>
            </div>
          </div>
          <div style="background:var(--off);padding:10px 16px;font-size:.72rem;color:var(--muted);font-family:monospace;border-top:1px solid var(--border)">
            ${t.qr_data ? t.qr_data.replace(/\n/g,'<br/>') : '–'}
          </div>
        </div>
      `;}).join('')}
    </div>` : `
    <div class="empty-state">
      <div class="es-icon">🎟</div>
      <p>Vous n'avez pas encore de billet.<br/>Inscrivez-vous à une activité pour obtenir votre QR code.</p>
    </div>`}
  `);
}

function _ticketChipClick(chip) {
  chip.parentElement.querySelectorAll('.m-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  const f = chip.dataset.f;
  document.querySelectorAll('.ticket-entry').forEach(el => {
    el.style.display = (!f || el.dataset.when === f) ? '' : 'none';
  });
}

// ══ DOCUMENTS OFFICIELS ══════════════════════════════════════════════════════
async function documents_mgmt() {
  const canUpload = can.adminOrSec();
  const docs = await api('/documents').catch(() => []);
  const CATS = { proces_verbaux:'📋 Procès-verbaux', statuts:'📜 Statuts & Règlements', formulaires:'📄 Formulaires officiels', rapports:'📊 Rapports annuels', autre:'📁 Autres documents' };
  const grouped = {};
  docs.forEach(d => { const c = d.categorie||'autre'; if(!grouped[c]) grouped[c]=[]; grouped[c].push(d); });
  const docIcon = m => { if(!m)return'📄'; if(m.includes('pdf'))return'📕'; if(m.includes('word')||m.includes('document'))return'📘'; if(m.includes('sheet')||m.includes('excel'))return'📗'; if(m.includes('image'))return'🖼️'; return'📄'; };
  const fmtSize = b => { if(!b)return''; if(b<1024)return b+'B'; if(b<1048576)return(b/1024).toFixed(1)+'KB'; return(b/1048576).toFixed(1)+'MB'; };
  setContent(`
    <div class="page-header">
      <div><h2>📁 Documents officiels</h2><p>Statuts, procès-verbaux et documents de l'association</p></div>
      ${canUpload ? '<div class="page-actions"><button class="btn btn-primary" onclick="documentUploadForm()">+ Ajouter</button></div>' : ''}
    </div>
    ${!docs.length ? '<div class="empty-state"><div class="es-icon">📁</div><p>Aucun document pour le moment.</p></div>' :
      Object.entries(CATS).filter(([k]) => grouped[k]?.length).map(([cat, label]) => `
        <div class="table-card" style="margin-bottom:20px">
          <div class="table-card-header"><h3>${label}</h3></div>
          <div style="padding:4px 16px">
            ${grouped[cat].map(d => {
              const signed = !!d.date_ma_signature;
              const sigBadge = signed
                ? `<span style="display:inline-flex;align-items:center;gap:4px;background:#e8f5e9;color:#1b5e20;border-radius:20px;padding:2px 10px;font-size:.72rem;font-weight:600">✅ Signé le ${fmt(d.date_ma_signature)}</span>`
                : '';
              const countBadge = d.nb_signatures > 0
                ? `<span style="display:inline-flex;align-items:center;gap:3px;background:#e3f2fd;color:#1565c0;border-radius:20px;padding:2px 8px;font-size:.7rem;font-weight:600">🖊 ${d.nb_signatures} signature${d.nb_signatures>1?'s':''}</span>`
                : '';
              return `
              <div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)">
                <div style="font-size:1.6rem;flex-shrink:0">${docIcon(d.mime_type)}</div>
                <div style="flex:1;min-width:0">
                  <div style="font-weight:600;font-size:.9rem">${escHtml(d.nom)}</div>
                  ${d.description ? `<div style="font-size:.78rem;color:var(--muted)">${escHtml(d.description)}</div>` : ''}
                  <div style="font-size:.72rem;color:var(--muted);margin-top:2px">${escHtml(d.uploader||'?')} · ${fmt(d.date_upload)} · ${fmtSize(d.taille)}</div>
                  ${sigBadge || countBadge ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:5px">${sigBadge}${countBadge}</div>` : ''}
                </div>
                <div style="display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;align-items:center">
                  <a href="/api/documents/${d.id}/download?token=${TOKEN}" class="btn btn-outline btn-sm" download>⬇ Télécharger</a>
                  ${d.nb_signatures > 0 ? `<a href="/api/documents/${d.id}/attestation?token=${TOKEN}" target="_blank" class="btn btn-outline btn-sm" style="color:#1b5e20;border-color:#1b5e20">🔏 Attestation</a>` : ''}
                  <button class="btn btn-sm btn-ghost" onclick="openSignatureModal(${d.id},'${escHtml(d.nom).replace(/'/g,"\\'")}')">✍️ ${signed ? 'Re-signer' : 'Signer'}</button>
                  ${canUpload ? `<button class="btn btn-sm btn-ghost" style="color:var(--red)" onclick="documentDelete(${d.id})">🗑</button>` : ''}
                </div>
              </div>`;}).join('')}
          </div>
        </div>`).join('')}`);
}
async function documentUploadForm() {
  openModal('📁 Nouveau document', `
    <div class="form-group"><label class="form-label">Nom du document *</label><input id="doc_nom" class="form-input" placeholder="ex: Procès-verbal AG 2026"/></div>
    <div class="form-group"><label class="form-label">Description</label><input id="doc_desc" class="form-input" placeholder="Optionnel"/></div>
    <div class="form-group"><label class="form-label">Catégorie</label>
      <select id="doc_cat" class="form-input">
        <option value="proces_verbaux">📋 Procès-verbaux</option>
        <option value="statuts">📜 Statuts & Règlements</option>
        <option value="formulaires">📄 Formulaires officiels</option>
        <option value="rapports">📊 Rapports annuels</option>
        <option value="autre">📁 Autre</option>
      </select>
    </div>
    <div class="form-group"><label class="form-label">Fichier * <span style="font-weight:400;color:var(--muted)">(PDF, Word, Excel, image — max 50 Mo)</span></label>
      <input type="file" id="doc_fichier" class="form-input" accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.zip"/></div>
    <div style="display:flex;gap:10px">
      <button class="btn btn-primary" onclick="documentSave()">⬆ Téléverser</button>
      <button class="btn btn-outline" onclick="closeModal()">Annuler</button>
    </div>`);
}
async function documentSave() {
  const fichier = document.getElementById('doc_fichier')?.files[0];
  if (!fichier) { toast('Choisissez un fichier', true); return; }
  const fd = new FormData();
  fd.append('fichier', fichier);
  fd.append('nom', document.getElementById('doc_nom').value || fichier.name);
  fd.append('description', document.getElementById('doc_desc').value || '');
  fd.append('categorie', document.getElementById('doc_cat').value || 'autre');
  try {
    toast('Téléversement en cours…');
    await fetch('/api/documents', { method:'POST', headers:{ Authorization:'Bearer '+TOKEN }, body:fd });
    closeModal(); documents_mgmt(); toast('✅ Document ajouté !');
  } catch(e) { toast('Erreur : '+e.message, true); }
}
async function documentDelete(id) {
  if (!confirm('Supprimer ce document définitivement ?')) return;
  await api('/documents/'+id, { method:'DELETE' });
  documents_mgmt(); toast('Document supprimé');
}

// ══ CORRESPONDANCE OFFICIELLE (secrétariat) ═══════════════════════════════════
const CORR_METHODES = { courriel:'✉️ Courriel', poste:'📮 Poste', main_propre:'🤝 En main propre', telephone:'📞 Téléphone' };
const CORR_STATUTS = { classe:'Classé', en_attente_reponse:'⏳ En attente de réponse', repondu:'✅ Répondu' };

// ══ GOUVERNANCE — hub fusionné (Décisions / Politiques / Délégation / Correspondance) ═
async function gouvernanceHubView(tab) {
  tab = tab || window._gouvernanceTab || 'decisions';
  window._gouvernanceTab = tab;
  setContent(`
    <div class="page-header"><div><h2>📒 Gouvernance</h2><p>Registres et dossiers administratifs du comité</p></div></div>
    <div class="page-tabs-inline">
      <button class="ptab ${tab==='decisions'?'active':''}" onclick="gouvernanceHubView('decisions')">Décisions</button>
      <button class="ptab ${tab==='politiques'?'active':''}" onclick="gouvernanceHubView('politiques')">Politiques</button>
      <button class="ptab ${tab==='delegation'?'active':''}" onclick="gouvernanceHubView('delegation')">Délégation présidence</button>
      <button class="ptab ${tab==='correspondance'?'active':''}" onclick="gouvernanceHubView('correspondance')">Correspondance</button>
    </div>
    <div id="gouvernanceHubBody"></div>
  `);
  if (tab === 'politiques') await policiesView();
  else if (tab === 'delegation') await presidenceDelegationView();
  else if (tab === 'correspondance') await correspondance();
  else await decisionRegistryView();
}

async function correspondance() {
  if (!document.getElementById('gouvernanceHubBody')) { return gouvernanceHubView('correspondance'); }
  const canEdit = can.adminOrSec();
  const data = await api('/correspondance').catch(() => []);
  window._corrById = {}; data.forEach(c => window._corrById[c.id] = c);
  document.getElementById('gouvernanceHubBody').innerHTML = `
    ${canEdit ? `<div class="page-actions" style="margin-bottom:14px"><button class="btn btn-primary" onclick="openCorrespondanceForm()">+ Nouvelle entrée</button></div>` : ''}
    <div class="table-card">
      <div class="table-card-header" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
        <h3 style="margin:0">Registre</h3>
        <input id="corrSearch" type="text" class="members-search" style="max-width:260px;margin:0" placeholder="🔍 Rechercher…" oninput="filterCorrespondance()"/>
        <select id="corrType" class="members-filter" onchange="filterCorrespondance()" style="margin:0">
          <option value="">Tous types</option>
          <option value="sortant">Sortant</option>
          <option value="entrant">Entrant</option>
        </select>
      </div>
      <div class="table-wrapper"><table>
        <thead><tr><th>Date</th><th>Type</th><th>Destinataire / Expéditeur</th><th>Objet</th><th>Méthode</th><th>Statut</th><th>Fichier</th>${canEdit ? '<th>Actions</th>' : ''}</tr></thead>
        <tbody id="corrBody"></tbody>
      </table></div>
    </div>
  `;
  window._corrAll = data;
  filterCorrespondance();
}

function filterCorrespondance() {
  const q = (document.getElementById('corrSearch')?.value || '').toLowerCase().trim();
  const type = document.getElementById('corrType')?.value || '';
  const data = (window._corrAll || []).filter(c => {
    if (type && c.type !== type) return false;
    if (q && !`${c.objet} ${c.destinataire||''} ${c.expediteur||''} ${c.resume||''}`.toLowerCase().includes(q)) return false;
    return true;
  });
  renderCorrespondance(data);
}

function renderCorrespondance(data) {
  const tbody = document.getElementById('corrBody');
  if (!tbody) return;
  const canEdit = can.adminOrSec();
  if (!data.length) {
    tbody.innerHTML = `<tr><td colspan="${canEdit?8:7}" style="text-align:center;color:var(--muted);padding:32px">Aucune correspondance enregistrée</td></tr>`;
    return;
  }
  tbody.innerHTML = data.map(c => `<tr>
    <td>${fmt(c.date_correspondance)}</td>
    <td>${pill(c.type==='sortant'?'Sortant':'Entrant', c.type==='sortant'?'bp-blue':'bp-green')}</td>
    <td>${escHtml(c.type==='sortant' ? (c.destinataire||'–') : (c.expediteur||'–'))}</td>
    <td><strong>${escHtml(c.objet)}</strong>${c.resume ? `<br><span style="font-size:.74rem;color:var(--muted)">${escHtml(c.resume)}</span>` : ''}</td>
    <td style="font-size:.82rem">${CORR_METHODES[c.methode]||c.methode}</td>
    <td>${pill(CORR_STATUTS[c.statut]||c.statut, c.statut==='en_attente_reponse'?'bp-orange':(c.statut==='repondu'?'bp-green':'bp-gray'))}</td>
    <td>${c.fichier_path ? `<a href="/api/correspondance/${c.id}/download?token=${TOKEN}" class="btn btn-sm btn-ghost" download>📎 Voir</a>` : '–'}</td>
    ${canEdit ? `<td style="white-space:nowrap">
      <button class="btn btn-sm btn-ghost" onclick="openCorrespondanceForm(window._corrById[${c.id}])" title="Modifier">✏️</button>
      <button class="btn btn-sm btn-ghost" style="color:var(--red)" onclick="correspondanceDelete(${c.id})" title="Supprimer">🗑</button>
    </td>` : ''}
  </tr>`).join('');
}

function openCorrespondanceForm(existing) {
  const isEdit = !!existing;
  openModal(isEdit ? 'Modifier la correspondance' : 'Nouvelle correspondance', `
    <form id="corrForm" enctype="multipart/form-data">
      <div class="form-row">
        <div class="form-group"><label>Type *</label>
          <select id="corr_type" onchange="document.getElementById('corr_dest_row').style.display=this.value==='sortant'?'':'none';document.getElementById('corr_exp_row').style.display=this.value==='entrant'?'':'none';">
            <option value="sortant" ${existing?.type==='sortant'?'selected':''}>Sortant (envoyé par l'AHH)</option>
            <option value="entrant" ${existing?.type==='entrant'?'selected':''}>Entrant (reçu par l'AHH)</option>
          </select></div>
        <div class="form-group"><label>Date *</label><input type="date" id="corr_date" value="${(existing?.date_correspondance||new Date().toISOString()).substring(0,10)}" required/></div>
      </div>
      <div class="form-group" id="corr_dest_row" style="display:${!existing||existing.type==='sortant'?'':'none'}">
        <label>Destinataire</label><input id="corr_dest" value="${escHtml(existing?.destinataire||'')}" placeholder="ex: Ville de Hamilton"/></div>
      <div class="form-group" id="corr_exp_row" style="display:${existing?.type==='entrant'?'':'none'}">
        <label>Expéditeur</label><input id="corr_exp" value="${escHtml(existing?.expediteur||'')}" placeholder="ex: Ville de Hamilton"/></div>
      <div class="form-group"><label>Objet *</label><input id="corr_objet" value="${escHtml(existing?.objet||'')}" required/></div>
      <div class="form-group"><label>Résumé</label><textarea id="corr_resume" rows="2">${escHtml(existing?.resume||'')}</textarea></div>
      <div class="form-row">
        <div class="form-group"><label>Méthode</label>
          <select id="corr_methode">${Object.entries(CORR_METHODES).map(([k,l])=>`<option value="${k}" ${existing?.methode===k?'selected':''}>${l}</option>`).join('')}</select></div>
        <div class="form-group"><label>Statut</label>
          <select id="corr_statut">${Object.entries(CORR_STATUTS).map(([k,l])=>`<option value="${k}" ${existing?.statut===k?'selected':''}>${l}</option>`).join('')}</select></div>
      </div>
      <div class="form-group"><label>Fichier / scan (optionnel)</label>
        ${existing?.fichier_path ? `<div style="margin-bottom:6px"><a href="/api/correspondance/${existing.id}/download?token=${TOKEN}" class="btn btn-sm btn-ghost" download>📎 Fichier actuel</a></div>` : ''}
        <input type="file" id="corr_fichier" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg"/></div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Enregistrer</button>
      </div>
    </form>
  `);
  document.getElementById('corrForm').onsubmit = async e => {
    e.preventDefault();
    const fd = new FormData();
    fd.append('type', document.getElementById('corr_type').value);
    fd.append('date_correspondance', document.getElementById('corr_date').value);
    fd.append('destinataire', document.getElementById('corr_dest').value);
    fd.append('expediteur', document.getElementById('corr_exp').value);
    fd.append('objet', document.getElementById('corr_objet').value.trim());
    fd.append('resume', document.getElementById('corr_resume').value);
    fd.append('methode', document.getElementById('corr_methode').value);
    fd.append('statut', document.getElementById('corr_statut').value);
    const fichier = document.getElementById('corr_fichier').files[0];
    if (fichier) fd.append('fichier', fichier);
    try {
      const url = '/correspondance' + (isEdit ? '/' + existing.id : '');
      await apiForm(url, fd, isEdit ? 'PUT' : 'POST');
      closeModal(); toast(isEdit ? 'Correspondance mise à jour' : 'Correspondance enregistrée'); correspondance();
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function correspondanceDelete(id) {
  if (!confirm('Supprimer cette entrée de correspondance ?')) return;
  try { await api('/correspondance/'+id, { method:'DELETE' }); toast('Correspondance supprimée'); correspondance(); }
  catch(ex) { toast(ex.message, 'error'); }
}

// ══ COMMANDITAIRES ═══════════════════════════════════════════════════════════
// ══ VITRINE PUBLIQUE — hub fusionné (Commanditaires / Équipe dirigeante) ══════
async function vitrineHubView(tab) {
  tab = tab || window._vitrineTab || 'sponsors';
  window._vitrineTab = tab;
  setContent(`
    <div class="page-header"><div><h2>🤝 Vitrine publique</h2><p>Contenu affiché sur le site public de l'association</p></div></div>
    <div class="page-tabs-inline">
      <button class="ptab ${tab==='sponsors'?'active':''}" onclick="vitrineHubView('sponsors')">Commanditaires</button>
      <button class="ptab ${tab==='equipe'?'active':''}" onclick="vitrineHubView('equipe')">Équipe dirigeante</button>
    </div>
    <div id="vitrineHubBody"></div>
  `);
  if (tab === 'equipe') await equipe_mgmt();
  else await sponsors_mgmt();
}

async function sponsors_mgmt() {
  if (!document.getElementById('vitrineHubBody')) { return vitrineHubView('sponsors'); }
  const canEdit = can.adminOrSec();
  const sponsors = await api('/sponsors/all').catch(() => []);
  window._sponsors_cache = sponsors;
  const CAT_LABELS = { platine:'Platine', or:'Or', argent:'Argent', bronze:'Bronze' };
  const CAT_COLORS = { platine:'#B0BEC5', or:'#F9A825', argent:'#9E9E9E', bronze:'#BF8A30' };

  document.getElementById('vitrineHubBody').innerHTML = `
    <div class="page-actions" style="margin-bottom:10px">
      <p style="flex:1;margin:0;color:var(--muted);font-size:.85rem">Gérez les commanditaires affichés sur le site public.</p>
      ${canEdit ? '<button class="btn btn-primary" onclick="sponsorForm()">+ Ajouter</button>' : ''}
    </div>
    <div id="sponsorsList">
      ${sponsors.length === 0
        ? '<p style="color:var(--muted);text-align:center;padding:40px 0">Aucun commanditaire pour l\'instant.</p>'
        : sponsors.map(s => `
          <div class="table-card" style="display:flex;gap:20px;align-items:flex-start;flex-wrap:wrap;margin-bottom:16px;opacity:${s.actif?1:.5}">
            ${s.photo_url
              ? `<img src="${s.photo_url}" alt="${s.nom}" style="width:90px;height:120px;object-fit:cover;border-radius:10px;flex-shrink:0;box-shadow:0 4px 16px rgba(0,0,0,.15)">`
              : `<div style="width:90px;height:120px;border-radius:10px;background:var(--bg2);display:flex;align-items:center;justify-content:center;font-size:2rem;flex-shrink:0">🤝</div>`}
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px">
                <strong style="font-size:1.1rem">${s.nom}</strong>
                <span style="background:${CAT_COLORS[s.categorie]||'#9E9E9E'};color:#fff;font-size:.72rem;font-weight:700;border-radius:20px;padding:2px 10px">${CAT_LABELS[s.categorie]||s.categorie}</span>
                ${!s.actif ? '<span style="background:#ccc;color:#555;font-size:.72rem;font-weight:700;border-radius:20px;padding:2px 10px">Inactif</span>' : ''}
              </div>
              ${s.description ? `<p style="color:var(--muted);font-size:.9rem;margin:0 0 6px">${s.description}</p>` : ''}
              ${s.site_web ? `<a href="${s.site_web}" target="_blank" rel="noopener" style="font-size:.85rem;color:var(--accent)">${s.site_web}</a>` : ''}
            </div>
            ${canEdit ? `
            <div style="display:flex;flex-direction:column;gap:6px;flex-shrink:0">
              <button class="btn btn-outline btn-sm" onclick="sponsorForm(${s.id})">✏️ Modifier</button>
              <button class="btn btn-outline btn-sm" onclick="sponsorToggle(${s.id},${s.actif?0:1})">${s.actif?'⏸ Masquer':'▶ Afficher'}</button>
              <div style="display:flex;gap:4px">
                <button class="btn btn-outline btn-sm" onclick="sponsorOrdre(${s.id},'up')" title="Monter">↑</button>
                <button class="btn btn-outline btn-sm" onclick="sponsorOrdre(${s.id},'down')" title="Descendre">↓</button>
              </div>
              <button class="btn btn-sm" style="background:#f44336;color:#fff" onclick="sponsorDelete(${s.id},'${s.nom.replace(/'/g,"\\'").replace(/"/g,'\\"')}')">🗑 Supprimer</button>
            </div>` : ''}
          </div>`).join('')}
    </div>
  `;
}

function sponsorForm(id) {
  const sp = id ? window._sponsors_cache?.find(s => s.id === id) : null;
  const CAT = ['platine','or','argent','bronze'];
  openModal(id ? 'Modifier le commanditaire' : 'Ajouter un commanditaire', `
    <form id="sponsorFrm" enctype="multipart/form-data">
      <div class="form-group">
        <label>Nom *</label>
        <input name="nom" class="form-control" required value="${sp?.nom||''}">
      </div>
      <div class="form-group">
        <label>Description</label>
        <textarea name="description" class="form-control" rows="2">${sp?.description||''}</textarea>
      </div>
      <div class="form-group">
        <label>Site web</label>
        <input name="site_web" class="form-control" type="url" placeholder="https://..." value="${sp?.site_web||''}">
      </div>
      <div class="form-group">
        <label>Catégorie</label>
        <select name="categorie" class="form-control">
          ${CAT.map(c => `<option value="${c}" ${(sp?.categorie||'or')===c?'selected':''}>${c.charAt(0).toUpperCase()+c.slice(1)}</option>`).join('')}
        </select>
      </div>
      <div class="form-group">
        <label>Logo / Affiche (image)</label>
        ${sp?.photo_url ? `<img src="${sp.photo_url}" style="width:80px;height:106px;object-fit:cover;border-radius:8px;margin-bottom:8px;display:block">` : ''}
        <input type="file" name="photo" class="form-control" accept="image/*">
      </div>
      <button type="button" class="btn btn-primary" onclick="sponsorSave(${id||'null'})">💾 Enregistrer</button>
    </form>
  `);
}

async function sponsorSave(id) {
  const frm = document.getElementById('sponsorFrm');
  if (!frm.nom.value.trim()) { toast('Le nom est obligatoire','err'); return; }
  const fd = new FormData(frm);
  const url = API + (id ? '/sponsors/'+id : '/sponsors');
  const method = id ? 'PUT' : 'POST';
  try {
    const res = await fetch(url, { method, headers: { Authorization: `Bearer ${TOKEN}` }, body: fd });
    const data = await res.json().catch(() => null);
    if (!res.ok) { toast((data?.error || 'Erreur '+res.status), 'err'); return; }
    closeModal(); sponsors_mgmt(); toast(id?'Commanditaire mis à jour':'Commanditaire ajouté');
  } catch(e) { toast('Erreur réseau: '+e.message, 'err'); }
}

async function sponsorToggle(id, actif) {
  const fd = new FormData();
  fd.append('actif', actif);
  await fetch(API+'/sponsors/'+id, { method:'PUT', headers:{ Authorization:`Bearer ${TOKEN}` }, body:fd }).catch(() => null);
  sponsors_mgmt();
}

async function sponsorOrdre(id, direction) {
  await api('/sponsors/'+id+'/ordre', { method:'PATCH', body:JSON.stringify({direction}) }).catch(() => null);
  sponsors_mgmt();
}

async function sponsorDelete(id, nom) {
  if (!confirm('Supprimer le commanditaire «'+nom+'» ?')) return;
  await api('/sponsors/'+id, { method:'DELETE' });
  sponsors_mgmt(); toast('Commanditaire supprimé');
}

