// ── Coordinateurs des dons — délégation d'accès au module sans rôle comité ───
async function _donsCoordinateursTabHtml() {
  let delegations = [];
  try { delegations = await api('/dons/delegations'); } catch(e) {}

  return `
    <div class="table-card" style="margin-bottom:18px">
      <div class="table-card-header"><h3>Nouveau coordinateur</h3></div>
      <div style="padding:16px">
        <p style="font-size:.85rem;color:var(--muted);margin-bottom:12px">Un coordinateur peut valider les foyers, gérer le stock et les créneaux, scanner au comptoir et consulter le journal — sans avoir de rôle comité et sans accès au reste du site (finances, autres membres, etc.). La création ou la mise en pause du programme reste réservée au comité.</p>
        <div class="form-row">
          <div class="form-group" style="position:relative">
            <label>Membre</label>
            <input id="dcSearch" autocomplete="off" placeholder="Tapez un nom..." oninput="_taskSearchMember(this.value);document.getElementById('dcDropdown').id='taskAssigneDropdown'">
            <input id="dcUserId" type="hidden">
            <div id="dcDropdown" style="position:absolute;top:100%;left:0;right:0;z-index:50;background:#fff;border:1px solid #ddd;border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.15);max-height:180px;overflow-y:auto;display:none"></div>
          </div>
          <div class="form-group">
            <label>Expiration (optionnel)</label>
            <input type="datetime-local" id="dcExpiration">
          </div>
        </div>
        <button class="btn btn-primary" onclick="_dcCreate()">Désigner comme coordinateur</button>
      </div>
    </div>

    <div class="table-card">
      <div class="table-card-header"><h3>Coordinateurs actifs (${delegations.length})</h3></div>
      <div class="table-wrapper"><table>
        <thead><tr><th>Membre</th><th>Désigné par</th><th>Expiration</th><th>Actions</th></tr></thead>
        <tbody>
          ${delegations.length ? delegations.map(d => `<tr>
            <td><strong>${escHtml(d.prenom)} ${escHtml(d.nom)}</strong><br><span style="font-size:.75rem;color:var(--muted)">${escHtml(d.email||'')}</span></td>
            <td>${_donsFmtDT(d.date_creation)}</td>
            <td>${d.date_expiration ? _donsFmtDT(d.date_expiration) : 'Illimitée'}</td>
            <td><button class="btn btn-ghost btn-sm" style="color:#c62828" onclick="_dcRevoke(${d.id})">Révoquer</button></td>
          </tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--muted);padding:24px">Aucun coordinateur actif</td></tr>'}
        </tbody>
      </table></div>
    </div>
  `;
}

function _dcInitDropdown() {
  setTimeout(() => {
    const dd = document.getElementById('dcDropdown');
    if (dd) {
      dd.id = 'taskAssigneDropdown';
      window._taskSelectMember = function(id, nom) {
        document.getElementById('dcUserId').value = id;
        document.getElementById('dcSearch').value = nom;
        document.getElementById('taskAssigneDropdown').style.display = 'none';
      };
    }
  }, 100);
}

async function _dcCreate() {
  const userId = document.getElementById('dcUserId')?.value;
  const expiration = document.getElementById('dcExpiration')?.value || null;
  if (!userId) { toast('Sélectionnez un membre', true); return; }
  try {
    await api('/dons/delegations', { method:'POST', body: JSON.stringify({ user_id: parseInt(userId), date_expiration: expiration }) });
    toast('✅ Coordinateur désigné');
    donsMgmtView();
  } catch(e) { toast(e.message, true); }
}

async function _dcRevoke(id) {
  if (!confirm('Révoquer ce coordinateur ?')) return;
  try {
    await api('/dons/delegations/' + id, { method:'DELETE' });
    toast('Coordinateur révoqué');
    donsMgmtView();
  } catch(e) { toast(e.message, true); }
}

// ══════════════════════════════════════════════════════════════════════════════
// PROGRAMME DE DONS — écran de scan / retrait (temps réel multi-postes)
// ══════════════════════════════════════════════════════════════════════════════

async function donsScanView() {
  if (window._donsScanner) { try { await window._donsScanner.stop(); } catch {} window._donsScanner = null; }
  if (window._donsStream)  { window._donsStream.getTracks().forEach(t => t.stop()); window._donsStream = null; }
  if (window._donsAnimFrame) { cancelAnimationFrame(window._donsAnimFrame); window._donsAnimFrame = null; }

  let programmes = [];
  try { programmes = await api('/dons/programmes'); } catch(e) {}
  if (!programmes.length) {
    const actif = await api('/dons/programme-actif').catch(() => null);
    programmes = actif ? [actif] : [];
  }
  if (!window._donsProgId && programmes.length) window._donsProgId = programmes[0].id;

  if (!programmes.length) {
    setContent(`<div class="page-header"><div><h2>📷 Scanner — Retrait de dons</h2></div></div>
      <div class="empty-state"><div class="es-icon">🎁</div><p>Aucun programme de dons actif.</p></div>`);
    return;
  }

  setContent(`
    <div class="page-header"><div><h2>📷 Scanner — Retrait de dons</h2><p>Scannez la carte de n'importe quel membre validé du foyer</p></div></div>

    ${programmes.length > 1 ? `
    <div class="form-group" style="max-width:340px;margin-bottom:14px">
      <label>Programme</label>
      <select onchange="window._donsProgId=parseInt(this.value)">
        ${programmes.map(p => `<option value="${p.id}" ${p.id===window._donsProgId?'selected':''}>${escHtml(p.nom)}</option>`).join('')}
      </select>
    </div>` : ''}

    <div style="display:flex;flex-wrap:wrap;gap:16px;max-width:1100px">
      <div class="table-card" style="flex:1 1 280px;padding:14px">
        <h4 style="margin-bottom:8px;color:var(--g2);font-size:.9rem">📷 Caméra</h4>
        <div id="donsReaderWrap" style="border-radius:12px;overflow:hidden;background:#111;min-height:160px;max-height:40vh;position:relative">
          <video id="donsScanVideo" autoplay muted playsinline style="width:100%;display:none;border-radius:12px;max-height:40vh;object-fit:cover"></video>
          <div id="donsScanViewfinder" style="display:none;position:absolute;inset:0;align-items:center;justify-content:center;pointer-events:none">
            <div style="position:relative;width:190px;height:190px;border:2.5px solid rgba(255,255,255,.75);border-radius:14px;box-shadow:0 0 0 9999px rgba(0,0,0,.45)"></div>
          </div>
          <div id="donsReader"></div>
        </div>
        <div id="donsReaderMsg" style="display:none;padding:10px;text-align:center;font-size:.8rem;color:var(--muted)"></div>
        <div style="margin-top:14px">
          <label class="form-label">Saisie manuelle / lecteur USB</label>
          <div style="display:flex;gap:6px">
            <input id="donsScanQrInput" class="form-input" placeholder="AHH-00007-..."
              onkeydown="if(event.key==='Enter'){event.preventDefault();donsScanSearch();}"/>
            <button class="btn btn-primary" onclick="donsScanSearch()" title="Rechercher">🔍</button>
          </div>
        </div>
        <div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border)">
          <label style="display:flex;align-items:center;gap:6px;font-size:.82rem;cursor:pointer">
            <input type="checkbox" id="donsDerogCheck" onchange="document.getElementById('donsDerogMotifWrap').style.display=this.checked?'block':'none'"/>
            Dérogation (retrait exceptionnel hors cycle)
          </label>
          <div id="donsDerogMotifWrap" style="display:none;margin-top:6px">
            <input id="donsDerogMotif" class="form-input" placeholder="Motif obligatoire..."/>
          </div>
        </div>
      </div>

      <div id="donsScanResult" class="table-card" style="flex:1 1 280px;padding:20px">
        <div class="empty-state"><div class="es-icon">🎁</div><p>Scannez une carte pour enregistrer un retrait</p></div>
      </div>

      <div class="table-card" style="flex:1 1 280px;padding:14px">
        <h4 style="margin-bottom:8px;color:var(--g2);font-size:.9rem">🔴 En direct — tous les postes</h4>
        <div id="donsLiveFeed" style="max-height:400px;overflow-y:auto;font-size:.82rem">
          <p style="padding:8px;color:var(--muted)">Les scans des autres postes du comité apparaîtront ici en temps réel.</p>
        </div>
      </div>
    </div>
  `);

  if ('BarcodeDetector' in window) await _donsStartNativeScanner();
  else await _donsStartHtml5Scanner();
}

async function _donsStartNativeScanner() {
  const video = document.getElementById('donsScanVideo');
  if (!video) return;
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } }
    });
    video.srcObject = stream;
    window._donsStream = stream;
    video.style.display = 'block';
    const vf = document.getElementById('donsScanViewfinder');
    if (vf) vf.style.display = 'flex';

    const detector = new BarcodeDetector({ formats: ['qr_code'] });
    let lastValue = '', lastTime = 0;
    const loop = async () => {
      if (!document.getElementById('donsScanVideo')) return;
      try {
        if (video.readyState >= 2) {
          const codes = await detector.detect(video);
          const now = Date.now();
          if (codes.length > 0 && (codes[0].rawValue !== lastValue || now - lastTime > 3000)) {
            lastValue = codes[0].rawValue; lastTime = now;
            const inp = document.getElementById('donsScanQrInput');
            if (inp) { inp.value = lastValue; donsScanSearch(); }
          }
        }
      } catch {}
      window._donsAnimFrame = requestAnimationFrame(loop);
    };
    video.addEventListener('loadedmetadata', () => { window._donsAnimFrame = requestAnimationFrame(loop); }, { once: true });
  } catch(e) {
    console.warn('[Scanner dons natif]', e.message, '→ fallback html5-qrcode');
    await _donsStartHtml5Scanner();
  }
}

async function _donsStartHtml5Scanner() {
  if (!window.Html5Qrcode) {
    try {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = '/Public/html5-qrcode.min.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    } catch {
      const msg = document.getElementById('donsReaderMsg');
      if (msg) { msg.style.display='block'; msg.textContent='Caméra non disponible — utilisez la saisie manuelle.'; }
      return;
    }
  }
  const scanner = new Html5Qrcode('donsReader');
  window._donsScanner = scanner;
  try {
    await scanner.start(
      { facingMode: 'environment' },
      { fps: 30, qrbox: { width: 220, height: 220 }, disableFlip: false },
      (decoded) => {
        const inp = document.getElementById('donsScanQrInput');
        if (inp && inp.value !== decoded) { inp.value = decoded; donsScanSearch(); }
      },
      () => {}
    );
  } catch(e) {
    console.warn('[Scanner dons html5-qrcode]', e && e.message || e);
    const msg = document.getElementById('donsReaderMsg');
    const permissionDenied = /NotAllowedError|Permission denied/i.test(String(e && e.message || e));
    if (msg) {
      msg.style.display = 'block';
      msg.textContent = permissionDenied
        ? 'Accès à la caméra refusé — autorisez la caméra pour ce site, ou utilisez la saisie manuelle.'
        : 'Caméra non disponible — utilisez la saisie manuelle.';
    }
  }
}

let _donsScanLock = false;
async function donsScanSearch() {
  const qr = document.getElementById('donsScanQrInput')?.value?.trim();
  if (!qr || _donsScanLock) return;
  if (!window._donsProgId) { toast('Aucun programme sélectionné', true); return; }
  _donsScanLock = true;
  setTimeout(() => { _donsScanLock = false; }, 2000);

  const resultEl = document.getElementById('donsScanResult');
  if (resultEl) resultEl.innerHTML = '<div style="text-align:center;padding:32px"><div class="spinner"></div></div>';

  const derogation = document.getElementById('donsDerogCheck')?.checked;
  const motif = document.getElementById('donsDerogMotif')?.value?.trim();

  try {
    const r = await api('/dons/scan', { method:'POST', body: JSON.stringify({ qr, programme_id: window._donsProgId, derogation, motif }) });
    const detailRows = (r.detail || []).map(d => `<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--border);font-size:.85rem">
      <span>${escHtml(d.nom)}</span><span>${d.donne} / ${d.du} ${escHtml(d.unite)}</span>
    </div>`).join('');
    if (resultEl) resultEl.innerHTML = `
      <div style="text-align:center">
        <div style="font-size:2.2rem">✅</div>
        <div style="font-size:1.1rem;font-weight:800;margin-top:6px">${escHtml(r.foyer_nom)}</div>
        <div style="margin-top:6px">${pill('Retrait enregistré','bp-green')}</div>
        ${r.partiel ? `<div style="margin-top:8px">${pill('⚠️ Stock insuffisant — remise partielle','bp-orange')}</div>` : ''}
      </div>
      <div style="margin-top:16px;text-align:left">${detailRows}</div>
      <div style="margin-top:14px;font-size:.82rem;color:var(--muted);text-align:center">Prochain retrait suggéré : <strong>${r.prochain_retrait_suggere}</strong>${r.prochain_creneau ? ` (créneau : ${_donsFmtDT(r.prochain_creneau.date_heure)})` : " (aucun créneau ouvert pour l'instant)"}</div>
      ${_donsRenderFiche(r.fiche, r.correspondances)}
      ${_donsRenderRoster(r.roster, r.foyer_id)}
    `;
    const dc = document.getElementById('donsDerogCheck'); if (dc) dc.checked = false;
    const dw = document.getElementById('donsDerogMotifWrap'); if (dw) dw.style.display = 'none';
  } catch(e) {
    if (resultEl) resultEl.innerHTML = `
      <div class="empty-state"><div class="es-icon">⛔</div><p style="color:#c62828;font-weight:700">${escHtml(e.message)}</p>
      ${e.prochain_retrait ? `<p style="font-size:.85rem;color:var(--muted)">Prochain retrait possible : ${escHtml(e.prochain_retrait)}</p>` : ''}
      </div>
      ${e.fiche ? _donsRenderFiche(e.fiche, e.correspondances) : ''}
    `;
  }
  const inp = document.getElementById('donsScanQrInput');
  if (inp) inp.value = '';
}

function _donsRenderFiche(fiche, correspondances) {
  if (!fiche) return '';
  window._donsLastFiche = fiche;
  const correspHtml = (correspondances || []).length ? `
    <div style="margin-top:10px;padding:10px 12px;background:#fff3e0;border-radius:8px;font-size:.82rem">
      ⚠️ ${correspondances.map(c => `Même ${escHtml(c.champ)} que <strong>${escHtml(c.avec.prenom)} ${escHtml(c.avec.nom)}</strong>`).join(' · ')} — demander le lien de parenté.
    </div>` : '';
  return `
    <div style="margin-top:16px;padding:14px 16px;background:var(--surface-2,var(--off));border:1px solid var(--border);border-radius:10px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong style="font-size:.9rem">${escHtml(fiche.prenom)} ${escHtml(fiche.nom)}</strong>
        <button class="btn btn-ghost btn-sm" onclick="_donsModifierFiche(${fiche.id})">Modifier</button>
      </div>
      <div style="font-size:.82rem;color:var(--muted);margin-top:4px">
        Date de naissance : ${fiche.date_naissance ? fmt(fiche.date_naissance) : '—'} · Adresse : ${escHtml(fiche.adresse || '—')}
      </div>
      ${correspHtml}
    </div>`;
}

function _donsModifierFiche(userId) {
  const f = window._donsLastFiche || {};
  openModal('Modifier la fiche', `
    <form id="donsFicheForm">
      <div class="form-group"><label>Date de naissance</label><input id="dmf_dob" type="date" value="${f.date_naissance ? f.date_naissance.slice(0,10) : ''}"/></div>
      <div class="form-group"><label>Adresse</label><input id="dmf_adresse" value="${escHtml(f.adresse || '')}"/></div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Enregistrer</button>
      </div>
    </form>
  `);
  document.getElementById('donsFicheForm').onsubmit = async e => {
    e.preventDefault();
    try {
      await api('/users/' + userId, { method:'PUT', body: JSON.stringify({
        date_naissance: document.getElementById('dmf_dob').value || null,
        adresse: document.getElementById('dmf_adresse').value
      })});
      closeModal(); toast('Fiche mise à jour');
    } catch(e) { toast(e.message, true); }
  };
}

function _donsRenderRoster(roster, foyerId) {
  if (!roster || !roster.length) return '';
  return `
    <div style="margin-top:12px;padding:14px 16px;background:var(--surface-2,var(--off));border:1px solid var(--border);border-radius:10px">
      <strong style="font-size:.85rem">Composition du foyer</strong>
      ${roster.map(p => { const a = p.date_naissance ? _donsAge(p.date_naissance) : null; const rel = DONS_RELATION_LABEL[p.relation] || 'Enfant'; const badges = _donsPersonneBadges(p, foyerId); return `<div style="padding:6px 0;border-top:1px solid var(--border);font-size:.82rem">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <span>${escHtml(p.prenom)} ${escHtml(p.nom)}${a !== null ? ' — ' + a + ' ans' : ' — âge inconnu'} <span style="color:var(--muted);font-size:.76rem">(${rel})</span>${p.date_naissance_verifiee ? ' ✅' : ''}${p.compte === false ? ' ⚠️ non compté' : ''}</span>
          <button class="btn btn-ghost btn-sm" onclick="_donsVerifierPersonne(${foyerId},${p.id},'${escHtml(p.prenom)}','${escHtml(p.nom)}','${p.date_naissance || ''}')">✓ Vérifier</button>
        </div>
        ${badges ? `<div style="margin-top:2px">${badges}</div>` : ''}
      </div>`; }).join('')}
    </div>`;
}

function _donsVerifierPersonne(foyerId, personneId, prenom, nom, dob) {
  openModal('Vérifier la personne', `
    <p style="font-size:.82rem;color:var(--muted);margin-bottom:10px">Confirmez la date de naissance après avoir vu une pièce d'identité (adulte) ou la déclaration du parent (enfant).</p>
    <form id="donsVerifForm">
      <div class="form-group"><label>Prénom</label><input id="dvf_prenom" value="${prenom}"/></div>
      <div class="form-group"><label>Nom</label><input id="dvf_nom" value="${nom}"/></div>
      <div class="form-group"><label>Date de naissance</label><input id="dvf_dob" type="date" value="${dob}"/></div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">✓ Confirmer / vérifier</button>
      </div>
    </form>
  `);
  document.getElementById('donsVerifForm').onsubmit = async e => {
    e.preventDefault();
    try {
      await api('/dons/foyers/' + foyerId + '/personnes/' + personneId, { method:'PUT', body: JSON.stringify({
        prenom: document.getElementById('dvf_prenom').value,
        nom: document.getElementById('dvf_nom').value,
        date_naissance: document.getElementById('dvf_dob').value || null,
        verifie: true
      })});
      closeModal(); toast('Personne vérifiée');
    } catch(e) { toast(e.message, true); }
  };
}

function _donsAppendLiveFeed(evt) {
  const feed = document.getElementById('donsLiveFeed');
  if (!feed) return;
  if (feed.querySelector('.muted, p')) feed.innerHTML = '';
  const ok = evt.resultat === 'ok';
  const row = document.createElement('div');
  row.style.cssText = 'padding:8px 10px;border-bottom:1px solid var(--border)';
  row.innerHTML = `<span style="color:${ok?'#2e7d32':'#c62828'};font-weight:700">${ok ? '✅' : '⛔'} ${escHtml(evt.foyer_nom || '')}</span>
    <div style="color:var(--muted);font-size:.76rem">${escHtml(evt.message || '')} · ${new Date().toLocaleTimeString('fr-CA')}</div>`;
  feed.prepend(row);
}

// ══════════════════════════════════════════════════════════════════════════════
// PROGRAMME DE DONS — vue membre (mon foyer, réservation, historique)
// ══════════════════════════════════════════════════════════════════════════════

function _donsStepPath(steps) {
  // steps: [{icon,label,state}] state = 'done' | 'active' | 'warn' | ''
  const bubbleStyle = s =>
    s === 'done' ? 'background:var(--g2);border-color:var(--g2);color:#fff'
    : s === 'active' ? 'background:#fff3e0;border-color:#e65100'
    : s === 'warn' ? 'background:#fdecea;border-color:#c62828'
    : 'background:var(--off);border-color:var(--border)';
  return `<div style="display:flex;align-items:center;justify-content:center;gap:4px;margin:26px 0 4px;flex-wrap:wrap">
    ${steps.map((s, i) => `
      ${i > 0 ? `<div style="width:26px;height:2px;background:${steps[i-1].state==='done'?'var(--g2)':'var(--border)'};margin-bottom:24px;flex-shrink:0"></div>` : ''}
      <div style="display:flex;flex-direction:column;align-items:center;gap:6px;width:88px;text-align:center">
        <div style="width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.25rem;border:2px solid;${bubbleStyle(s.state)}">${s.icon}</div>
        <span style="font-size:.72rem;font-weight:700;color:${s.state?'var(--text)':'var(--muted)'}">${s.label}</span>
      </div>`).join('')}
  </div>`;
}

async function donsMonFoyerView() {
  const prog = await api('/dons/programme-actif').catch(() => null);
  if (!prog) {
    setContent(`<div class="page-header"><div><h2>🎁 Programme de dons</h2></div></div>
      <div class="empty-state"><div class="es-icon">🎁</div><p>Aucun programme de dons actif pour le moment.</p></div>`);
    return;
  }
  const foyer = await api('/dons/mon-foyer?programme_id=' + prog.id).catch(() => null);
  window._donsMyFoyerId = foyer ? foyer.id : null;
  const prenom = (USER.prenom || '').trim();

  let bodyHtml = '';
  if (!foyer) {
    bodyHtml = `
      <div style="background:linear-gradient(160deg,#e8f5e9,var(--card,#fff) 65%);border:1px solid var(--border);border-radius:18px;padding:28px 26px;text-align:center;margin-bottom:22px">
        <div style="font-size:2rem">👋</div>
        <h2 style="font-size:1.3rem;font-weight:800;margin:6px 0 4px">Bonjour${prenom ? ', ' + escHtml(prenom) : ''}</h2>
        <p style="color:var(--muted);font-size:.9rem;max-width:44ch;margin:0 auto">Déclarez votre foyer pour rejoindre le programme — vous-même et chaque personne à charge. Ça ne prend qu'une minute.</p>
      </div>
      <div class="table-card" style="max-width:640px">
        <div class="table-card-header"><h3>Déclarer mon foyer</h3></div>
        <div style="padding:16px">
          <p style="font-size:.88rem;color:var(--muted);margin-bottom:14px">Listez toutes les personnes de votre foyer, vous y compris. Certains articles remis dépendent de l'âge (ex. couches, vêtements enfant) — la date de naissance est donc importante. Pour un(e) <strong>conjoint(e)</strong>, ajoutez son courriel AHH : il/elle doit avoir une carte membre active pour participer (sinon listé(e) mais non compté(e), en attendant). Les <strong>enfants</strong> n'ont pas besoin de carte — sauf à partir de 25 ans, où une déclaration de tutelle approuvée par le comité devient nécessaire.</p>
          <form id="donsFoyerForm">
            <div id="df_personnes"></div>
            <button type="button" class="btn btn-ghost btn-sm" onclick="_donsAjouterLignePersonne()">+ Ajouter une personne</button>
            <div class="form-actions" style="margin-top:16px"><button type="submit" class="btn btn-primary">Déclarer mon foyer</button></div>
          </form>
        </div>
      </div>`;
  } else {
    const statutLabel = foyer.statut === 'refuse' ? 'Refusé'
      : foyer.valide_pour_reservation ? (foyer.statut === 'en_attente' ? 'Actif — composition modifiée (informatif)' : 'Foyer validé')
      : 'En attente de validation';
    const statutCls = foyer.statut === 'refuse' ? 'bp-red' : foyer.valide_pour_reservation ? 'bp-green' : 'bp-orange';

    let prochainRdv = null, mesRdv = { rdv: [], retraits: [] }, creneaux = [], creneauxComplets = [];
    if (foyer.valide_pour_reservation && !foyer.necessite_reconfirmation) {
      mesRdv = await api('/dons/mes-rdv?programme_id=' + prog.id).catch(() => ({ rdv: [], retraits: [] }));
      prochainRdv = (mesRdv.rdv || []).find(r => r.statut === 'a_venir');
      if (!prochainRdv) {
        creneaux = await api('/dons/programmes/' + prog.id + '/creneaux-disponibles').catch(() => []);
        creneauxComplets = await api('/dons/programmes/' + prog.id + '/creneaux-complets').catch(() => []);
      }
    }

    // ── Chemin d'étapes : reflète l'état réel du foyer ──────────────────
    const step2State = foyer.statut === 'refuse' ? 'warn' : foyer.valide_pour_reservation ? 'done' : 'active';
    const step3State = foyer.necessite_reconfirmation ? 'warn' : !foyer.valide_pour_reservation ? '' : (prochainRdv ? 'done' : 'active');
    const step4State = foyer.necessite_reconfirmation ? '' : prochainRdv ? 'active' : '';
    const stepPath = foyer.statut === 'refuse' ? '' : _donsStepPath([
      { icon:'🏠', label:'Déclaré', state:'done' },
      { icon:'✅', label:'Validé', state: step2State },
      { icon:'📅', label:'Rendez-vous', state: step3State },
      { icon:'🎁', label:'Retrait', state: step4State },
    ]);

    let cardHtml = '';
    if (foyer.statut === 'refuse') {
      cardHtml = `<div style="background:#fdecea;padding:14px 18px;border-radius:10px">⛔ Votre foyer n'a pas été validé pour ce programme.${foyer.note_comite ? ' Raison : ' + escHtml(foyer.note_comite) : ''} Contactez le comité pour plus de détails.</div>`;
    } else if (foyer.necessite_reconfirmation) {
      cardHtml = `<div style="background:#fff3e0;padding:14px 18px;border-radius:10px">⚠️ Votre foyer doit être reconfirmé par le comité (rendez-vous manqués) avant de pouvoir réserver à nouveau. Contactez le comité si nécessaire.</div>`;
    } else if (!foyer.valide_pour_reservation) {
      cardHtml = `<div style="background:#fff3e0;padding:14px 18px;border-radius:10px">🕐 Votre foyer est en attente de validation par le comité. Vous pourrez réserver un rendez-vous dès qu'il sera validé.</div>`;
    } else if (prochainRdv) {
      const chips = (foyer.personnes || []).map(p => { const a = p.date_naissance ? _donsAge(p.date_naissance) : null; return `<div style="display:flex;align-items:center;gap:6px;background:var(--card,#fff);border:1px solid var(--border);padding:5px 10px 5px 5px;border-radius:999px;font-size:.78rem;font-weight:600">
        <span style="width:22px;height:22px;border-radius:50%;background:var(--g2);color:#fff;display:flex;align-items:center;justify-content:center;font-size:.65rem;font-weight:800">${(p.prenom[0]||'?')}${(p.nom[0]||'')}</span>
        ${escHtml(p.prenom)}${a !== null ? ' · ' + a + ' ans' : ''}
      </div>`; }).join('');
      cardHtml = `<div class="table-card" style="padding:20px 22px">
        <h3 style="margin:0 0 4px;font-size:1.02rem">Votre prochain rendez-vous</h3>
        <div style="font-size:1.15rem;font-weight:800;color:var(--g2)">${_donsFmtDT(prochainRdv.date_heure)}</div>
        ${chips ? `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">${chips}</div>` : ''}
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;flex-wrap:wrap;gap:10px">
          <span style="font-size:.82rem;color:var(--muted)">Présentez la carte de n'importe quel adulte du foyer.</span>
          <button class="btn btn-ghost btn-sm" style="color:#c62828" onclick="_donsAnnulerRdv(${prochainRdv.id})">Annuler</button>
        </div>
      </div>`;
    } else {
      const attenteHtml = creneauxComplets.length ? `
        <div style="margin-top:${creneaux.length ? '16px' : '0'};padding-top:${creneaux.length ? '14px' : '0'};${creneaux.length ? 'border-top:1px solid var(--border)' : ''}">
          <p style="font-size:.82rem;color:var(--muted);margin-bottom:8px">Créneaux complets — rejoignez la liste d'attente pour être avisé(e) si une place se libère :</p>
          ${creneauxComplets.map(c => `<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;font-size:.88rem">
            <span>${_donsFmtDT(c.date_heure)}</span>
            ${c.sur_liste_attente ? pill("✓ Sur liste d'attente", 'bp-green') : `<button class="btn btn-ghost btn-sm" onclick="_donsRejoindreAttente(${c.id})">Rejoindre la liste d'attente</button>`}
          </div>`).join('')}
        </div>` : '';
      cardHtml = `<div class="table-card">
        <div class="table-card-header"><h3>Réserver un rendez-vous</h3></div>
        <div style="padding:16px">
          ${creneaux.length ? `
            <select id="df_creneau" class="form-input" style="margin-bottom:10px;width:100%">
              ${creneaux.map(c => `<option value="${c.id}">${_donsFmtDT(c.date_heure)} — ${c.places_restantes} place(s)</option>`).join('')}
            </select>
            <button class="btn btn-primary" onclick="_donsReserverRdv(${prog.id})">Réserver</button>
          ` : (creneauxComplets.length ? '' : '<p style="color:var(--muted)">Aucun créneau disponible pour le moment — revenez plus tard.</p>')}
          ${attenteHtml}
        </div>
      </div>`;
    }

    let histHtml = '';
    if ((mesRdv.retraits || []).length) {
      histHtml = `<div class="table-card" style="margin-top:14px">
        <div class="table-card-header"><h3>Historique des retraits</h3></div>
        <div class="table-wrapper"><table><thead><tr><th>Date</th><th></th></tr></thead><tbody>
          ${mesRdv.retraits.map(r => `<tr><td>${_donsFmtDT(r.date_retrait)}</td><td><a href="${API}/dons/retraits/${r.id}/recu?token=${encodeURIComponent(TOKEN)}" target="_blank" class="btn btn-ghost btn-sm">🖨️ Reçu</a></td></tr>`).join('')}
        </tbody></table></div>
      </div>`;
    }

    const personnesRows = (foyer.personnes || []).map(p => { const a = p.date_naissance ? _donsAge(p.date_naissance) : null; const badges = _donsPersonneBadges(p, foyer.id, { canRequestTutelle: true }); return `<li>${escHtml(p.prenom)} ${escHtml(p.nom)}${a !== null ? ' — ' + a + ' ans' : ''} <span style="color:var(--muted);font-size:.78rem">(${DONS_RELATION_LABEL[p.relation] || 'Enfant'})</span>${p.date_naissance_verifiee ? ' ✅' : ''}${badges ? '<br>' + badges : ''}</li>`; }).join('');

    bodyHtml = `
      <div style="background:linear-gradient(160deg,#e8f5e9,var(--card,#fff) 65%);border:1px solid var(--border);border-radius:18px;padding:28px 26px;text-align:center;margin-bottom:22px">
        <div style="font-size:2rem">👋</div>
        <h2 style="font-size:1.3rem;font-weight:800;margin:6px 0 4px">Bonjour${prenom ? ', ' + escHtml(prenom) : ''}</h2>
        <p style="color:var(--muted);font-size:.9rem;max-width:46ch;margin:0 auto">Votre foyer fait partie du programme de dons — voici où vous en êtes et ce qui vous attend.</p>
        ${stepPath}
      </div>

      <div style="max-width:640px;margin:0 auto">
        ${cardHtml}
        ${histHtml}

        <div class="table-card" style="margin-top:14px">
          <div class="table-card-header"><h3>Mon foyer</h3>${pill(statutLabel, statutCls)}</div>
          <div style="padding:16px">
            <p><strong>Nombre de personnes :</strong> ${foyer.nb_personnes}</p>
            ${foyer.date_validation ? `<p style="font-size:.82rem;color:var(--muted)">Validé le ${fmt(foyer.date_validation)} — revalidation requise vers le ${_donsDansUnAn(foyer.date_validation)}.</p>` : ''}
            ${personnesRows ? `<ul style="margin:6px 0 10px;padding-left:20px;font-size:.88rem">${personnesRows}</ul>` : ''}
            ${foyer.membres.length ? `<p><strong>Membres liés (carte propre) :</strong> ${foyer.membres.map(m => escHtml(m.prenom+' '+m.nom)).join(', ')}</p>` : ''}
            ${foyer.note_comite ? `<p style="font-size:.85rem;color:var(--muted)"><strong>Note du comité :</strong> ${escHtml(foyer.note_comite)}</p>` : ''}
            ${foyer.statut !== 'refuse' ? `<button class="btn btn-ghost btn-sm" onclick="_donsModifierFoyer(${foyer.id},${prog.id})">Modifier la composition</button>` : ''}
          </div>
        </div>
      </div>
    `;
  }

  setContent(`
    <div class="page-header"><div><h2>🎁 ${escHtml(prog.nom)}</h2>${prog.description ? `<p>${escHtml(prog.description)}</p>` : ''}</div></div>
    ${bodyHtml}
  `);

  if (!foyer) {
    _donsAjouterLignePersonne(USER.prenom, USER.nom, false);
    document.getElementById('donsFoyerForm').onsubmit = async e => {
      e.preventDefault();
      const personnes = Array.from(document.querySelectorAll('#df_personnes .dons-personne-row')).map(row => ({
        prenom: row.querySelector('.dpp-prenom').value.trim(),
        nom: row.querySelector('.dpp-nom').value.trim(),
        date_naissance: row.querySelector('.dpp-dob').value || null,
        relation: row.querySelector('.dpp-relation')?.value || 'enfant',
        email: row.querySelector('.dpp-email')?.value?.trim() || null
      })).filter(p => p.prenom && p.nom);
      if (!personnes.length) { toast('Ajoutez au moins une personne', true); return; }
      try {
        const r = await api('/dons/foyers', { method:'POST', body: JSON.stringify({
          programme_id: prog.id,
          // Le responsable (première ligne) est déjà ajouté automatiquement côté serveur.
          personnes: personnes.slice(1)
        })});
        if (r.comptes_non_lies?.length) toast('Attention : ' + r.comptes_non_lies.join(', ') + ' introuvable(s) ou déjà rattaché(s) à un autre foyer — personne listée mais non comptée pour l\'instant', true);
        toast('Foyer déclaré — en attente de validation par le comité');
        donsMonFoyerView();
      } catch(e) { toast(e.message, true); }
    };
  }
}

function _donsFmtDT(dateStr) {
  if (!dateStr) return '–';
  const d = new Date(dateStr);
  return d.toLocaleDateString('fr-CA', { year:'numeric', month:'short', day:'numeric' }) + ' ' + d.toLocaleTimeString('fr-CA', { hour:'2-digit', minute:'2-digit' });
}

function _donsDansUnAn(dateISO) {
  const d = new Date(dateISO);
  d.setDate(d.getDate() + 365);
  return d.toLocaleDateString('fr-CA', { year:'numeric', month:'short', day:'numeric' });
}

function _donsAge(dateNaissance) {
  const d = new Date(dateNaissance), now = new Date();
  let age = now.getFullYear() - d.getFullYear();
  const m = now.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && now.getDate() < d.getDate())) age--;
  if (isNaN(age) || age < 0 || age > 120) return null; // date de naissance visiblement erronée — mieux vaut ne rien afficher
  return age;
}

const DONS_RELATION_LABEL = { responsable:'Responsable', conjoint:'Conjoint(e)', enfant:'Enfant' };

// Badges d'état (carte requise / tutelle) réutilisés dans la vue membre, le tableau comité
// et le panneau de scan — reflète p.compte / p.tutelle_statut renvoyés par le serveur.
function _donsPersonneBadges(p, foyerId, { canRequestTutelle = false } = {}) {
  const bits = [];
  if (p.relation === 'conjoint' && p.compte === false) {
    bits.push(pill('⚠️ Carte active requise', 'bp-orange'));
  }
  if (p.relation === 'enfant') {
    const age = p.date_naissance ? _donsAge(p.date_naissance) : null;
    if (age !== null && age >= 25) {
      if (p.tutelle_statut === 'approuvee') bits.push(pill('✅ Tutelle approuvée', 'bp-green'));
      else if (p.tutelle_statut === 'demandee') bits.push(pill('⏳ Tutelle en attente', 'bp-orange'));
      else if (p.tutelle_statut === 'refusee') bits.push(pill('❌ Tutelle refusée', 'bp-red'));
      else {
        bits.push(pill('⚠️ 25 ans+ — carte requise', 'bp-orange'));
        if (canRequestTutelle) bits.push(`<button class="btn btn-ghost btn-sm" style="padding:2px 8px;font-size:.72rem" onclick="_donsDemanderTutelle(${foyerId},${p.id})">Demander une tutelle</button>`);
      }
    }
  }
  return bits.join(' ');
}

function _donsDemanderTutelle(foyerId, personneId) {
  openModal('Demander une tutelle', `
    <p style="font-size:.82rem;color:var(--muted);margin-bottom:10px">Cette personne a 25 ans ou plus et n'a pas de carte membre propre. Expliquez brièvement pourquoi elle reste sous votre tutelle (ex. situation de handicap, aux études, etc.) — le comité approuvera ou refusera la demande.</p>
    <form id="donsTutelleForm">
      <div class="form-group"><label>Motif *</label><textarea id="dt_motif" rows="3" required></textarea></div>
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Envoyer la demande</button>
      </div>
    </form>
  `);
  document.getElementById('donsTutelleForm').onsubmit = async e => {
    e.preventDefault();
    try {
      await api('/dons/foyers/' + foyerId + '/personnes/' + personneId + '/tutelle', { method:'POST', body: JSON.stringify({ motif: document.getElementById('dt_motif').value }) });
      closeModal(); toast('Demande de tutelle envoyée au comité'); donsMonFoyerView();
    } catch(e) { toast(e.message, true); }
  };
}

function _donsAjouterLignePersonne(prenom = '', nom = '', removable = true) {
  const wrap = document.getElementById('df_personnes');
  if (!wrap) return;
  const row = document.createElement('div');
  row.className = 'dons-personne-row';
  row.style.cssText = 'display:flex;gap:8px;margin-bottom:8px;align-items:flex-end;flex-wrap:wrap';
  row.innerHTML = `
    <div class="form-group" style="flex:1;min-width:120px;margin:0"><label>Prénom</label><input class="dpp-prenom" value="${escHtml(prenom)}"/></div>
    <div class="form-group" style="flex:1;min-width:120px;margin:0"><label>Nom</label><input class="dpp-nom" value="${escHtml(nom)}"/></div>
    <div class="form-group" style="flex:1;min-width:150px;margin:0"><label>Date de naissance</label><input class="dpp-dob" type="date"/></div>
    ${removable ? `
    <div class="form-group" style="flex:1;min-width:130px;margin:0"><label>Relation</label>
      <select class="dpp-relation" onchange="const w=this.closest('.dons-personne-row').querySelector('.dpp-email-wrap');w.style.display=this.value==='conjoint'?'block':'none'">
        <option value="enfant" selected>Enfant</option>
        <option value="conjoint">Conjoint(e)</option>
      </select>
    </div>
    <div class="form-group dpp-email-wrap" style="flex:1;min-width:170px;margin:0;display:none"><label>Courriel du conjoint (AHH)</label><input class="dpp-email" type="email" placeholder="conjoint@exemple.com"/></div>
    <button type="button" class="btn btn-ghost btn-sm" onclick="this.closest('.dons-personne-row').remove()">✕</button>
    ` : ''}
  `;
  wrap.appendChild(row);
}

async function _donsReserverRdv(progId) {
  const creneauId = document.getElementById('df_creneau')?.value;
  if (!creneauId) return;
  try {
    await api('/dons/rdv', { method:'POST', body: JSON.stringify({ programme_id: progId, creneau_id: parseInt(creneauId) }) });
    toast('Rendez-vous réservé !');
    donsMonFoyerView();
  } catch(e) { toast(e.message, true); }
}

async function _donsAnnulerRdv(id) {
  if (!confirm('Annuler ce rendez-vous ?')) return;
  try { await api('/dons/rdv/' + id, { method:'DELETE' }); toast('Rendez-vous annulé'); donsMonFoyerView(); }
  catch(e) { toast(e.message, true); }
}

async function _donsRejoindreAttente(creneauId) {
  try {
    await api('/dons/creneaux/' + creneauId + '/attente', { method:'POST' });
    toast('Vous êtes sur la liste d\'attente — vous serez avisé(e) par courriel si une place se libère');
    donsMonFoyerView();
  } catch(e) { toast(e.message, true); }
}

async function _donsModifierFoyer(id, programmeId) {
  const foyer = await api('/dons/mon-foyer?programme_id=' + programmeId).catch(() => null);
  const personnes = (foyer && foyer.id === id) ? (foyer.personnes || []) : [];
  openModal('Modifier mon foyer', `
    <p style="font-size:.82rem;color:var(--muted);margin-bottom:10px">Ajouter, retirer ou corriger une personne renverra votre foyer en attente de validation.</p>
    <div id="dfe_personnes">
      ${personnes.map(p => { const badges = _donsPersonneBadges(p, id, { canRequestTutelle: true }); return `<div style="padding:8px 0;border-bottom:1px solid var(--border)">
        <div style="display:flex;gap:8px;align-items:center;justify-content:space-between">
          <span style="font-size:.88rem">${escHtml(p.prenom)} ${escHtml(p.nom)}${p.date_naissance ? ' — ' + fmt(p.date_naissance) : ''} <span style="color:var(--muted);font-size:.78rem">(${DONS_RELATION_LABEL[p.relation] || 'Enfant'})</span>${p.date_naissance_verifiee ? ' ✅' : ''}</span>
          <button type="button" class="btn btn-ghost btn-sm" style="color:#c62828" onclick="_donsSupprimerPersonne(${id},${p.id})">Retirer</button>
        </div>
        ${badges ? `<div style="margin-top:4px">${badges}</div>` : ''}
      </div>`; }).join('') || '<p style="font-size:.85rem;color:var(--muted)">Aucune personne listée.</p>'}
    </div>
    <form id="donsAjoutPersonneForm" style="margin-top:14px;display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap">
      <div class="form-group" style="flex:1;min-width:110px;margin:0"><label>Prénom</label><input id="dap_prenom" required/></div>
      <div class="form-group" style="flex:1;min-width:110px;margin:0"><label>Nom</label><input id="dap_nom" required/></div>
      <div class="form-group" style="flex:1;min-width:140px;margin:0"><label>Date de naissance</label><input id="dap_dob" type="date"/></div>
      <div class="form-group" style="flex:1;min-width:130px;margin:0"><label>Relation</label>
        <select id="dap_relation" onchange="document.getElementById('dap_email_wrap').style.display=this.value==='conjoint'?'block':'none'">
          <option value="enfant" selected>Enfant</option>
          <option value="conjoint">Conjoint(e)</option>
        </select>
      </div>
      <div class="form-group" id="dap_email_wrap" style="flex:1;min-width:170px;margin:0;display:none"><label>Courriel du conjoint (AHH)</label><input id="dap_email" type="email" placeholder="conjoint@exemple.com"/></div>
      <button type="submit" class="btn btn-primary btn-sm">+ Ajouter</button>
    </form>
    <div class="form-actions" style="margin-top:16px"><button type="button" class="btn btn-ghost" onclick="closeModal()">Fermer</button></div>
  `);
  document.getElementById('donsAjoutPersonneForm').onsubmit = async e => {
    e.preventDefault();
    try {
      const r = await api('/dons/foyers/' + id + '/personnes', { method:'POST', body: JSON.stringify({
        prenom: document.getElementById('dap_prenom').value,
        nom: document.getElementById('dap_nom').value,
        date_naissance: document.getElementById('dap_dob').value || null,
        relation: document.getElementById('dap_relation').value,
        email: document.getElementById('dap_email')?.value?.trim() || null
      })});
      if (r.lien_echoue) toast('Courriel introuvable ou déjà rattaché ailleurs — personne ajoutée mais non comptée pour l\'instant', true);
      closeModal(); toast('Personne ajoutée — foyer en attente de validation'); donsMonFoyerView();
    } catch(e) { toast(e.message, true); }
  };
}

async function _donsSupprimerPersonne(foyerId, personneId) {
  if (!confirm('Retirer cette personne du foyer ?')) return;
  try {
    await api('/dons/foyers/' + foyerId + '/personnes/' + personneId, { method:'DELETE' });
    toast('Personne retirée — foyer en attente de validation');
    closeModal(); donsMonFoyerView();
  } catch(e) { toast(e.message, true); }
}

// ══════════════════════════════════════════════════════════════════════════════
// SCANNER CARTES DE MEMBRE — BarcodeDetector natif (rapide) + html5-qrcode fallback
// ══════════════════════════════════════════════════════════════════════════════
async function carteScannerView() {
  // Arrêter tout scanner en cours
  if (window._carteScanner) { try { await window._carteScanner.stop(); } catch {} window._carteScanner = null; }
  if (window._carteStream)  { window._carteStream.getTracks().forEach(t => t.stop()); window._carteStream = null; }
  if (window._carteAnimFrame) { cancelAnimationFrame(window._carteAnimFrame); window._carteAnimFrame = null; }

  setContent(`
    <div class="page-header"><div><h2>📷 Lecteur de cartes membres</h2><p>Pointez la caméra vers le code QR de la carte</p></div></div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;max-width:920px">

      <div class="table-card" style="padding:14px">
        <h4 style="margin-bottom:8px;color:var(--g2);font-size:.9rem">📷 Caméra</h4>
        <div id="carteReaderWrap" style="border-radius:12px;overflow:hidden;background:#111;min-height:160px;max-height:40vh;position:relative">
          <!-- video pour BarcodeDetector natif -->
          <video id="scanVideo" autoplay muted playsinline style="width:100%;display:none;border-radius:12px;max-height:40vh;object-fit:cover"></video>
          <!-- viseur -->
          <div id="scanViewfinder" style="display:none;position:absolute;inset:0;align-items:center;justify-content:center;pointer-events:none">
            <div style="position:relative;width:190px;height:190px;border:2.5px solid rgba(255,255,255,.75);border-radius:14px;box-shadow:0 0 0 9999px rgba(0,0,0,.45)">
              <div style="position:absolute;top:-4px;left:-4px;width:22px;height:22px;border-top:5px solid #fff;border-left:5px solid #fff;border-radius:4px 0 0 0"></div>
              <div style="position:absolute;top:-4px;right:-4px;width:22px;height:22px;border-top:5px solid #fff;border-right:5px solid #fff;border-radius:0 4px 0 0"></div>
              <div style="position:absolute;bottom:-4px;left:-4px;width:22px;height:22px;border-bottom:5px solid #fff;border-left:5px solid #fff;border-radius:0 0 0 4px"></div>
              <div style="position:absolute;bottom:-4px;right:-4px;width:22px;height:22px;border-bottom:5px solid #fff;border-right:5px solid #fff;border-radius:0 0 4px 0"></div>
            </div>
          </div>
          <!-- fallback html5-qrcode -->
          <div id="carteReader"></div>
        </div>
        <div id="carteReaderMsg" style="display:none;padding:10px;text-align:center;font-size:.8rem;color:var(--muted)"></div>
        <div style="margin-top:14px">
          <label class="form-label">Saisie manuelle / lecteur USB</label>
          <div style="display:flex;gap:6px">
            <input id="scanQrInput" class="form-input" placeholder="AHH-00007-..."
              onkeydown="if(event.key==='Enter'){event.preventDefault();carteScanSearch();}"/>
            <button class="btn btn-primary" onclick="carteScanSearch()" title="Rechercher">🔍</button>
          </div>
        </div>
      </div>

      <div id="scanResult" class="table-card" style="padding:20px">
        <div class="empty-state"><div class="es-icon">🪪</div><p>Scannez une carte pour voir le profil du membre</p></div>
      </div>
    </div>
    <div id="scanActivities" style="display:none;margin-top:20px;max-width:920px"></div>
  `);

  // Utiliser BarcodeDetector natif si disponible (hardware-accelerated, très rapide)
  if ('BarcodeDetector' in window) {
    await _startNativeScanner();
  } else {
    await _startHtml5Scanner();
  }
}

async function _startNativeScanner() {
  const video = document.getElementById('scanVideo');
  if (!video) return;
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } }
    });
    video.srcObject = stream;
    window._carteStream = stream;
    video.style.display = 'block';
    const vf = document.getElementById('scanViewfinder');
    if (vf) vf.style.display = 'flex';

    const detector = new BarcodeDetector({ formats: ['qr_code'] });
    let lastValue = '', lastTime = 0;

    const loop = async () => {
      if (!document.getElementById('scanVideo')) return; // vue changée
      try {
        if (video.readyState >= 2) {
          const codes = await detector.detect(video);
          const now = Date.now();
          if (codes.length > 0 && (codes[0].rawValue !== lastValue || now - lastTime > 3000)) {
            lastValue = codes[0].rawValue;
            lastTime = now;
            const inp = document.getElementById('scanQrInput');
            if (inp) { inp.value = lastValue; carteScanSearch(); }
          }
        }
      } catch {}
      window._carteAnimFrame = requestAnimationFrame(loop);
    };
    video.addEventListener('loadedmetadata', () => {
      window._carteAnimFrame = requestAnimationFrame(loop);
    }, { once: true });

  } catch(e) {
    console.warn('[Scanner natif]', e.message, '→ fallback html5-qrcode');
    await _startHtml5Scanner();
  }
}

async function _startHtml5Scanner() {
  if (!window.Html5Qrcode) {
    try {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = '/Public/html5-qrcode.min.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    } catch {
      const msg = document.getElementById('carteReaderMsg');
      if (msg) { msg.style.display='block'; msg.textContent='Caméra non disponible — utilisez la saisie manuelle.'; }
      return;
    }
  }
  const scanner = new Html5Qrcode('carteReader');
  window._carteScanner = scanner;
  try {
    await scanner.start(
      { facingMode: 'environment' },
      { fps: 30, qrbox: { width: 220, height: 220 }, disableFlip: false },
      (decoded) => {
        const inp = document.getElementById('scanQrInput');
        if (inp && inp.value !== decoded) { inp.value = decoded; carteScanSearch(); }
      },
      () => {}
    );
  } catch(e) {
    console.warn('[Scanner html5-qrcode]', e && e.message || e);
    const msg = document.getElementById('carteReaderMsg');
    const permissionDenied = /NotAllowedError|Permission denied/i.test(String(e && e.message || e));
    if (msg) {
      msg.style.display = 'block';
      msg.textContent = permissionDenied
        ? 'Accès à la caméra refusé — autorisez la caméra pour ce site dans les réglages du navigateur, ou utilisez la saisie manuelle.'
        : 'Caméra non disponible — utilisez la saisie manuelle.';
    }
    const el = document.getElementById('carteReader');
    if (el) el.innerHTML = '<div style="padding:40px;text-align:center;font-size:2rem">📷</div>';
  }
}

let _carteScanLock = false;
async function carteScanSearch() {
  const qr = document.getElementById('scanQrInput')?.value?.trim();
  if (!qr || _carteScanLock) return;
  _carteScanLock = true;
  setTimeout(() => { _carteScanLock = false; }, 2000); // anti-doublon 2s

  const resultEl = document.getElementById('scanResult');
  if (resultEl) resultEl.innerHTML = '<div style="text-align:center;padding:32px"><div class="spinner"></div></div>';

  try {
    const r = await api(`/carte-scan/${encodeURIComponent(qr)}`);
    const m = r.member;
    const planLabel = { gratuit:'Gratuit', bienfaiteur:'Bienfaiteur', partenaire:'Partenaire' };
    const initials = `${(m.prenom||'?')[0]}${(m.nom||'')[0]}`.toUpperCase();
    const photoOk      = !!(m.photo_url && m.carte_photo_approuvee);
    const photoEnAttente = !!(m.photo_url && !m.carte_photo_approuvee);
    const sansPhoto    = !m.photo_url;
    const expiColor = sansPhoto ? '#e65100' : photoEnAttente ? '#1565c0' : m.expired ? '#c62828' : '#2e7d32';
    const expiBg    = sansPhoto ? '#fff3e0' : photoEnAttente ? '#e3f2fd' : m.expired ? '#fdecea' : '#e8f5e9';
    const validLabel = sansPhoto
      ? '⚠️ CARTE INVALIDE — aucune photo'
      : photoEnAttente
        ? '🕐 En attente de validation photo'
        : m.expired
          ? '⛔ Carte EXPIRÉE'
          : `✅ Valide — expire ${fmt(m.expiration)}`;
    const avatarBg = sansPhoto ? '#e65100' : photoEnAttente ? '#1565c0' : '#546e7a';

    if (resultEl) resultEl.innerHTML = `
      <div style="text-align:center;margin-bottom:16px">
        ${photoOk
          ? `<img src="${BASE}${m.photo_url}" style="width:88px;height:88px;border-radius:50%;object-fit:cover;border:4px solid ${expiColor};margin-bottom:10px"/>`
          : photoEnAttente
            ? `<img src="${BASE}${m.photo_url}" style="width:88px;height:88px;border-radius:50%;object-fit:cover;border:4px solid #1565c0;margin-bottom:10px;opacity:.7"/>`
            : `<div style="width:88px;height:88px;border-radius:50%;background:${avatarBg};color:#fff;font-size:2.2rem;font-weight:900;display:flex;align-items:center;justify-content:center;margin:0 auto 10px;border:4px solid ${avatarBg}">${initials}</div>`}
        <div style="font-size:1.15rem;font-weight:800">${escHtml(m.prenom)} ${escHtml(m.nom)}</div>
        <div style="font-size:.8rem;color:var(--muted);margin-top:2px">#${String(m.id).padStart(5,'0')} · ${planLabel[m.plan]||''} ${m.is_comite ? '· <span style="color:#1b5e20;font-weight:700">COMITÉ</span>' : ''}</div>
        <div style="margin-top:10px;padding:8px 16px;border-radius:20px;display:inline-block;font-size:.82rem;font-weight:700;
          background:${expiBg};color:${expiColor}">
          ${validLabel}
        </div>
        ${sansPhoto && can.executive() ? `<div style="margin-top:10px">
          <label style="cursor:pointer;background:var(--accent);color:#000;padding:8px 16px;border-radius:8px;font-size:.8rem;font-weight:700;display:inline-block">
            📷 Prendre / Ajouter photo
            <input type="file" accept="image/*" capture="environment" style="display:none" onchange="_uploadCartePhoto(${m.id},this.files[0])"/>
          </label>
        </div>` : ''}
      </div>`;

    window._scanUserId = m.id;
    const actEl = document.getElementById('scanActivities');
    if (actEl) {
      actEl.style.display = 'block';

      const inscrits   = r.activities.filter(a => a.reg_statut);
      const disponibles = r.activities.filter(a => !a.reg_statut);

      const rowInscrire = (a) => `
        <div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid var(--border);flex-wrap:wrap">
          <div style="width:8px;height:8px;border-radius:50%;background:#2e7d32;flex-shrink:0"></div>
          <div style="flex:1;min-width:0">
            <div style="font-weight:600;font-size:.88rem">${escHtml(a.titre)}</div>
            <div style="font-size:.74rem;color:var(--muted)">${a.date_debut ? new Date(a.date_debut).toLocaleDateString('fr-CA',{weekday:'short',month:'short',day:'numeric'}) : '–'}${a.lieu ? ' · ' + escHtml(a.lieu) : ''}</div>
          </div>
          ${a.reg_statut === 'confirme'
            ? '<span style="color:#2e7d32;font-weight:700;font-size:.8rem;white-space:nowrap">✅ Présent confirmé</span>'
            : `<button class="btn btn-sm btn-primary" style="background:#2e7d32;white-space:nowrap" onclick="carteScanPresencer(${a.id})">✅ Confirmer présence</button>`}
        </div>`;

      const rowDisponible = (a) => {
        const billetInfo = a.nb_billets > 0
          ? `<span style="font-size:.72rem;background:#e8f5e9;color:#2e7d32;padding:2px 8px;border-radius:8px;font-weight:600">${a.billets_non_utilises}/${a.nb_billets} billet(s)</span>`
          : (a.paiement_requis && a.prix > 0 ? `<span style="font-size:.72rem;background:#fdecea;color:#c62828;padding:2px 8px;border-radius:8px;font-weight:600">Pas de billet</span>` : '');
        return `<div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid #e3f2fd;flex-wrap:wrap">
          <div style="width:8px;height:8px;border-radius:50%;background:#1565c0;flex-shrink:0"></div>
          <div style="flex:1;min-width:0">
            <div style="font-weight:600;font-size:.88rem">${escHtml(a.titre)} ${billetInfo}</div>
            <div style="font-size:.74rem;color:var(--muted)">${a.date_debut ? new Date(a.date_debut).toLocaleDateString('fr-CA',{weekday:'short',month:'short',day:'numeric'}) : '–'}${a.lieu ? ' · ' + escHtml(a.lieu) : ''}</div>
          </div>
          <button class="btn btn-sm btn-outline" style="border-color:#1565c0;color:#1565c0;white-space:nowrap" onclick="carteScanPresencer(${a.id})">+ Présence</button>
        </div>`;
      };

      actEl.innerHTML = `
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;max-width:920px">
          <div class="table-card">
            <div class="table-card-header" style="background:#e8f5e9">
              <h3 style="color:#2e7d32">🟢 Inscrit(e) (${inscrits.length})</h3>
            </div>
            ${inscrits.length ? inscrits.map(rowInscrire).join('') : '<div style="padding:16px;text-align:center;font-size:.82rem;color:var(--muted)">Non inscrit(e) à aucune activité</div>'}
          </div>
          <div class="table-card">
            <div class="table-card-header" style="background:#e3f2fd">
              <h3 style="color:#1565c0">🔵 Disponible (${disponibles.length})</h3>
            </div>
            ${disponibles.length ? disponibles.map(rowDisponible).join('') : '<div style="padding:16px;text-align:center;font-size:.82rem;color:var(--muted)">Toutes les activités sont cochées</div>'}
          </div>
        </div>`;
    }
  } catch(e) {
    if (resultEl) resultEl.innerHTML = `<div class="empty-state"><div class="es-icon">⚠️</div><p style="color:#c62828">${escHtml(e.message)}</p></div>`;
    const actEl = document.getElementById('scanActivities');
    if (actEl) actEl.style.display = 'none';
  }
}

async function _uploadCartePhoto(userId, file) {
  if (!file) return;
  openPhotoCropper(file, async (blob, sourceFile) => {
    const fd = new FormData();
    fd.append('photo', blob, 'photo.jpg');
    fd.append('original', sourceFile, 'original.jpg');
    try {
      await fetch(BASE + '/api/admin/cartes/' + userId + '/photo', {
        method: 'POST',
        headers: { Authorization: 'Bearer ' + TOKEN },
        body: fd
      });
      toast('✅ Photo ajoutée — carte validée');
      const input = document.getElementById('scanQrInput');
      if (input?.value) carteScanSearch();
    } catch(e) { toast('Erreur photo : ' + e.message, true); }
  });
}

async function carteScanPresencer(actId) {
  const userId = window._scanUserId;
  if (!userId) return;
  try {
    await api('/carte-scan/presencer', { method:'POST', body: JSON.stringify({ user_id:userId, activity_id:actId }) });
    toast('✅ Présence enregistrée !');
    await carteScanSearch();
  } catch(e) { toast(e.message, true); }
}

// ══════════════════════════════════════════════════════════════════════════════
// 7. FIL D'ACTUALITÉS COMMUNAUTAIRE
// ══════════════════════════════════════════════════════════════════════════════
async function actualitesView() {
  const [galerie, activites, forumTopics] = await Promise.all([
    api('/gallery').catch(() => []),
    api('/activities').catch(() => []),
    api('/forum/topics').catch(() => [])
  ]);

  const feed = [];
  galerie.slice(0, 5).forEach(g => feed.push({
    type:'photo', date: g.date_upload, icon:'🖼️',
    titre: g.titre || 'Photo AHH',
    desc: `Photo ajoutée par ${escHtml(g.uploadeur||'AHH')}`,
    action: `showView('gallery_mgmt')`, color:'#7b1fa2'
  }));
  activites.filter(a => a.statut === 'planifiee').slice(0, 5).forEach(a => feed.push({
    type:'activite', date: a.date_creation || a.date_debut, icon:'🎉',
    titre: a.titre,
    desc: `📍 ${a.lieu||'–'} · ${a.date_debut ? new Date(a.date_debut).toLocaleDateString('fr-CA') : ''}`,
    action: `showView('activities')`, color:'#c62828'
  }));
  forumTopics.slice(0, 5).forEach(t => feed.push({
    type:'forum', date: t.date_creation, icon:'💬',
    titre: t.titre,
    desc: `${t.nb_posts||0} réponse(s) · Par ${escHtml(t.auteur||'membre')}`,
    action: `showView('forum')`, color:'#1565c0'
  }));

  feed.sort((a, b) => new Date(b.date||0) - new Date(a.date||0));

  setContent(`
    <div class="page-header"><div><h2>📰 Actualités</h2><p>Le fil de vie de votre communauté AHH</p></div></div>
    ${!feed.length ? '<div class="empty-state"><div class="es-icon">📰</div><p>Aucune actualité pour le moment</p></div>' :
      `<div style="display:flex;flex-direction:column;gap:12px">
        ${feed.map(item => `
          <div style="border:1px solid var(--border);border-radius:12px;background:#fff;overflow:hidden;cursor:pointer" onclick="${item.action}">
            <div style="display:flex;align-items:flex-start;gap:14px;padding:14px 16px">
              <div style="width:40px;height:40px;border-radius:10px;background:${item.color};color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.2rem;flex-shrink:0">${item.icon}</div>
              <div style="flex:1;min-width:0">
                <div style="font-weight:700;font-size:.9rem;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escHtml(item.titre)}</div>
                <div style="font-size:.78rem;color:var(--muted)">${item.desc}</div>
              </div>
              <div style="font-size:.7rem;color:var(--muted);flex-shrink:0;margin-top:2px">${item.date ? fmt(item.date) : ''}</div>
            </div>
          </div>`).join('')}
      </div>`}
  `);
}

