// ══ TASKS (Kanban) ═════════════════════════════════════════════════════════
async function tasksView() {
  try {
    const tasks = await api('/tasks');
    const priorityColors = { haute:'#e53935', moyenne:'#fb8c00', basse:'#43a047' };
    const priorityLabels = { haute:'Haute', moyenne:'Moyenne', basse:'Basse' };
    const statusCols = [
      { key:'a_faire',  label:'À faire',  color:'#1976d2' },
      { key:'en_cours', label:'En cours',  color:'#fb8c00' },
      { key:'terminee', label:'Terminé',   color:'#43a047' },
    ];

    const filterHtml = `
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px;align-items:center">
        <select id="taskFilterAssignee" onchange="tasksApplyFilter()" style="padding:6px 10px;border-radius:6px;border:1px solid #ddd">
          <option value="">Tous les assignés</option>
          ${[...new Set(tasks.map(t => t.assigne_nom).filter(Boolean))].map(n => `<option value="${escHtml(n)}">${escHtml(n)}</option>`).join('')}
        </select>
        <select id="taskFilterPriority" onchange="tasksApplyFilter()" style="padding:6px 10px;border-radius:6px;border:1px solid #ddd">
          <option value="">Toutes priorités</option>
          <option value="haute">Haute</option>
          <option value="moyenne">Moyenne</option>
          <option value="basse">Basse</option>
        </select>
        <select id="taskFilterCategory" onchange="tasksApplyFilter()" style="padding:6px 10px;border-radius:6px;border:1px solid #ddd">
          <option value="">Toutes catégories</option>
          ${[...new Set(tasks.map(t => t.categorie).filter(Boolean))].map(c => `<option value="${escHtml(c)}">${escHtml(c)}</option>`).join('')}
        </select>
        <button class="btn btn-primary btn-sm" onclick="taskShowForm()" style="margin-left:auto">+ Nouvelle tâche</button>
      </div>`;

    const buildCard = (t) => {
      const pc = priorityColors[t.priorite] || '#999';
      return `<div class="task-card" data-id="${t.id}" data-assignee="${escHtml(t.assigne_nom || '')}" data-priority="${t.priorite || ''}" data-category="${escHtml(t.categorie || '')}" style="background:#fff;border-radius:8px;padding:12px;margin-bottom:8px;box-shadow:0 1px 3px rgba(0,0,0,.1);border-left:4px solid ${pc}">
        <div style="font-weight:600;margin-bottom:4px">${escHtml(t.titre)}</div>
        <div style="font-size:.8rem;color:var(--muted);margin-bottom:6px">${escHtml(t.description || '')}</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
          ${t.assigne_nom ? pill(escHtml(t.assigne_nom), 'bp-blue') : ''}
          ${t.priorite ? `<span style="font-size:.7rem;padding:2px 8px;border-radius:10px;background:${pc};color:#fff">${priorityLabels[t.priorite] || t.priorite}</span>` : ''}
          ${t.echeance ? `<span style="font-size:.75rem;color:var(--muted)">📅 ${fmt(t.echeance)}</span>` : ''}
        </div>
        <div style="display:flex;gap:4px;margin-top:8px;justify-content:flex-end">
          <button class="btn btn-ghost btn-sm" onclick="taskEdit(${t.id})" style="padding:2px 8px;font-size:.75rem">✏️</button>
          <button class="btn btn-ghost btn-sm" onclick="taskDelete(${t.id})" style="padding:2px 8px;font-size:.75rem;color:#c62828">🗑️</button>
        </div>
      </div>`;
    };

    const colsHtml = statusCols.map(col => {
      const colTasks = (tasks || []).filter(t => t.statut === col.key);
      return `<div style="flex:1;min-width:260px;background:#f5f5f5;border-radius:10px;padding:12px">
        <div style="font-weight:700;margin-bottom:12px;padding-bottom:8px;border-bottom:3px solid ${col.color};color:${col.color}">${col.label} (${colTasks.length})</div>
        <div class="task-col" data-status="${col.key}">${colTasks.map(buildCard).join('')}</div>
      </div>`;
    }).join('');

    const statusLabels = { a_faire:'À faire', en_cours:'En cours', terminee:'Terminé' };
    const mobileCards = (tasks || []).map(t => {
      const searchData = ((t.titre||'')+' '+(t.description||'')+' '+(t.assigne_nom||'')+' '+(t.categorie||'')).toLowerCase();
      return `<div class="task-card m-item task-entry" data-search="${escHtml(searchData)}" data-priority="${t.priorite||''}" data-status="${t.statut||''}" style="border-left:4px solid ${priorityColors[t.priorite]||'#999'}">
        <div class="m-item-top"><div class="m-item-title">${escHtml(t.titre)}</div>${pill(statusLabels[t.statut]||t.statut,'bp-blue')}</div>
        ${t.description ? `<div class="m-item-sub">${escHtml(t.description)}</div>` : ''}
        <div class="m-item-sub">
          ${t.assigne_nom ? '👤 '+escHtml(t.assigne_nom)+' · ' : ''}${t.priorite ? priorityLabels[t.priorite]+' · ' : ''}${t.echeance ? '📅 '+fmt(t.echeance) : ''}
        </div>
        <div class="m-item-actions">
          <button class="btn btn-sm btn-ghost" onclick="taskEdit(${t.id})">✏️ Modifier</button>
          <button class="btn btn-sm btn-ghost" style="color:#c62828" onclick="taskDelete(${t.id})">🗑️ Supprimer</button>
        </div>
      </div>`;
    }).join('') || '<div class="m-empty">Aucune tâche</div>';

    setContent(`
      <div class="page-header"><div><h2>✓ Tâches</h2></div>
        <div class="page-actions"><button class="btn btn-primary btn-sm" onclick="taskShowForm()">+ Nouvelle tâche</button></div>
      </div>
      <div id="taskFormArea"></div>

      <div class="desktop-page-only">
        <div class="table-card">
          <div style="padding:16px">
            ${filterHtml.replace('<button class="btn btn-primary btn-sm" onclick="taskShowForm()" style="margin-left:auto">+ Nouvelle tâche</button>', '')}
            <div style="display:flex;gap:16px;flex-wrap:wrap">${colsHtml}</div>
          </div>
        </div>
      </div>

      <div class="mobile-page-only">
        <div class="m-searchbar">🔍<input type="text" id="taskSearch" placeholder="Titre, description, assigné…" oninput="_taskFilterMobile()"/></div>
        <div class="m-chiprow" id="taskChips">
          <span class="m-chip active" data-f="" onclick="_taskChipClick(this)">Toutes</span>
          <span class="m-chip" data-f="a_faire" onclick="_taskChipClick(this)">À faire</span>
          <span class="m-chip" data-f="en_cours" onclick="_taskChipClick(this)">En cours</span>
          <span class="m-chip" data-f="terminee" onclick="_taskChipClick(this)">Terminé</span>
          <span class="m-chip" data-f="haute" onclick="_taskChipClick(this)">🔴 Priorité haute</span>
        </div>
        <div id="taskListMobile">${mobileCards}</div>
      </div>`);
  } catch(e) { toast(e.message, true); }
}

function _taskChipClick(chip) {
  chip.parentElement.querySelectorAll('.m-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  _taskFilterMobile();
}
function _taskFilterMobile() {
  const q = (document.getElementById('taskSearch')?.value || '').toLowerCase();
  const f = document.querySelector('#taskChips .m-chip.active')?.dataset.f || '';
  document.querySelectorAll('.task-entry').forEach(el => {
    const ok = (!q || el.dataset.search.includes(q))
      && (!f || el.dataset.status === f || el.dataset.priority === f);
    el.style.display = ok ? '' : 'none';
  });
}

function tasksApplyFilter() {
  const assignee = document.getElementById('taskFilterAssignee').value;
  const priority = document.getElementById('taskFilterPriority').value;
  const category = document.getElementById('taskFilterCategory').value;
  document.querySelectorAll('.task-card').forEach(c => {
    const matchA = !assignee || c.dataset.assignee === assignee;
    const matchP = !priority || c.dataset.priority === priority;
    const matchC = !category || c.dataset.category === category;
    c.style.display = (matchA && matchP && matchC) ? '' : 'none';
  });
}

function taskShowForm(existing) {
  const t = existing || {};
  document.getElementById('taskFormArea').innerHTML = `
    <div style="background:#f9f9f9;border-radius:10px;padding:16px;margin-bottom:16px;border:1px solid #e0e0e0">
      <h4 style="margin:0 0 12px">${t.id ? 'Modifier la tâche' : 'Nouvelle tâche'}</h4>
      <div class="form-row">
        <div class="form-group"><label>Titre *</label><input id="taskTitre" value="${escHtml(t.titre || '')}" required></div>
        <div class="form-group"><label>Catégorie</label><input id="taskCategorie" value="${escHtml(t.categorie || '')}"></div>
      </div>
      <div class="form-group"><label>Description</label><textarea id="taskDesc" rows="2">${escHtml(t.description || '')}</textarea></div>
      <div class="form-row">
        <div class="form-group"><label>Priorité</label>
          <select id="taskPriorite"><option value="basse" ${t.priorite==='basse'?'selected':''}>Basse</option><option value="moyenne" ${t.priorite==='moyenne'?'selected':''}>Moyenne</option><option value="haute" ${t.priorite==='haute'?'selected':''}>Haute</option></select>
        </div>
        <div class="form-group"><label>Statut</label>
          <select id="taskStatut"><option value="a_faire" ${t.statut==='a_faire'?'selected':''}>À faire</option><option value="en_cours" ${t.statut==='en_cours'?'selected':''}>En cours</option><option value="terminee" ${t.statut==='terminee'?'selected':''}>Terminé</option></select>
        </div>
      </div>
      <div class="form-row">
        <div class="form-group" style="position:relative">
          <label>Assigné à</label>
          <input id="taskAssigneSearch" autocomplete="off" placeholder="Tapez un nom..." value="${escHtml(t.assigne_nom || '')}" oninput="_taskSearchMember(this.value)">
          <input id="taskAssigne" type="hidden" value="${t.assigne_a || ''}">
          <div id="taskAssigneDropdown" style="position:absolute;top:100%;left:0;right:0;z-index:50;background:#fff;border:1px solid #ddd;border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.15);max-height:180px;overflow-y:auto;display:none"></div>
        </div>
        <div class="form-group"><label>Échéance</label><input id="taskEcheance" type="date" value="${t.echeance ? t.echeance.substring(0,10) : ''}"></div>
      </div>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn btn-primary btn-sm" onclick="taskSave(${t.id || 'null'})">${t.id ? 'Mettre à jour' : 'Créer'}</button>
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('taskFormArea').innerHTML=''">Annuler</button>
      </div>
    </div>`;
}

let _taskSearchTimer = null;
async function _taskSearchMember(query) {
  const dd = document.getElementById('taskAssigneDropdown');
  if (!dd) return;
  clearTimeout(_taskSearchTimer);
  if (!query || query.length < 2) { dd.style.display = 'none'; return; }
  _taskSearchTimer = setTimeout(async () => {
    try {
      const members = await api('/members/search?q=' + encodeURIComponent(query));
      if (!members || !members.length) { dd.style.display = 'none'; return; }
      dd.innerHTML = members.map(m =>
        `<div style="padding:8px 12px;cursor:pointer;border-bottom:1px solid #f0f0f0;font-size:.88rem" onmouseover="this.style.background='#e3f2fd'" onmouseout="this.style.background=''" onclick="_taskSelectMember(${m.id},'${escHtml(m.prenom)} ${escHtml(m.nom)}')">
          <strong>${escHtml(m.prenom)} ${escHtml(m.nom)}</strong> <span style="color:var(--muted);font-size:.78rem">${escHtml(m.email || '')}</span>
        </div>`
      ).join('');
      dd.style.display = '';
    } catch(e) { dd.style.display = 'none'; }
  }, 250);
}

function _taskSelectMember(id, nom) {
  document.getElementById('taskAssigne').value = id;
  document.getElementById('taskAssigneSearch').value = nom;
  document.getElementById('taskAssigneDropdown').style.display = 'none';
}

async function taskSave(id) {
  try {
    const assigneId = document.getElementById('taskAssigne').value;
    const assigneNom = document.getElementById('taskAssigneSearch').value;
    const data = {
      titre: document.getElementById('taskTitre').value,
      description: document.getElementById('taskDesc').value,
      categorie: document.getElementById('taskCategorie').value,
      priorite: document.getElementById('taskPriorite').value,
      statut: document.getElementById('taskStatut').value,
      assigne_a: assigneId || null,
      assigne_nom_libre: !assigneId && assigneNom ? assigneNom : null,
      echeance: document.getElementById('taskEcheance').value || null,
    };
    if (!data.titre) { toast('Le titre est requis', true); return; }
    if (id) {
      await api('/tasks/' + id, { method:'PUT', body: JSON.stringify(data) });
      toast('Tâche mise à jour');
    } else {
      await api('/tasks', { method:'POST', body: JSON.stringify(data) });
      toast('Tâche créée');
    }
    await tasksView();
  } catch(e) { toast(e.message, true); }
}

async function taskEdit(id) {
  try {
    const tasks = await api('/tasks');
    const t = tasks.find(x => x.id === id);
    if (t) taskShowForm(t);
  } catch(e) { toast(e.message, true); }
}

async function taskDelete(id) {
  if (!confirm('Supprimer cette tâche ?')) return;
  try {
    await api('/tasks/' + id, { method:'DELETE' });
    toast('Tâche supprimée');
    await tasksView();
  } catch(e) { toast(e.message, true); }
}

// ══ MEETING CALENDAR ═══════════════════════════════════════════════════════
async function meetingCalendarView() {
  if (!document.getElementById('reunionsHubBody')) { return reunionsHubView('calendrier'); }
  try {
    const meetings = await api('/meetings');
    const typePills = { ordinaire:'bp-blue', extraordinaire:'bp-orange', comite:'bp-green', assemblee:'bp-gray' };

    const rows = (meetings || []).map(m => `<tr>
      <td>${fmt(m.date_heure)}</td>
      <td>${escHtml(m.titre)}</td>
      <td>${pill(m.type || '–', typePills[m.type] || 'bp-gray')}</td>
      <td>${escHtml(m.lieu || '–')}</td>
      <td>${m.duree_minutes ? m.duree_minutes + ' min' : '–'}</td>
      <td>${m.lien_virtuel ? `<a href="${escHtml(m.lien_virtuel)}" target="_blank" style="color:var(--accent)">Lien</a>` : '–'}</td>
      <td>
        <button class="btn btn-ghost btn-sm" onclick="meetingEdit(${m.id})" style="padding:2px 8px">✏️</button>
        <button class="btn btn-ghost btn-sm" onclick="meetingDelete(${m.id})" style="padding:2px 8px;color:#c62828">🗑️</button>
      </td>
    </tr>`).join('');

    document.getElementById('reunionsHubBody').innerHTML = `
      <div class="table-card">
        <div class="table-card-header">
          <h3>Calendrier des réunions</h3>
          <button class="btn btn-primary btn-sm" onclick="meetingShowForm()">+ Nouvelle réunion</button>
        </div>
        <div id="meetingFormArea" style="padding:0 16px"></div>
        <div class="table-wrapper">
          <table class="data-table">
            <thead><tr><th>Date</th><th>Titre</th><th>Type</th><th>Lieu</th><th>Durée</th><th>Lien</th><th>Actions</th></tr></thead>
            <tbody>${rows || '<tr><td colspan="7" style="text-align:center;color:var(--muted)">Aucune réunion</td></tr>'}</tbody>
          </table>
        </div>
      </div>`;
  } catch(e) { toast(e.message, true); }
}

function meetingShowForm(existing) {
  const m = existing || {};
  const dtVal = m.date_heure ? m.date_heure.substring(0,16) : '';
  document.getElementById('meetingFormArea').innerHTML = `
    <div style="background:#f9f9f9;border-radius:10px;padding:16px;margin:12px 0;border:1px solid #e0e0e0">
      <h4 style="margin:0 0 12px">${m.id ? 'Modifier la réunion' : 'Nouvelle réunion'}</h4>
      <div class="form-row">
        <div class="form-group"><label>Titre *</label><input id="mtgTitre" value="${escHtml(m.titre || '')}"></div>
        <div class="form-group"><label>Type</label>
          <select id="mtgType">
            <option value="ordinaire" ${m.type==='ordinaire'?'selected':''}>Ordinaire</option>
            <option value="extraordinaire" ${m.type==='extraordinaire'?'selected':''}>Extraordinaire</option>
            <option value="comite" ${m.type==='comite'?'selected':''}>Comité</option>
            <option value="assemblee" ${m.type==='assemblee'?'selected':''}>Assemblée</option>
          </select>
        </div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Date et heure *</label><input id="mtgDate" type="datetime-local" value="${dtVal}"></div>
        <div class="form-group"><label>Durée (minutes)</label><input id="mtgDuree" type="number" value="${m.duree_minutes || 60}"></div>
      </div>
      <div class="form-row">
        <div class="form-group"><label>Lieu</label><input id="mtgLieu" value="${escHtml(m.lieu || '')}"></div>
        <div class="form-group"><label>Lien virtuel</label><input id="mtgLien" value="${escHtml(m.lien_virtuel || '')}"></div>
      </div>
      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="btn btn-primary btn-sm" onclick="meetingSave(${m.id || 'null'})">${m.id ? 'Mettre à jour' : 'Créer'}</button>
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('meetingFormArea').innerHTML=''">Annuler</button>
      </div>
    </div>`;
}

async function meetingSave(id) {
  try {
    const data = {
      titre: document.getElementById('mtgTitre').value,
      type: document.getElementById('mtgType').value,
      date_heure: document.getElementById('mtgDate').value,
      duree_minutes: parseInt(document.getElementById('mtgDuree').value) || 60,
      lieu: document.getElementById('mtgLieu').value,
      lien_virtuel: document.getElementById('mtgLien').value,
    };
    if (!data.titre) { toast('Le titre est requis', true); return; }
    if (!data.date_heure) { toast('La date est requise', true); return; }
    if (id) {
      await api('/meetings/' + id, { method:'PUT', body: JSON.stringify(data) });
      toast('Réunion mise à jour');
    } else {
      await api('/meetings', { method:'POST', body: JSON.stringify(data) });
      toast('Réunion créée');
    }
    await meetingCalendarView();
  } catch(e) { toast(e.message, true); }
}

async function meetingEdit(id) {
  try {
    const meetings = await api('/meetings');
    const m = meetings.find(x => x.id === id);
    if (m) meetingShowForm(m);
  } catch(e) { toast(e.message, true); }
}

async function meetingDelete(id) {
  if (!confirm('Supprimer cette réunion ?')) return;
  try {
    await api('/meetings/' + id, { method:'DELETE' });
    toast('Réunion supprimée');
    await meetingCalendarView();
  } catch(e) { toast(e.message, true); }
}

// ══ MEETING AGENDAS — document officiel (lettre AHH, listes uniquement) ═════
async function meetingAgendasView() {
  if (!document.getElementById('reunionsHubBody')) { return reunionsHubView('agendas'); }
  try {
    const agendas = await api('/agendas');
    window._agendaData = {}; agendas.forEach(a => { window._agendaData[a.id] = a; });
    const rows = (agendas || []).map(a => {
      const locked = !!a.verrouille;
      const signed = !!a.date_ma_signature;
      const lockBadge = locked ? `<span style="background:#e8f5e9;color:#1b5e20;font-size:.72rem;padding:2px 9px;border-radius:12px;font-weight:600">🔒 Verrouillé — 3/3</span>` : '';
      const sigBadge = signed && !locked ? `<span style="background:#e3f2fd;color:#1565c0;font-size:.72rem;padding:2px 9px;border-radius:12px;font-weight:600">✅ Vous avez signé</span>` : '';
      const countBadge = a.nb_signatures > 0 && !locked ? `<span style="background:#fff3cd;color:#856404;font-size:.72rem;padding:2px 9px;border-radius:12px;font-weight:600">🖊 ${a.nb_signatures}/3</span>` : '';
      return `<tr>
        <td style="cursor:pointer" onclick="openAgendaEditor(window._agendaData[${a.id}])"><strong>${escHtml(a.titre)}</strong></td>
        <td>${fmt(a.date_reunion)}</td>
        <td>${lockBadge}${sigBadge}${countBadge}</td>
        <td>${escHtml(a.createur_nom || '–')}</td>
        <td style="white-space:nowrap">
          <button class="btn btn-sm btn-outline" onclick="openAgendaEditor(window._agendaData[${a.id}])">${locked?'👁 Voir':'✏️ Ouvrir'}</button>
          <a href="/api/agendas/${a.id}/download?token=${TOKEN}" target="_blank" class="btn btn-sm btn-ghost">⬇ PDF</a>
          ${!locked ? `<button class="btn btn-sm btn-danger" onclick="deleteAgenda(${a.id})">🗑️</button>` : ''}
        </td>
      </tr>`;
    }).join('');

    document.getElementById('reunionsHubBody').innerHTML = `
      <div class="page-header" style="margin-bottom:14px">
        <p style="font-size:.82rem;color:var(--muted)">Document officiel AHH — rédigé en listes à puces ou numérotées</p>
        <div class="page-actions"><button class="btn btn-primary" onclick="openAgendaEditor(null)">+ Nouvel ordre du jour</button></div>
      </div>
      <div class="table-card">
        <div class="table-wrapper">
          <table class="data-table">
            <thead><tr><th>Titre</th><th>Date réunion</th><th>Statut</th><th>Créé par</th><th>Actions</th></tr></thead>
            <tbody>${rows || '<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:24px">Aucun ordre du jour</td></tr>'}</tbody>
          </table>
        </div>
      </div>`;
  } catch(e) { toast(e.message, true); }
}

async function deleteAgenda(id) {
  if (!confirm('Supprimer cet ordre du jour ?')) return;
  try { await api('/agendas/' + id, { method:'DELETE' }); toast('Ordre du jour supprimé'); await meetingAgendasView(); }
  catch(e) { toast(e.message, true); }
}

function openAgendaEditor(a) {
  const agendaId = a?.id || null;
  const readOnly = !!a?.verrouille;
  const today = new Date().toISOString().slice(0,10);
  const autoTitle = a?.titre || `Ordre du jour — ${new Date().toLocaleDateString('fr-CA',{year:'numeric',month:'long',day:'numeric'})}`;

  setContent(`
    <div id="agendaEditorShell" style="display:flex;flex-direction:column;height:calc(100vh - var(--strip-h) - 8px);background:#e0e0e0">
      <div style="background:#fff;border-bottom:1px solid #d0d0d0;padding:8px 16px;display:flex;align-items:center;gap:4px;flex-wrap:wrap;box-shadow:0 1px 4px rgba(0,0,0,.08);position:sticky;top:0;z-index:10">
        <div style="display:flex;gap:8px;align-items:center;margin-right:12px;padding-right:12px;border-right:1px solid #ddd;flex-wrap:wrap">
          <input id="ag_titre" style="border:1px solid #ddd;border-radius:6px;padding:5px 10px;font-size:.88rem;font-weight:600;width:240px" placeholder="Titre de l'ordre du jour" value="${escHtml(autoTitle)}" ${readOnly?'disabled':''}/>
          <input type="date" id="ag_date" style="border:1px solid #ddd;border-radius:6px;padding:5px 8px;font-size:.82rem" value="${a?.date_reunion?a.date_reunion.substring(0,10):today}" ${readOnly?'disabled':''}/>
        </div>

        <!-- Listes uniquement -->
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('insertUnorderedList');_fixListNesting('ag_editor');_collapseSelectionToEnd();_updateLivePagination('ag_editor','Ordre du jour')" title="Liste à puces" ${readOnly?'disabled':''}>• ≡</button>
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('insertOrderedList');_fixListNesting('ag_editor');_collapseSelectionToEnd();_updateLivePagination('ag_editor','Ordre du jour')" title="Liste numérotée" ${readOnly?'disabled':''}>1. ≡</button>
        <div style="width:1px;height:24px;background:#ddd;margin:0 4px"></div>
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('indent');_fixListNesting('ag_editor');_collapseSelectionToEnd();_updateLivePagination('ag_editor','Ordre du jour')" title="Sous-point (indenter)" ${readOnly?'disabled':''}>➡ Indenter</button>
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('outdent');_fixListNesting('ag_editor');_collapseSelectionToEnd();_updateLivePagination('ag_editor','Ordre du jour')" title="Remonter d'un niveau" ${readOnly?'disabled':''}>⬅ Désindenter</button>
        <div style="width:1px;height:24px;background:#ddd;margin:0 4px"></div>
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('undo')" title="Annuler" ${readOnly?'disabled':''}>↩</button>
        <button class="we-btn" onmousedown="event.preventDefault()" onclick="document.execCommand('redo')" title="Rétablir" ${readOnly?'disabled':''}>↪</button>

        <div style="flex:1"></div>

        <span id="agendaStatus" style="font-size:.75rem;color:var(--muted);margin-right:8px">${readOnly ? '🔒 Verrouillé' : ''}</span>
        <button class="btn btn-sm btn-ghost" onclick="meetingAgendasView()" title="Fermer">✕ Fermer</button>
        ${agendaId ? `<a href="/api/agendas/${agendaId}/download?token=${TOKEN}" target="_blank" class="btn btn-sm btn-outline">⬇ PDF</a>` : ''}
        ${agendaId && !readOnly ? `<button class="btn btn-sm btn-ghost" style="color:#6a1b9a;border:1px solid #6a1b9a" onclick="openAgendaSignatureModal(${agendaId},'${escHtml(a?.titre||'').replace(/'/g,"\\'")}')">✍️ Signer</button>` : ''}
        ${!readOnly ? `<button class="btn btn-sm btn-primary" onclick="saveAgendaEditor(${agendaId||'null'})">💾 Sauvegarder</button>` : ''}
      </div>

      <div style="flex:1;overflow-y:auto;padding:32px 0 48px;background:#e0e0e0">
        ${readOnly ? `<div style="text-align:center;padding:12px;background:#e8f5e9;color:#1b5e20;font-weight:600;font-size:.85rem">🔒 Cet ordre du jour est verrouillé — lecture seule après 3 signatures</div>`
          : a?.nb_signatures > 0 ? `<div style="text-align:center;padding:10px 16px;background:#fff3cd;color:#856404;font-weight:600;font-size:.82rem">⚠️ ${a.nb_signatures} signature(s) existante(s). Toute sauvegarde les annulera.</div>` : ''}

        <style>#ag_editor ul, #ag_editor ol { margin: 4px 0 4px 28px; padding: 0; } #ag_editor li { margin: 2px 0; }</style>
        ${readOnly ? `
        <div id="agendaPagedArea"></div>
        <div id="ag_editor" style="display:none">${a?.contenu || ''}</div>
        ` : `
        <div id="agPageWrapper" style="width:816px;max-width:calc(100vw - 40px);margin:0 auto;background:#fff;box-shadow:0 2px 20px rgba(0,0,0,.22);position:relative">
          <div style="border-bottom:3px solid #1a237e;padding:12px 64px 10px;display:flex;align-items:center;gap:14px;user-select:none">
            <img src="/Public/logo1.png" style="height:52px;width:52px;object-fit:cover;border-radius:8px;flex-shrink:0" onerror="this.style.display='none'">
            <div style="flex:1">
              <div style="font-weight:800;font-size:12pt;color:#1a237e;letter-spacing:.3px">Association Haïtienne de Hamilton (AHH)</div>
              <div style="font-size:9pt;color:#555;margin-top:2px">Ordre du jour</div>
            </div>
            <div style="font-size:9pt;color:#888;text-align:right">${new Date().toLocaleDateString('fr-CA',{year:'numeric',month:'long',day:'numeric'})}</div>
          </div>
          <div id="ag_editor" style="min-height:944px;padding:40px 64px;font-family:'Times New Roman',serif;font-size:12pt;line-height:1.6;color:#000;outline:none"
            contenteditable="true" spellcheck="true" oninput="agendaChanged()">${a?.contenu || '<ul><li><br></li></ul>'}</div>
          <div style="border-top:2px solid #1a237e;padding:8px 64px;display:flex;justify-content:space-between;align-items:center;font-size:8pt;color:#888;user-select:none">
            <span>Association Haïtienne de Hamilton — Hamilton, Ontario, Canada</span>
            <span>Document officiel — confidentiel</span>
          </div>
        </div>
        `}
      </div>
    </div>
  `);

  if (readOnly) {
    setTimeout(() => _paginateAgendaReadOnly(a?.contenu || ''), 80);
  } else {
    setTimeout(() => {
      const editor = document.getElementById('ag_editor');
      if (!editor) return;
      editor.focus();
      _updateLivePagination('ag_editor', 'Ordre du jour');
      // Tab / Shift+Tab pour indenter/désindenter comme un vrai document à puces
      editor.addEventListener('keydown', e => {
        if (e.key === 'Tab') {
          e.preventDefault();
          document.execCommand(e.shiftKey ? 'outdent' : 'indent');
          _fixListNesting('ag_editor');
          _collapseSelectionToEnd();
          _updateLivePagination('ag_editor', 'Ordre du jour');
        }
      });
    }, 50);
  }
}

function agendaChanged() {
  clearTimeout(_agLiveTimer);
  _agLiveTimer = setTimeout(() => _updateLivePagination('ag_editor', 'Ordre du jour'), 500);
}

async function saveAgendaEditor(id) {
  const editor = document.getElementById('ag_editor');
  if (!editor) return;
  const body = {
    titre: document.getElementById('ag_titre')?.value || 'Sans titre',
    contenu: _getCleanContent('ag_editor'),
    date_reunion: document.getElementById('ag_date')?.value || new Date().toISOString().slice(0,10),
  };
  try {
    if (id) {
      const r = await api('/agendas/' + id, { method:'PUT', body: JSON.stringify(body) });
      if (r?.signatures_annulees > 0) toast('⚠️ Signatures annulées — le document a été modifié', true);
      const s = document.getElementById('agendaStatus');
      if (s) s.textContent = '✅ Sauvegardé ' + new Date().toLocaleTimeString('fr-CA',{hour:'2-digit',minute:'2-digit'});
      else toast('Ordre du jour sauvegardé');
    } else {
      const r = await api('/agendas', { method:'POST', body: JSON.stringify(body) });
      toast('Ordre du jour créé');
      const fresh = await api('/agendas/' + r.id);
      openAgendaEditor(fresh);
    }
  } catch(e) { toast(e.message, true); }
}

function openAgendaSignatureModal(agendaId, titre) {
  openModal(`✍️ Signer — ${titre}`, `
    <p style="font-size:.85rem;color:var(--muted);margin-bottom:12px">Dessinez votre signature dans la zone ci-dessous. Elle sera horodatée et liée à votre compte.<br>
    <strong style="color:#1b5e20">⚠️ Le créateur de l'ordre du jour doit signer en premier ; 2 autres membres du comité peuvent ensuite signer. Après 3 signatures, l'ordre du jour sera verrouillé et ne pourra plus être modifié.</strong></p>
    <canvas id="agendaSigCanvas" width="540" height="160" style="border:1px solid #ccc;border-radius:8px;cursor:crosshair;display:block;width:100%;touch-action:none"></canvas>
    <div style="margin-top:8px;display:flex;gap:8px">
      <button class="btn btn-sm btn-ghost" onclick="_clearAgendaCanvas()">🗑 Effacer</button>
    </div>
    <div style="margin-top:16px;display:flex;gap:8px">
      <button class="btn btn-primary" onclick="_saveAgendaSignature(${agendaId})">✅ Signer le document</button>
      <button class="btn btn-outline" onclick="closeModal()">Annuler</button>
    </div>
  `);
  setTimeout(() => {
    const canvas = document.getElementById('agendaSigCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let drawing = false;
    const getPos = e => {
      const r = canvas.getBoundingClientRect();
      const src = e.touches ? e.touches[0] : e;
      return { x: (src.clientX - r.left) * (canvas.width / r.width), y: (src.clientY - r.top) * (canvas.height / r.height) };
    };
    canvas.addEventListener('mousedown', e => { drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('mousemove', e => { if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); });
    canvas.addEventListener('mouseup', () => { drawing = false; });
    canvas.addEventListener('touchstart', e => { e.preventDefault(); drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }, { passive: false });
    canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); }, { passive: false });
    canvas.addEventListener('touchend', () => { drawing = false; });
  }, 50);
}
function _clearAgendaCanvas() {
  const c = document.getElementById('agendaSigCanvas');
  if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
}
async function _saveAgendaSignature(agendaId) {
  const canvas = document.getElementById('agendaSigCanvas');
  if (!canvas) return;
  const blank = document.createElement('canvas'); blank.width = canvas.width; blank.height = canvas.height;
  if (canvas.toDataURL() === blank.toDataURL()) return toast('Veuillez dessiner votre signature', true);
  const signature_data = canvas.toDataURL('image/png');
  try {
    const r = await api(`/agendas/${agendaId}/sign`, { method:'POST', body: JSON.stringify({ signature_data }) });
    closeModal();
    if (r.verrouille) toast(`🔒 Ordre du jour verrouillé — ${r.nb_signatures} signatures collectées`);
    else toast(`✅ Signature enregistrée (${r.nb_signatures}/3 pour verrouiller)`);
    const fresh = await api('/agendas/' + agendaId);
    openAgendaEditor(fresh);
  } catch(e) { toast(e.message, true); }
}

