async function emailTemplateEdit(id) {
  try {
    const templates = await api('/email-templates');
    const t = templates.find(x => x.id === id);
    if (t) emailTemplateShowForm(t);
  } catch(e) { toast(e.message, true); }
}

async function emailTemplatePreview(id) {
  try {
    const templates = await api('/email-templates');
    const t = templates.find(x => x.id === id);
    if (!t) return;
    const previewArea = document.getElementById('emailTplPreviewArea');
    previewArea.innerHTML = `
      <div style="border:1px solid #e0e0e0;border-radius:10px;padding:20px;margin-top:8px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
          <h4 style="margin:0">Aperçu : ${escHtml(t.nom)}</h4>
          <button class="btn btn-ghost btn-sm" onclick="document.getElementById('emailTplPreviewArea').innerHTML=''">Fermer</button>
        </div>
        <div style="background:#f5f5f5;padding:12px;border-radius:8px;margin-bottom:12px">
          <strong>Sujet :</strong> ${escHtml(t.sujet)}
        </div>
        <div style="background:#fff;padding:16px;border:1px solid #eee;border-radius:8px;white-space:pre-wrap;font-size:.9rem;line-height:1.6">${escHtml(t.corps || 'Aucun contenu')}</div>
      </div>`;
  } catch(e) { toast(e.message, true); }
}

async function emailTemplateDelete(id) {
  if (!confirm('Supprimer ce modèle ?')) return;
  try {
    await api('/email-templates/' + id, { method:'DELETE' });
    toast('Modèle supprimé');
    await emailTemplatesView();
  } catch(e) { toast(e.message, true); }
}

// ══ DÉLÉGATIONS DE SCAN (vue complète) ═════════════════════════════════════
async function scanDelegationsListView() {
  if (!can.executive()) { toast('Accès réservé au comité', true); return; }
  try {
    const [delegations, acts] = await Promise.all([
      api('/scan-delegations'),
      api('/activities')
    ]);
    const activeActs = acts.filter(a => a.statut === 'planifiee' || a.statut === 'en_cours');

    setContent(`
      <div class="page-header">
        <div><h2>📱 Déléguer un scanner</h2><p>Donnez à un membre le droit de scanner des billets ou cartes lors d'un événement.</p></div>
      </div>

      <div class="table-card" style="margin-bottom:18px">
        <div class="table-card-header"><h3>Nouvelle délégation</h3></div>
        <div style="padding:16px">
          <div class="form-row">
            <div class="form-group" style="position:relative">
              <label>Membre</label>
              <input id="sdSearch" autocomplete="off" placeholder="Tapez un nom..." oninput="_taskSearchMember(this.value);document.getElementById('sdDropdown').id='taskAssigneDropdown'">
              <input id="sdUserId" type="hidden">
              <div id="sdDropdown" style="position:absolute;top:100%;left:0;right:0;z-index:50;background:#fff;border:1px solid #ddd;border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.15);max-height:180px;overflow-y:auto;display:none"></div>
            </div>
            <div class="form-group">
              <label>Activité</label>
              <select id="sdActivity">
                <option value="">Toutes les activités</option>
                ${activeActs.map(a => `<option value="${a.id}">${escHtml(a.titre)}</option>`).join('')}
              </select>
            </div>
          </div>
          <div class="form-row">
            <div class="form-group">
              <label>Expiration</label>
              <input type="datetime-local" id="sdExpiration" value="${new Date(Date.now()+24*60*60*1000).toISOString().slice(0,16)}">
            </div>
            <input type="hidden" id="sdType" value="tous">
          </div>
          <button class="btn btn-primary" onclick="_sdCreate()">Déléguer le scanner</button>
        </div>
      </div>

      <div class="table-card">
        <div class="table-card-header"><h3>Délégations actives (${delegations.length})</h3></div>
        <div class="table-wrapper"><table>
          <thead><tr><th>Membre</th><th>Activité</th><th>Expiration</th><th>Actions</th></tr></thead>
          <tbody>
            ${delegations.length ? delegations.map(d => `<tr>
              <td><strong>${escHtml((d.prenom||'') + ' ' + (d.nom||'') || '–')}</strong><br><span style="font-size:.75rem;color:var(--muted)">${escHtml(d.email||'')}</span></td>
              <td>${escHtml(d.activite_titre || d.activity_titre || 'Toutes')}</td>
              <td>${d.date_expiration ? fmt(d.date_expiration) : 'Illimitée'}</td>
              <td><button class="btn btn-ghost btn-sm" style="color:#c62828" onclick="_sdRevoke(${d.id})">Révoquer</button></td>
            </tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--muted);padding:24px">Aucune délégation active</td></tr>'}
          </tbody>
        </table></div>
      </div>
    `);

    // Réutiliser le dropdown de recherche de membres
    setTimeout(() => {
      const dd = document.getElementById('sdDropdown');
      if (dd) {
        dd.id = 'taskAssigneDropdown';
        window._taskSelectMember = function(id, nom) {
          document.getElementById('sdUserId').value = id;
          document.getElementById('sdSearch').value = nom;
          document.getElementById('taskAssigneDropdown').style.display = 'none';
        };
      }
    }, 100);
  } catch(e) { toast(e.message, true); }
}

async function _sdCreate() {
  const userId = document.getElementById('sdUserId')?.value;
  const actId = document.getElementById('sdActivity')?.value || null;
  const type = document.getElementById('sdType')?.value || 'billets';
  const expiration = document.getElementById('sdExpiration')?.value || null;
  if (!userId) { toast('Sélectionnez un membre', true); return; }
  try {
    await api('/scan-delegations', { method:'POST', body: JSON.stringify({ user_id: parseInt(userId), activity_id: actId ? parseInt(actId) : null, type, date_expiration: expiration }) });
    toast('✅ Lecteur délégué');
    scanDelegationsListView();
  } catch(e) { toast(e.message, true); }
}

async function _sdRevoke(id) {
  if (!confirm('Révoquer cette délégation ?')) return;
  try {
    await api('/scan-delegations/' + id, { method:'DELETE' });
    toast('Délégation révoquée');
    scanDelegationsListView();
  } catch(e) { toast(e.message, true); }
}

// ══ DÉLÉGATION DE PRÉSIDENCE (INTÉRIM) ══════════════════════════════════════
async function presidenceDelegationView() {
  if (!can.executive()) { toast('Accès réservé au comité', true); return; }
  if (!document.getElementById('gouvernanceHubBody')) { return gouvernanceHubView('delegation'); }
  try {
    const [history, active] = await Promise.all([
      api('/presidence-delegations'),
      api('/presidence-delegations/active').catch(() => null)
    ]);

    document.getElementById('gouvernanceHubBody').innerHTML = `
      <p style="color:var(--muted);font-size:.85rem;margin-bottom:16px">Désignez un membre du comité comme président(e) par intérim pendant une absence.</p>

      ${active ? `
      <div class="table-card" style="margin-bottom:18px;border-left:4px solid #f9a825">
        <div style="padding:16px;display:flex;align-items:center;gap:14px">
          <span style="font-size:1.6rem">🎗️</span>
          <div style="flex:1">
            <div style="font-weight:700">Présidence par intérim active : ${escHtml(active.prenom)} ${escHtml(active.nom)}</div>
            <div style="font-size:.82rem;color:var(--muted)">${active.motif ? escHtml(active.motif) + ' — ' : ''}depuis le ${fmt(active.date_creation)}${active.date_expiration ? ' · jusqu\'au ' + fmt(active.date_expiration) : ''}</div>
          </div>
          ${can.admin() ? `<button class="btn btn-ghost btn-sm" style="color:#c62828" onclick="_pdRevoke(${active.id})">Révoquer</button>` : ''}
        </div>
      </div>` : ''}

      ${can.admin() && !active ? `
      <div class="table-card" style="margin-bottom:18px">
        <div class="table-card-header"><h3>Nouvelle délégation</h3></div>
        <div style="padding:16px">
          <div class="form-row">
            <div class="form-group" style="position:relative">
              <label>Membre du comité</label>
              <input id="pdSearch" autocomplete="off" placeholder="Tapez un nom..." oninput="_taskSearchMember(this.value);document.getElementById('pdDropdown').id='taskAssigneDropdown'">
              <input id="pdUserId" type="hidden">
              <div id="pdDropdown" style="position:absolute;top:100%;left:0;right:0;z-index:50;background:#fff;border:1px solid #ddd;border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.15);max-height:180px;overflow-y:auto;display:none"></div>
            </div>
            <div class="form-group">
              <label>Jusqu'au (optionnel)</label>
              <input type="date" id="pdExpiration">
            </div>
          </div>
          <div class="form-group"><label>Motif</label><input id="pdMotif" placeholder="Ex. Vacances, congé maladie..."/></div>
          <button class="btn btn-primary" onclick="_pdCreate()">Déléguer la présidence</button>
        </div>
      </div>` : ''}

      <div class="table-card">
        <div class="table-card-header"><h3>Historique</h3></div>
        <div class="table-wrapper"><table>
          <thead><tr><th>Membre</th><th>Délégué par</th><th>Motif</th><th>Début</th><th>Fin</th><th>Statut</th></tr></thead>
          <tbody>
            ${history.length ? history.map(d => `<tr>
              <td><strong>${escHtml(d.prenom)} ${escHtml(d.nom)}</strong></td>
              <td>${escHtml(d.delegue_par_prenom)} ${escHtml(d.delegue_par_nom)}</td>
              <td>${escHtml(d.motif || '–')}</td>
              <td>${fmt(d.date_creation)}</td>
              <td>${d.date_expiration ? fmt(d.date_expiration) : '–'}</td>
              <td>${d.actif ? pill('Active','bp-green') : pill('Terminée','bp-gray')}</td>
            </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--muted);padding:24px">Aucune délégation enregistrée</td></tr>'}
          </tbody>
        </table></div>
      </div>
    `;

    setTimeout(() => {
      const dd = document.getElementById('pdDropdown');
      if (dd) {
        dd.id = 'taskAssigneDropdown';
        window._taskSelectMember = function(id, nom) {
          document.getElementById('pdUserId').value = id;
          document.getElementById('pdSearch').value = nom;
          document.getElementById('taskAssigneDropdown').style.display = 'none';
        };
      }
    }, 100);
  } catch(e) { toast(e.message, true); }
}

async function _pdCreate() {
  const userId = document.getElementById('pdUserId')?.value;
  const motif = document.getElementById('pdMotif')?.value || '';
  const expiration = document.getElementById('pdExpiration')?.value || null;
  if (!userId) { toast('Sélectionnez un membre', true); return; }
  try {
    await api('/presidence-delegations', { method:'POST', body: JSON.stringify({ user_id: parseInt(userId), motif, date_expiration: expiration }) });
    toast('✅ Présidence déléguée');
    presidenceDelegationView();
  } catch(e) { toast(e.message, true); }
}

async function _pdRevoke(id) {
  if (!confirm('Révoquer cette délégation de présidence ?')) return;
  try {
    await api('/presidence-delegations/' + id, { method:'DELETE' });
    toast('Délégation révoquée');
    presidenceDelegationView();
  } catch(e) { toast(e.message, true); }
}

// ══ EXPORT DATA ════════════════════════════════════════════════════════════
async function exportDataView() {
  try {
    const backupsHtml = can.admin() ? `
      <div class="table-card" style="margin-top:20px">
        <div class="table-card-header">
          <h3>Sauvegardes</h3>
          <button class="btn btn-primary btn-sm" onclick="exportCreateBackup()">Créer une sauvegarde</button>
        </div>
        <div id="backupsList" style="padding:16px">
          <div style="text-align:center;color:var(--muted);padding:20px">Chargement...</div>
        </div>
      </div>` : '';

    setContent(`
      <div class="table-card">
        <div class="table-card-header"><h3>Export de données</h3></div>
        <div style="padding:16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px">
          <div style="background:#fff;border-radius:12px;padding:20px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.08);border:1px solid #eee">
            <div style="font-size:2.5rem;margin-bottom:8px">👥</div>
            <div style="font-weight:700;margin-bottom:4px">Export Membres</div>
            <div style="font-size:.85rem;color:var(--muted);margin-bottom:16px">Télécharger la liste complète des membres en format CSV</div>
            <button class="btn btn-primary btn-sm" onclick="window.open('${BASE}/api/export/membres.csv?token=${TOKEN}')">Télécharger CSV</button>
          </div>
          <div style="background:#fff;border-radius:12px;padding:20px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.08);border:1px solid #eee">
            <div style="font-size:2.5rem;margin-bottom:8px">💰</div>
            <div style="font-weight:700;margin-bottom:4px">Export Paiements</div>
            <div style="font-size:.85rem;color:var(--muted);margin-bottom:16px">Télécharger l'historique des paiements en format CSV</div>
            <button class="btn btn-primary btn-sm" onclick="window.open('${BASE}/api/export/paiements.csv?token=${TOKEN}')">Télécharger CSV</button>
          </div>
          <div style="background:#fff;border-radius:12px;padding:20px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.08);border:1px solid #eee">
            <div style="font-size:2.5rem;margin-bottom:8px">📅</div>
            <div style="font-weight:700;margin-bottom:4px">Export Activités</div>
            <div style="font-size:.85rem;color:var(--muted);margin-bottom:16px">Télécharger la liste des activités en format CSV</div>
            <button class="btn btn-primary btn-sm" onclick="window.open('${BASE}/api/export/activities?token=${TOKEN}')">Télécharger CSV</button>
          </div>
        </div>
      </div>
      ${backupsHtml}`);

    if (can.admin()) exportLoadBackups();
  } catch(e) { toast(e.message, true); }
}

async function exportLoadBackups() {
  try {
    const backups = await api('/backups');
    const container = document.getElementById('backupsList');
    if (!container) return;
    if (!backups || !backups.length) {
      container.innerHTML = '<p style="text-align:center;color:var(--muted);padding:20px">Aucune sauvegarde disponible</p>';
      return;
    }
    container.innerHTML = `
      <table class="data-table">
        <thead><tr><th>Date</th><th>Fichier</th><th>Taille</th></tr></thead>
        <tbody>${backups.map(b => `<tr>
          <td>${fmt(b.date)}</td>
          <td>${escHtml(b.filename)}</td>
          <td>${b.size ? (b.size / 1024 / 1024).toFixed(2) + ' Mo' : '–'}</td>
        </tr>`).join('')}</tbody>
      </table>`;
  } catch(e) {
    const container = document.getElementById('backupsList');
    if (container) container.innerHTML = '<p style="text-align:center;color:#c62828;padding:20px">Erreur de chargement des sauvegardes</p>';
  }
}

async function exportCreateBackup() {
  try {
    await api('/backup', { method:'POST' });
    toast('Sauvegarde créée');
    await exportLoadBackups();
  } catch(e) { toast(e.message, true); }
}

// ══ ANNUAL REPORT (onglet "Annuel" du hub Rapports) ═══════════════════════════
async function _rapportsRenderAnnuel() {
  try {
    const currentYear = new Date().getFullYear();
    const yearSelect = `
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:20px">
        <label style="font-weight:600">Année :</label>
        <select id="annualYear" onchange="annualReportLoad()" style="padding:6px 12px;border-radius:6px;border:1px solid #ddd;font-size:1rem">
          ${[currentYear, currentYear - 1, currentYear - 2, currentYear - 3].map(y => `<option value="${y}">${y}</option>`).join('')}
        </select>
        <button class="btn btn-ghost btn-sm" onclick="window.print()" style="margin-left:auto">🖨 Imprimer</button>
      </div>`;

    document.getElementById('rapportsHubBody').innerHTML = `
      <div class="table-card">
        <div class="table-card-header"><h3>Rapport annuel</h3></div>
        <div style="padding:16px">
          ${yearSelect}
          <div id="annualReportContent"><div class="loading-screen"><div class="spinner"></div><p>Chargement...</p></div></div>
        </div>
      </div>`;

    await annualReportLoad();
  } catch(e) { toast(e.message, true); }
}

async function annualReportLoad() {
  try {
    const year = document.getElementById('annualYear').value;
    const report = await api('/reports/annual?annee=' + year);
    const container = document.getElementById('annualReportContent');
    if (!container) return;

    const kpi = (value, label) => `
      <div style="background:#fff;border-radius:12px;padding:20px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.08)">
        <div style="font-size:2rem;font-weight:800;color:var(--accent)">${value}</div>
        <div style="font-size:.85rem;color:var(--muted);margin-top:4px">${label}</div>
      </div>`;

    const kpisHtml = `
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:16px;margin-bottom:24px">
        ${kpi(report.total_membres || 0, 'Total membres')}
        ${kpi(report.nouveaux_membres || 0, 'Nouveaux membres')}
        ${kpi(fmtMoney(report.revenus || 0), 'Revenus')}
        ${kpi(fmtMoney(report.depenses || 0), 'Dépenses')}
        ${kpi(report.total_activites || 0, 'Activités')}
        ${kpi(report.total_participants || 0, 'Participants')}
        ${kpi((report.taux_recouvrement || 0) + '%', 'Taux recouvrement')}
      </div>`;

    const planRows = (report.plan_distribution || []).map(p => `<tr>
      <td>${escHtml(p.plan || p.nom || '–')}</td>
      <td style="text-align:center">${p.count || p.nombre || 0}</td>
      <td style="text-align:right">${fmtMoney(p.montant || 0)}</td>
    </tr>`).join('');

    const planTable = planRows ? `
      <div style="margin-bottom:24px">
        <h4 style="margin-bottom:12px">Distribution par plan</h4>
        <table class="data-table">
          <thead><tr><th>Plan</th><th style="text-align:center">Nombre</th><th style="text-align:right">Montant</th></tr></thead>
          <tbody>${planRows}</tbody>
        </table>
      </div>` : '';

    const topActivities = (report.top_activites || []).map((a, i) => `<tr>
      <td style="font-weight:600">${i + 1}</td>
      <td>${escHtml(a.titre || a.nom || '–')}</td>
      <td style="text-align:center">${a.participants || a.nb_participants || 0}</td>
      <td>${fmt(a.date)}</td>
    </tr>`).join('');

    const topTable = topActivities ? `
      <div>
        <h4 style="margin-bottom:12px">Activités les plus populaires</h4>
        <table class="data-table">
          <thead><tr><th>#</th><th>Activité</th><th style="text-align:center">Participants</th><th>Date</th></tr></thead>
          <tbody>${topActivities}</tbody>
        </table>
      </div>` : '';

    container.innerHTML = kpisHtml + planTable + topTable;
  } catch(e) {
    const container = document.getElementById('annualReportContent');
    if (container) container.innerHTML = '<p style="text-align:center;color:#c62828;padding:20px">Erreur de chargement du rapport</p>';
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// DELEGATION DE SCAN
// ══════════════════════════════════════════════════════════════════════════════

async function openScanDelegation(actId, titre) {
  let delegations = [];
  try { delegations = await api('/scan-delegations?activity_id=' + actId); } catch {}

  const delegList = delegations.length
    ? delegations.map(d => `<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:var(--off);border-radius:8px;margin-bottom:6px">
        <div>
          <div style="font-weight:600;font-size:.88rem">${escHtml(d.prenom)} ${escHtml(d.nom)}</div>
          <div style="font-size:.72rem;color:var(--muted)">${escHtml(d.email)} | Type: ${escHtml(d.type)} | Par: ${escHtml(d.delegue_par_prenom)} ${escHtml(d.delegue_par_nom)}</div>
          ${d.date_expiration ? '<div style="font-size:.68rem;color:#e65100">Expire: ' + new Date(d.date_expiration).toLocaleString('fr-CA') + '</div>' : ''}
        </div>
        <button class="btn btn-sm" style="background:#c62828;color:#fff;border:none" onclick="revokeScanDelegation(${d.id},${actId},'${titre.replace(/'/g,"\\'")}')">Revoquer</button>
      </div>`).join('')
    : '<p style="color:var(--muted);text-align:center;padding:12px">Aucune delegation active</p>';

  const today = new Date().toISOString().slice(0, 10);

  openModal('Deleguer un scanner — ' + titre, `
    <div style="max-width:600px;margin:0 auto">
      <h3 style="margin-bottom:16px">Delegations actives</h3>
      <div id="scanDelegList">${delegList}</div>

      <div style="border-top:2px solid var(--border);margin:24px 0;padding-top:20px">
        <h3 style="margin-bottom:16px">Nouvelle delegation</h3>
        <div style="margin-bottom:12px">
          <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:4px">Rechercher un membre</label>
          <input type="text" id="sdSearchInput" placeholder="Nom ou courriel..." style="width:100%;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:.88rem" oninput="searchScanDelegate(this.value)"/>
          <div id="sdSearchResults" style="margin-top:4px"></div>
          <input type="hidden" id="sdUserId"/>
          <div id="sdSelectedUser" style="margin-top:6px;font-weight:600;color:var(--g2)"></div>
        </div>
        <div style="display:flex;gap:12px;margin-bottom:12px">
          <div style="flex:1">
            <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:4px">Type</label>
            <select id="sdType" style="width:100%;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:.88rem">
              <option value="billets">Billets</option>
              <option value="cartes">Cartes membres</option>
              <option value="tous">Tous</option>
            </select>
          </div>
          <div style="flex:1">
            <label style="font-size:.82rem;font-weight:600;display:block;margin-bottom:4px">Expiration (optionnel)</label>
            <input type="datetime-local" id="sdExpiration" value="${today}T23:59" style="width:100%;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:.88rem"/>
          </div>
        </div>
        <button class="btn btn-primary" style="width:100%" onclick="createScanDelegation(${actId},'${titre.replace(/'/g,"\\'")}')">Creer la delegation</button>
      </div>
    </div>
  `);
}

let _sdSearchTimer = null;
async function searchScanDelegate(q) {
  clearTimeout(_sdSearchTimer);
  if (q.length < 2) { document.getElementById('sdSearchResults').innerHTML = ''; return; }
  _sdSearchTimer = setTimeout(async () => {
    try {
      const members = await api('/members/search?q=' + encodeURIComponent(q));
      const box = document.getElementById('sdSearchResults');
      box.innerHTML = members.map(m =>
        `<div style="padding:6px 10px;cursor:pointer;border-radius:6px;font-size:.84rem;background:var(--off);margin-bottom:2px" onmouseover="this.style.background='var(--border)'" onmouseout="this.style.background='var(--off)'" onclick="selectScanDelegate(${m.id},'${escHtml(m.prenom)} ${escHtml(m.nom)}','${escHtml(m.email)}')">
          ${escHtml(m.prenom)} ${escHtml(m.nom)} <span style="color:var(--muted);font-size:.75rem">(${escHtml(m.email)})</span>
        </div>`
      ).join('');
    } catch {}
  }, 300);
}

function selectScanDelegate(id, nom, email) {
  document.getElementById('sdUserId').value = id;
  document.getElementById('sdSelectedUser').textContent = nom + ' (' + email + ')';
  document.getElementById('sdSearchResults').innerHTML = '';
  document.getElementById('sdSearchInput').value = nom;
}

async function createScanDelegation(actId, titre) {
  const userId = document.getElementById('sdUserId').value;
  if (!userId) { alert('Veuillez selectionner un membre'); return; }
  const type = document.getElementById('sdType').value;
  const exp = document.getElementById('sdExpiration').value;
  try {
    await api('/scan-delegations', {
      method: 'POST',
      body: JSON.stringify({ activity_id: actId, user_id: parseInt(userId), type: type, date_expiration: exp || null })
    });
    openScanDelegation(actId, titre);
  } catch(e) {
    alert(e.message || 'Erreur lors de la creation');
  }
}

async function revokeScanDelegation(delegId, actId, titre) {
  if (!confirm('Revoquer cette delegation ?')) return;
  try {
    await api('/scan-delegations/' + delegId, { method: 'DELETE' });
    openScanDelegation(actId, titre);
  } catch(e) {
    alert(e.message || 'Erreur');
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// JOURNAL DES SCANS
// ══════════════════════════════════════════════════════════════════════════════

async function viewScanLogs(actId, titre) {
  openModal('📋 Journal des scans — ' + titre, '<div style="text-align:center;padding:30px;color:var(--muted)">Chargement...</div>');
  try {
    const logs = await api('/scan-logs?activity_id=' + actId);
    window._scanLogs = logs || [];
    window._scanLogsSort = { col: 'date_scan', dir: 'desc' };
    window._scanLogsFilter = { search: '', resultat: '' };
    _renderScanLogs();
  } catch(e) {
    document.querySelector('.print-content').innerHTML = '<p style="text-align:center;color:#c62828;padding:20px">' + (e.message || 'Erreur') + '</p>';
  }
}

function _renderScanLogs() {
  const container = document.querySelector('.print-content');
  if (!container) return;
  const logs = window._scanLogs || [];

  const badgeColors = { valide:'#2e7d32', deja_scanne:'#6a1a75', introuvable:'#c62828', invalide:'#e65100' };
  const badgeLabels = { valide:'Valide', deja_scanne:'Déjà scanné', introuvable:'Introuvable', invalide:'Invalide' };
  const stats = {
    total: logs.length,
    valide: logs.filter(l => l.resultat === 'valide').length,
    deja: logs.filter(l => l.resultat === 'deja_scanne').length,
    invalide: logs.filter(l => l.resultat === 'invalide' || l.resultat === 'introuvable').length
  };

  const mkRow = l => {
    const d = new Date(l.date_scan);
    const dateStr = d.toLocaleDateString('fr-CA', {timeZone:'America/Toronto'}) + ' ' + d.toLocaleTimeString('fr-CA', {hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'America/Toronto'});
    const bg = badgeColors[l.resultat] || '#666';
    const label = badgeLabels[l.resultat] || l.resultat;
    const scannerNom = (l.scanner_prenom||'') + ' ' + (l.scanner_nom||'');
    const acheteur = l.acheteur_nom || '';
    const vendeur = l.vendu_par_nom || '';
    const codeAff = l.barcode_data || (l.code_scanne||'').substring(0, 30);
    const detailParts = [l.details||''];
    if (acheteur) detailParts.unshift('🎫 ' + acheteur);
    if (vendeur) detailParts.push('👤 vendu par ' + vendeur);
    const detailStr = detailParts.filter(Boolean).join(' · ');
    const allText = (scannerNom + ' ' + codeAff + ' ' + acheteur + ' ' + vendeur + ' ' + (l.details||'') + ' ' + (l.resultat||'')).toLowerCase();
    return `<tr class="sl-row" data-search="${escHtml(allText)}" data-resultat="${l.resultat}" data-date="${l.date_scan||''}" data-scanner="${escHtml(scannerNom.toLowerCase())}">
      <td style="white-space:nowrap;font-size:.78rem">${dateStr}</td>
      <td style="font-weight:600">${escHtml(scannerNom)}</td>
      <td style="font-size:.76rem;font-family:monospace" title="${escHtml(l.code_scanne||'')}">${escHtml(codeAff)}</td>
      <td><span style="display:inline-block;padding:3px 12px;border-radius:12px;font-size:.72rem;font-weight:700;color:#fff;background:${bg}">${label}</span></td>
      <td style="font-size:.78rem;color:var(--muted)">${escHtml(detailStr)}</td>
    </tr>`;
  };

  const sorted = [...logs].sort((a, b) => new Date(b.date_scan) - new Date(a.date_scan));

  container.innerHTML = `
    <div style="display:flex;gap:12px;margin-bottom:16px;flex-wrap:wrap">
      <div style="background:#e8f5e9;padding:10px 18px;border-radius:10px;text-align:center;flex:1;min-width:80px">
        <div style="font-size:1.3rem;font-weight:800;color:#2e7d32">${stats.valide}</div>
        <div style="font-size:.7rem;color:#2e7d32">Valides</div>
      </div>
      <div style="background:#f3e5f5;padding:10px 18px;border-radius:10px;text-align:center;flex:1;min-width:80px">
        <div style="font-size:1.3rem;font-weight:800;color:#6a1a75">${stats.deja}</div>
        <div style="font-size:.7rem;color:#6a1a75">Doublons</div>
      </div>
      <div style="background:#fdecea;padding:10px 18px;border-radius:10px;text-align:center;flex:1;min-width:80px">
        <div style="font-size:1.3rem;font-weight:800;color:#c62828">${stats.invalide}</div>
        <div style="font-size:.7rem;color:#c62828">Refusés</div>
      </div>
      <div style="background:var(--off);padding:10px 18px;border-radius:10px;text-align:center;flex:1;min-width:80px">
        <div style="font-size:1.3rem;font-weight:800">${stats.total}</div>
        <div style="font-size:.7rem;color:var(--muted)">Total</div>
      </div>
    </div>

    <div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;align-items:center">
      <input type="text" id="slSearch" placeholder="🔍 Rechercher nom, code, détails..."
        oninput="_filterScanRows()"
        style="flex:1;min-width:180px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:.85rem"/>
      <select id="slFilter" onchange="_filterScanRows()" style="padding:8px 10px;border:1px solid var(--border);border-radius:8px;font-size:.85rem">
        <option value="">Tous les résultats</option>
        <option value="valide">✅ Valide</option>
        <option value="deja_scanne">🔄 Déjà scanné</option>
        <option value="invalide">⚠️ Invalide</option>
        <option value="introuvable">❌ Introuvable</option>
      </select>
      <select id="slSort" onchange="_sortScanRows()" style="padding:8px 10px;border:1px solid var(--border);border-radius:8px;font-size:.85rem">
        <option value="desc">Plus récent d'abord</option>
        <option value="asc">Plus ancien d'abord</option>
      </select>
    </div>

    <div id="slCount" style="font-size:.78rem;color:var(--muted);margin-bottom:8px">${logs.length} résultat(s)</div>

    <div style="overflow-x:auto">
      <table class="data-table">
        <thead><tr>
          <th>Date/Heure</th>
          <th>Scanné par</th>
          <th>Code scanné</th>
          <th>Résultat</th>
          <th>Détails / Acheteur</th>
        </tr></thead>
        <tbody id="slBody">${sorted.map(mkRow).join('') || '<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--muted)">Aucun scan</td></tr>'}</tbody>
      </table>
    </div>`;
}

function _filterScanRows() {
  const q = (document.getElementById('slSearch')?.value || '').toLowerCase();
  const r = document.getElementById('slFilter')?.value || '';
  let shown = 0;
  document.querySelectorAll('.sl-row').forEach(row => {
    const matchQ = !q || row.dataset.search.includes(q);
    const matchR = !r || row.dataset.resultat === r;
    const visible = matchQ && matchR;
    row.style.display = visible ? '' : 'none';
    if (visible) shown++;
  });
  const cnt = document.getElementById('slCount');
  if (cnt) cnt.textContent = shown + ' résultat(s) sur ' + (window._scanLogs||[]).length;
}

function _sortScanRows() {
  const dir = document.getElementById('slSort')?.value || 'desc';
  const tbody = document.getElementById('slBody');
  if (!tbody) return;
  const rows = [...tbody.querySelectorAll('.sl-row')];
  rows.sort((a, b) => {
    const da = a.dataset.date, db = b.dataset.date;
    return dir === 'asc' ? da.localeCompare(db) : db.localeCompare(da);
  });
  rows.forEach(r => tbody.appendChild(r));
}

// ══════════════════════════════════════════════════════════════════════════════
// FORMULAIRES — Google Forms-like
// ══════════════════════════════════════════════════════════════════════════════

async function formsMgmtView() {
  let forms = [];
  try { forms = await api('/forms'); } catch(e) { setContent('<div class="empty-state"><p>Erreur : '+escHtml(e.message)+'</p></div>'); return; }
  window._formsList = forms;

  // Les formulaires archivés sont masqués par défaut (même schéma que la page Activités) —
  // il faut cliquer sur "📦 Archivés" pour les voir.
  const showArchived = !!window._formsShowArchived;
  const archivedCount = forms.filter(f => f.statut === 'archivee').length;
  const visible = forms.filter(f => showArchived ? f.statut === 'archivee' : f.statut !== 'archivee');

  const rows = visible.map(f => {
    const statutPill = f.statut === 'archivee'
      ? '<span style="background:var(--off);color:var(--muted);padding:3px 10px;border-radius:12px;font-size:.78rem;font-weight:600">📦 Archivé</span>'
      : f.statut === 'actif'
      ? '<span style="background:#e8f5e9;color:#2e7d32;padding:3px 10px;border-radius:12px;font-size:.78rem;font-weight:600">Actif</span>'
      : '<span style="background:#fce4ec;color:#c62828;padding:3px 10px;border-radius:12px;font-size:.78rem;font-weight:600">Fermé</span>';
    return `<tr>
      <td style="font-weight:600">${escHtml(f.titre)}</td>
      <td style="text-align:center"><span style="background:var(--off);padding:4px 12px;border-radius:8px;font-weight:600">${f.nb_reponses || 0}</span></td>
      <td style="text-align:center">${statutPill}</td>
      <td>${fmt(f.date_creation)}</td>
      <td>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          <button onclick="viewFormResults(${f.id})" style="background:#e3f2fd;color:#1565c0;border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">Résultats</button>
          ${f.statut === 'archivee' ? `
          <button onclick="_unarchiveForm(${f.id})" style="background:#e3f2fd;color:#1565c0;border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">↩️ Restaurer</button>
          ` : `
          <button onclick="openFormBuilder(${f.id})" style="background:#fff3e0;color:#e65100;border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">Modifier</button>
          <button onclick="_copyFormLink(${f.id})" style="background:#e8f5e9;color:#2e7d32;border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">Copier lien</button>
          <button onclick="_archiveForm(${f.id})" style="background:var(--off);color:var(--muted);border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">📦 Archiver</button>
          `}
          <button onclick="_deleteForm(${f.id})" style="background:#fce4ec;color:#c62828;border:none;padding:5px 10px;border-radius:6px;cursor:pointer;font-size:.78rem">Supprimer</button>
        </div>
      </td>
    </tr>`;
  }).join('');

  setContent(`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;flex-wrap:wrap;gap:12px">
      <h2 style="margin:0;font-size:1.3rem">Formulaires</h2>
      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
        <button class="btn btn-sm ${showArchived ? 'btn-primary' : 'btn-ghost'}" onclick="_toggleFormsArchived()">📦 Archivés (${archivedCount})</button>
        <button onclick="openFormBuilder(0)" style="background:var(--g2);color:#fff;border:none;padding:10px 20px;border-radius:8px;cursor:pointer;font-weight:600;font-size:.9rem">+ Nouveau formulaire</button>
      </div>
    </div>
    ${visible.length === 0 ? `<div class="empty-state"><div class="es-icon">📋</div><p>${showArchived ? 'Aucun formulaire archivé' : 'Aucun formulaire créé'}</p>${showArchived ? '' : '<p style="color:var(--muted);font-size:.85rem">Créez votre premier formulaire pour collecter des réponses</p>'}</div>` : `
    <div style="overflow-x:auto">
      <table class="data-table">
        <thead><tr>
          <th>Titre</th>
          <th style="text-align:center">Réponses</th>
          <th style="text-align:center">Statut</th>
          <th>Date création</th>
          <th>Actions</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`}
  `);
}

function _toggleFormsArchived() {
  window._formsShowArchived = !window._formsShowArchived;
  formsMgmtView();
}

async function _archiveForm(formId) {
  try {
    await api('/forms/' + formId + '/archive', { method: 'PATCH' });
    toast('📦 Formulaire archivé');
    formsMgmtView();
  } catch(e) { toast('Erreur : ' + e.message, 'error'); }
}

async function _unarchiveForm(formId) {
  try {
    await api('/forms/' + formId + '/unarchive', { method: 'PATCH' });
    toast('↩️ Formulaire restauré');
    formsMgmtView();
  } catch(e) { toast('Erreur : ' + e.message, 'error'); }
}

function _copyFormLink(formId) {
  const f = (window._formsList || []).find(x => x.id === formId);
  if (!f) return;
  const url = window.location.origin + '/formulaire.html?t=' + f.share_token;
  navigator.clipboard.writeText(url).then(() => toast('Lien copié !')).catch(() => {
    prompt('Copiez ce lien :', url);
  });
}

async function _deleteForm(formId) {
  if (!confirm('Supprimer ce formulaire et toutes ses réponses ?')) return;
  try {
    await api('/forms/' + formId, { method: 'DELETE' });
    toast('Formulaire supprimé');
    formsMgmtView();
  } catch(e) { toast('Erreur : ' + e.message, 'error'); }
}

async function openFormBuilder(formId) {
  window._modalReturnViewId = 'forms-mgmt';
  let form = null;
  let activities = [];
  try { activities = await api('/activities'); } catch {}

  if (formId) {
    try { form = await api('/forms/' + formId); } catch(e) {
      toast('Erreur : ' + e.message, 'error'); return;
    }
  }

  window._formBuilderData = form;
  window._formBuilderFields = form ? (form.fields || []) : [];

  const isNew = !formId;
  const title = isNew ? 'Nouveau formulaire' : 'Modifier : ' + escHtml(form.titre);

  const actOptions = activities.map(a =>
    `<option value="${a.id}" ${form && form.activity_id === a.id ? 'selected' : ''}>${escHtml(a.titre)}</option>`
  ).join('');

  const shareUrl = form ? (window.location.origin + '/formulaire.html?t=' + form.share_token) : '';

  setContent(`
    <div style="padding-bottom:40px">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:24px;padding-bottom:16px;border-bottom:1px solid var(--border)">
        <button onclick="showView('forms-mgmt')" style="display:flex;align-items:center;gap:6px;background:var(--off);border:1px solid var(--border);border-radius:8px;padding:7px 14px;cursor:pointer;font-size:.84rem;color:var(--text)">← Retour</button>
        <h2 style="margin:0;font-size:1.18rem;font-weight:700">${title}</h2>
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px">
        <div style="grid-column:1/-1">
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Titre *</label>
          <input id="fb_titre" type="text" value="${form ? escHtml(form.titre) : ''}" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem" required/>
        </div>
        <div style="grid-column:1/-1">
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Description</label>
          <textarea id="fb_description" rows="3" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem;resize:vertical">${form ? escHtml(form.description || '') : ''}</textarea>
        </div>
        <div>
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Activité liée (optionnel)</label>
          <select id="fb_activity" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem">
            <option value="">Aucune</option>
            ${actOptions}
          </select>
        </div>
        <div>
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Statut</label>
          <select id="fb_statut" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem">
            <option value="actif" ${!form || form.statut === 'actif' ? 'selected' : ''}>Actif</option>
            <option value="ferme" ${form && form.statut === 'ferme' ? 'selected' : ''}>Fermé</option>
          </select>
        </div>
        <div>
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Date et heure de fin (optionnel)</label>
          <input id="fb_date_fermeture" type="datetime-local" value="${form && form.date_fermeture ? form.date_fermeture.slice(0,16) : ''}" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem"/>
          <small style="color:var(--muted)">Après cette date, seul le comité peut encore soumettre une réponse (au nom d'un membre).</small>
        </div>
        <div>
          <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:4px">Message de fin</label>
          <input id="fb_message_fin" type="text" value="${form ? escHtml(form.message_fin || '') : 'Merci pour votre réponse !'}" style="width:100%;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.9rem"/>
        </div>
        <div style="display:flex;flex-direction:column;gap:8px;justify-content:center">
          <label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer">
            <input type="checkbox" id="fb_anonymous" ${!form || form.allow_anonymous ? 'checked' : ''}/> Réponses anonymes autorisées
          </label>
          <label style="display:flex;align-items:center;gap:8px;font-size:.85rem;cursor:pointer">
            <input type="checkbox" id="fb_redirect" ${!form || form.redirect_adhesion ? 'checked' : ''}/> Proposer l'adhésion après soumission
          </label>
        </div>
      </div>

      ${form ? `<div style="margin-bottom:24px">
        <label style="font-weight:600;font-size:.85rem;display:block;margin-bottom:8px">Image du formulaire</label>
        ${form.image_path ? '<img src="'+BASE+escHtml(form.image_path)+'" style="max-width:300px;max-height:150px;border-radius:8px;margin-bottom:8px;display:block" />' : ''}
        <input type="file" id="fb_image" accept="image/*" onchange="_uploadFormImage(${form.id})" style="font-size:.85rem"/>
      </div>` : ''}

      <div style="margin-bottom:24px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
          <h3 style="margin:0;font-size:1.05rem;font-weight:700">Champs du formulaire</h3>
          <button onclick="_addFieldInline()" style="background:var(--g2);color:#fff;border:none;padding:8px 16px;border-radius:8px;cursor:pointer;font-weight:600;font-size:.82rem">+ Ajouter un champ</button>
        </div>
        <div id="fb_fieldsList">${_renderFieldsList()}</div>
        <div id="fb_newFieldForm" style="display:none"></div>
      </div>

      <div style="display:flex;gap:12px;flex-wrap:wrap">
        <button onclick="_saveFormBuilder(${formId || 0})" style="background:var(--g2);color:#fff;border:none;padding:12px 28px;border-radius:8px;cursor:pointer;font-weight:600;font-size:.9rem">${isNew ? 'Créer le formulaire' : 'Enregistrer'}</button>
        ${form ? `<button onclick="_exportFormCSV(${form.id})" style="background:#e3f2fd;color:#1565c0;border:none;padding:12px 20px;border-radius:8px;cursor:pointer;font-weight:600;font-size:.85rem">Export CSV</button>` : ''}
      </div>

      ${form ? `<div style="margin-top:28px;padding:20px;background:var(--off);border-radius:12px;border:1px solid var(--border)">
        <h3 style="margin:0 0 12px;font-size:1rem;font-weight:700">Partager ce formulaire</h3>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px">
          <input id="fb_shareUrl" type="text" readonly value="${escHtml(shareUrl)}" style="flex:1;min-width:200px;padding:10px 14px;border:1.5px solid var(--border);border-radius:8px;font-size:.82rem;background:#fff"/>
          <button onclick="navigator.clipboard.writeText(document.getElementById('fb_shareUrl').value);toast('Lien copié !')" style="background:var(--g2);color:#fff;border:none;padding:10px 16px;border-radius:8px;cursor:pointer;font-size:.82rem;font-weight:600">Copier</button>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap">
          <a href="https://wa.me/?text=${encodeURIComponent(form.titre + '\n' + shareUrl)}" target="_blank" style="display:inline-flex;align-items:center;gap:6px;background:#25d366;color:#fff;padding:8px 16px;border-radius:8px;text-decoration:none;font-size:.82rem;font-weight:600">WhatsApp</a>
          <a href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}" target="_blank" style="display:inline-flex;align-items:center;gap:6px;background:#1877f2;color:#fff;padding:8px 16px;border-radius:8px;text-decoration:none;font-size:.82rem;font-weight:600">Facebook</a>
        </div>
      </div>` : ''}
    </div>
  `);
}

function _renderFieldsList() {
  const fields = window._formBuilderFields || [];
  if (fields.length === 0) return '<p style="color:var(--muted);font-size:.85rem;padding:12px">Aucun champ ajouté</p>';
  return fields.map((f, idx) => {
    const typeLabels = {text:'Texte',email:'Courriel',telephone:'Téléphone',textarea:'Zone de texte',select:'Liste déroulante',radio:'Choix unique',checkbox:'Cases à cocher',number:'Nombre',date:'Date',signature:'Signature'};
    const typePill = '<span style="background:#e3f2fd;color:#1565c0;padding:2px 8px;border-radius:6px;font-size:.72rem;font-weight:600">' + (typeLabels[f.type] || f.type) + '</span>';
    const reqBadge = f.obligatoire ? ' <span style="color:#d32f2f;font-size:.72rem;font-weight:600">obligatoire</span>' : '';
    return `<div style="display:flex;align-items:center;gap:10px;padding:12px 16px;background:#fff;border:1px solid var(--border);border-radius:8px;margin-bottom:6px" data-field-idx="${idx}">
      <span style="cursor:grab;color:var(--muted);font-size:1.1rem">⠿</span>
      <div style="flex:1;min-width:0">
        <div style="font-weight:600;font-size:.88rem">${escHtml(f.label)} ${typePill}${reqBadge}</div>
        ${f.description ? '<div style="font-size:.78rem;color:var(--muted)">'+escHtml(f.description)+'</div>' : ''}
      </div>
      <button onclick="_editFieldInline(${idx})" style="background:var(--off);border:1px solid var(--border);border-radius:6px;padding:5px 10px;cursor:pointer;font-size:.78rem">Modifier</button>
      <button onclick="_removeField(${idx})" style="background:#fce4ec;color:#c62828;border:none;border-radius:6px;padding:5px 10px;cursor:pointer;font-size:.78rem">Supprimer</button>
    </div>`;
  }).join('');
}

function _addFieldInline() {
  const container = document.getElementById('fb_newFieldForm');
  container.style.display = 'block';
  container.innerHTML = _fieldFormHtml(null, '_saveNewField');
  // Reset tous les champs du formulaire inline
  var el = document.getElementById('nf_label'); if(el) el.value = '';
  var el2 = document.getElementById('nf_desc'); if(el2) el2.value = '';
  var el3 = document.getElementById('nf_type'); if(el3) el3.value = 'text';
  var el4 = document.getElementById('nf_required'); if(el4) el4.checked = false;
  var el5 = document.getElementById('nf_options'); if(el5) el5.value = '';
  _toggleFieldOptions();
}

function _editFieldInline(idx) {
  const field = window._formBuilderFields[idx];
  if (!field) return;
  const container = document.getElementById('fb_newFieldForm');
  container.style.display = 'block';
  window._editingFieldIdx = idx;
  container.innerHTML = _fieldFormHtml(field, '_saveEditField');
}

function _fieldFormHtml(field, saveFn) {
  const types = [
    {v:'text',l:'Texte'},{v:'email',l:'Courriel'},{v:'telephone',l:'Téléphone'},{v:'textarea',l:'Zone de texte'},
    {v:'select',l:'Liste déroulante'},{v:'radio',l:'Choix unique'},{v:'checkbox',l:'Cases à cocher'},
    {v:'number',l:'Nombre'},{v:'date',l:'Date'},{v:'signature',l:'Signature (tracée)'}
  ];
  const typeOpts = types.map(t => `<option value="${t.v}" ${field && field.type === t.v ? 'selected' : ''}>${t.l}</option>`).join('');
  let existingOpts = '';
  if (field && field.options_json) {
    try { existingOpts = JSON.parse(field.options_json).join('\n'); } catch {}
  }
  return `<div style="padding:16px;background:#f5f5f5;border-radius:10px;border:1px solid var(--border);margin-top:12px">
    <h4 style="margin:0 0 12px;font-size:.92rem">${field ? 'Modifier le champ' : 'Nouveau champ'}</h4>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div>
        <label style="font-size:.8rem;font-weight:600;display:block;margin-bottom:3px">Type</label>
        <select id="nf_type" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font-size:.85rem" onchange="_toggleFieldOptions()">
          ${typeOpts}
        </select>
      </div>
      <div>
        <label style="font-size:.8rem;font-weight:600;display:block;margin-bottom:3px">Libellé *</label>
        <input id="nf_label" type="text" value="${field ? escHtml(field.label) : ''}" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font-size:.85rem"/>
      </div>
    </div>
    <div style="margin-bottom:10px">
      <label style="font-size:.8rem;font-weight:600;display:block;margin-bottom:3px">Description (optionnel)</label>
      <input id="nf_desc" type="text" value="${field && field.description ? escHtml(field.description) : ''}" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font-size:.85rem"/>
    </div>
    <div id="nf_optionsWrap" style="margin-bottom:10px;display:${field && ['select','radio','checkbox'].includes(field.type) ? 'block' : 'none'}">
      <label style="font-size:.8rem;font-weight:600;display:block;margin-bottom:3px">Options (une par ligne)</label>
      <textarea id="nf_options" rows="3" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;font-size:.85rem">${existingOpts}</textarea>
    </div>
    <label style="display:flex;align-items:center;gap:6px;font-size:.82rem;margin-bottom:14px;cursor:pointer">
      <input type="checkbox" id="nf_required" ${field && field.obligatoire ? 'checked' : ''}/> Obligatoire
    </label>
    <div style="display:flex;gap:8px">
      <button onclick="${saveFn}()" style="background:var(--g2);color:#fff;border:none;padding:8px 18px;border-radius:6px;cursor:pointer;font-size:.82rem;font-weight:600">Enregistrer</button>
      <button onclick="document.getElementById('fb_newFieldForm').style.display='none'" style="background:var(--off);border:1px solid var(--border);padding:8px 18px;border-radius:6px;cursor:pointer;font-size:.82rem">Annuler</button>
    </div>
  </div>`;
}

function _toggleFieldOptions() {
  const type = document.getElementById('nf_type').value;
  const wrap = document.getElementById('nf_optionsWrap');
  if (wrap) wrap.style.display = ['select','radio','checkbox'].includes(type) ? 'block' : 'none';
}

function _collectFieldData() {
  const label = document.getElementById('nf_label').value.trim();
  if (!label) { toast('Libellé requis', 'error'); return null; }
  const type = document.getElementById('nf_type').value;
  const description = document.getElementById('nf_desc').value.trim();
  const obligatoire = document.getElementById('nf_required').checked ? 1 : 0;
  let options_json = null;
  if (['select','radio','checkbox'].includes(type)) {
    const raw = document.getElementById('nf_options').value.trim();
    const opts = raw.split('\n').map(s => s.trim()).filter(Boolean);
    if (opts.length === 0) { toast('Ajoutez au moins une option', 'error'); return null; }
    options_json = JSON.stringify(opts);
  }
  return { type, label, description: description || null, obligatoire, options_json, ordre: 0 };
}

async function _saveNewField() {
  const data = _collectFieldData();
  if (!data) return;
  const formData = window._formBuilderData;
  if (formData && formData.id) {
    try {
      const r = await api('/forms/' + formData.id + '/fields', { method: 'POST', body: JSON.stringify(data) });
      data.id = r.id;
    } catch(e) { toast('Erreur : ' + e.message, 'error'); return; }
  }
  window._formBuilderFields.push(data);
  document.getElementById('fb_fieldsList').innerHTML = _renderFieldsList();
  document.getElementById('fb_newFieldForm').style.display = 'none';
  toast('Champ ajouté');
}

async function _saveEditField() {
  const data = _collectFieldData();
  if (!data) return;
  const idx = window._editingFieldIdx;
  const existing = window._formBuilderFields[idx];
  if (existing && existing.id && window._formBuilderData && window._formBuilderData.id) {
    try {
      await api('/forms/' + window._formBuilderData.id + '/fields/' + existing.id, { method: 'PUT', body: JSON.stringify(data) });
    } catch(e) { toast('Erreur : ' + e.message, 'error'); return; }
  }
  data.id = existing ? existing.id : undefined;
  window._formBuilderFields[idx] = data;
  document.getElementById('fb_fieldsList').innerHTML = _renderFieldsList();
  document.getElementById('fb_newFieldForm').style.display = 'none';
  toast('Champ modifié');
}

async function _removeField(idx) {
  if (!confirm('Supprimer ce champ ?')) return;
  const field = window._formBuilderFields[idx];
  if (field && field.id && window._formBuilderData && window._formBuilderData.id) {
    try {
      await api('/forms/' + window._formBuilderData.id + '/fields/' + field.id, { method: 'DELETE' });
    } catch(e) { toast('Erreur : ' + e.message, 'error'); return; }
  }
  window._formBuilderFields.splice(idx, 1);
  document.getElementById('fb_fieldsList').innerHTML = _renderFieldsList();
  toast('Champ supprimé');
}

async function _uploadFormImage(formId) {
  const fileInput = document.getElementById('fb_image');
  if (!fileInput || !fileInput.files[0]) return;
  const fd = new FormData();
  fd.append('image', fileInput.files[0]);
  try {
    const res = await fetch(BASE+'/api/forms/'+formId+'/image', {method:'POST', headers:{Authorization:'Bearer '+TOKEN}, body:fd});
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'Erreur');
    toast('Image mise à jour');
    openFormBuilder(formId);
  } catch(e) { toast('Erreur : ' + e.message, 'error'); }
}

async function _saveFormBuilder(formId) {
  const titre = document.getElementById('fb_titre').value.trim();
  if (!titre) { toast('Titre requis', 'error'); return; }
  const payload = {
    titre,
    description: document.getElementById('fb_description').value.trim() || null,
    activity_id: document.getElementById('fb_activity').value || null,
    statut: document.getElementById('fb_statut').value,
    allow_anonymous: document.getElementById('fb_anonymous').checked ? 1 : 0,
    message_fin: document.getElementById('fb_message_fin').value.trim() || 'Merci pour votre réponse !',
    redirect_adhesion: document.getElementById('fb_redirect').checked ? 1 : 0,
    date_fermeture: document.getElementById('fb_date_fermeture').value || null
  };

  try {
    if (formId) {
      await api('/forms/' + formId, { method: 'PUT', body: JSON.stringify(payload) });
      toast('Formulaire enregistré');
      openFormBuilder(formId);
    } else {
      const r = await api('/forms', { method: 'POST', body: JSON.stringify(payload) });
      toast('Formulaire créé');
      // Save fields for new form
      for (const f of window._formBuilderFields) {
        await api('/forms/' + r.id + '/fields', { method: 'POST', body: JSON.stringify(f) });
      }
      openFormBuilder(r.id);
    }
  } catch(e) { toast('Erreur : ' + e.message, 'error'); }
}

function _exportFormCSV(formId) {
  window.open(BASE + '/api/forms/' + formId + '/export?token=' + TOKEN, '_blank');
}

async function viewFormResults(formId) {
  window._modalReturnViewId = 'forms-mgmt';
  let form = null;
  try { form = await api('/forms/' + formId); } catch(e) {
    toast('Erreur : ' + e.message, 'error'); return;
  }
  window._formResultsData = form;

  const fields = form.fields || [];
  const responses = form.responses || [];
  const total = responses.length;

  // Date range filter
  const dates = responses.map(r => r.date_reponse ? r.date_reponse.slice(0, 10) : '').filter(Boolean).sort();
  const minDate = dates.length ? dates[0] : '';
  const maxDate = dates.length ? dates[dates.length - 1] : '';

  // Chart data for select/radio/checkbox fields
  let chartsHtml = '';
  fields.forEach(f => {
    if (!['select', 'radio', 'checkbox'].includes(f.type)) return;
    const counts = {};
    let opts = [];
    try { opts = JSON.parse(f.options_json || '[]'); } catch {}
    opts.forEach(o => { counts[o] = 0; });
    responses.forEach(r => {
      const ans = (r.answers || []).find(a => a.field_id === f.id);
      if (ans && ans.valeur) {
        const vals = ans.valeur.split(', ');
        vals.forEach(v => { counts[v] = (counts[v] || 0) + 1; });
      }
    });
    const maxCount = Math.max(...Object.values(counts), 1);
    const barsHtml = Object.entries(counts).map(([label, count]) => {
      const pct = Math.round((count / maxCount) * 100);
      return `<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
        <div style="width:120px;font-size:.82rem;text-align:right;flex-shrink:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escHtml(label)}">${escHtml(label)}</div>
        <div style="flex:1;background:#e8f5e9;border-radius:4px;height:24px;position:relative;overflow:hidden">
          <div style="width:${pct}%;background:#2e7d32;height:100%;border-radius:4px;transition:width .5s"></div>
        </div>
        <div style="font-size:.82rem;font-weight:600;width:40px;text-align:right">${count}</div>
      </div>`;
    }).join('');
    chartsHtml += `<div style="background:#fff;border:1px solid var(--border);border-radius:10px;padding:16px 20px;margin-bottom:14px">
      <h4 style="margin:0 0 12px;font-size:.9rem;font-weight:700">${escHtml(f.label)}</h4>
      ${barsHtml}
    </div>`;
  });

  // Data table
  const thFields = fields.map(f => `<th style="font-size:.78rem">${escHtml(f.label)}</th>`).join('');
  const tbodyRows = responses.map(r => {
    const answerCells = fields.map(f => {
      const ans = (r.answers || []).find(a => a.field_id === f.id);
      const val = ans ? ans.valeur : '';
      if (f.type === 'signature' && val) {
        return `<td style="font-size:.82rem"><img src="${val}" alt="signature" style="height:32px;max-width:120px;object-fit:contain;border:1px solid var(--border);border-radius:4px;background:#fff;cursor:zoom-in" onclick="_showSignatureFull(this.src)"/></td>`;
      }
      return `<td style="font-size:.82rem">${escHtml(val)}</td>`;
    }).join('');
    return `<tr class="fr-row" data-date="${r.date_reponse || ''}" data-nom="${escHtml((r.nom||'').toLowerCase())}">
      <td style="font-size:.82rem;white-space:nowrap">${fmt(r.date_reponse)}</td>
      <td style="font-size:.82rem;font-weight:600">${escHtml(r.nom || '')}</td>
      <td style="font-size:.82rem">${escHtml(r.email || '')}</td>
      <td style="font-size:.82rem">${escHtml(r.telephone || '')}</td>
      ${answerCells}
    </tr>`;
  }).join('');

  setContent(`
    <div style="padding-bottom:40px">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:24px;padding-bottom:16px;border-bottom:1px solid var(--border)">
        <button onclick="showView('forms-mgmt')" style="display:flex;align-items:center;gap:6px;background:var(--off);border:1px solid var(--border);border-radius:8px;padding:7px 14px;cursor:pointer;font-size:.84rem;color:var(--text)">← Retour</button>
        <h2 style="margin:0;font-size:1.18rem;font-weight:700;flex:1">Résultats : ${escHtml(form.titre)}</h2>
        <button onclick="openRespondForMember(${form.id})" style="background:var(--g2);color:#fff;border:none;border-radius:8px;padding:8px 16px;cursor:pointer;font-size:.84rem;font-weight:600;white-space:nowrap">+ Répondre pour un membre</button>
      </div>
      ${form.date_fermeture ? `<div style="background:${new Date() > new Date(form.date_fermeture) ? '#fce4ec' : '#fff8e1'};border-radius:8px;padding:10px 16px;margin-bottom:20px;font-size:.85rem;color:${new Date() > new Date(form.date_fermeture) ? '#c62828' : '#e65100'}">
        ${new Date() > new Date(form.date_fermeture) ? '⛔ Échéance dépassée' : '🕐 Se ferme'} le ${new Date(form.date_fermeture).toLocaleString('fr-CA', { dateStyle:'long', timeStyle:'short' })} — seul le comité peut encore soumettre une réponse.
      </div>` : ''}

      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin-bottom:24px">
        <div style="background:#fff;border:1px solid var(--border);border-radius:10px;padding:16px 20px;text-align:center">
          <div style="font-size:2rem;font-weight:700;color:#1b5e20">${total}</div>
          <div style="font-size:.82rem;color:var(--muted)">Réponses totales</div>
        </div>
        <div style="background:#fff;border:1px solid var(--border);border-radius:10px;padding:16px 20px;text-align:center">
          <div style="font-size:2rem;font-weight:700;color:#1565c0">${fields.length}</div>
          <div style="font-size:.82rem;color:var(--muted)">Champs</div>
        </div>
        <div style="background:#fff;border:1px solid var(--border);border-radius:10px;padding:16px 20px;text-align:center">
          <div style="font-size:2rem;font-weight:700;color:#e65100">${form.statut === 'actif' ? 'Actif' : 'Fermé'}</div>
          <div style="font-size:.82rem;color:var(--muted)">Statut</div>
        </div>
      </div>

      ${chartsHtml ? '<h3 style="font-size:1.05rem;font-weight:700;margin-bottom:14px">Graphiques</h3>' + chartsHtml : ''}

      <h3 style="font-size:1.05rem;font-weight:700;margin-bottom:12px">Données</h3>
      <div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;align-items:center">
        <input type="text" id="fr_search" placeholder="🔍 Rechercher nom, email, réponse..." oninput="_filterFormResults()" style="flex:1;min-width:200px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:.84rem"/>
        <input type="date" id="fr_dateFrom" value="${minDate}" onchange="_filterFormResults()" style="padding:7px 10px;border:1px solid var(--border);border-radius:6px;font-size:.82rem"/>
        <input type="date" id="fr_dateTo" value="${maxDate}" onchange="_filterFormResults()" style="padding:7px 10px;border:1px solid var(--border);border-radius:6px;font-size:.82rem"/>
        <button onclick="_exportFormCSV(${form.id})" style="background:#1565c0;color:#fff;border:none;padding:8px 16px;border-radius:6px;cursor:pointer;font-size:.82rem;font-weight:600">Export CSV</button>
      </div>
      <div id="fr_count" style="font-size:.78rem;color:var(--muted);margin-bottom:8px">${total} réponse(s)</div>

      ${total === 0 ? '<div class="empty-state" style="padding:40px"><div class="es-icon">📊</div><p>Aucune réponse pour le moment</p></div>' : `
      <div style="overflow-x:auto">
        <table class="data-table">
          <thead><tr>
            <th style="font-size:.78rem;cursor:pointer" onclick="_sortFormResults('date')">Date ▼</th>
            <th style="font-size:.78rem;cursor:pointer" onclick="_sortFormResults('nom')">Nom</th>
            <th style="font-size:.78rem;cursor:pointer" onclick="_sortFormResults('email')">Courriel</th>
            <th style="font-size:.78rem;cursor:pointer" onclick="_sortFormResults('tel')">Téléphone</th>
            ${thFields}
          </tr></thead>
          <tbody id="fr_tbody">${tbodyRows}</tbody>
        </table>
      </div>`}
    </div>
  `);
}

// ── Pavé de signature (canvas dessinable, souris/tactile) ────────────────────
function _wireSignaturePad(canvas) {
  if (!canvas || canvas._sigWired) return;
  canvas._sigWired = true;
  const ctx = canvas.getContext('2d');
  ctx.strokeStyle = '#1b1b1b'; ctx.lineWidth = 2.2; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  let drawing = false, last = null;
  function pos(e) {
    const r = canvas.getBoundingClientRect();
    return { x: (e.clientX - r.left) * (canvas.width / r.width), y: (e.clientY - r.top) * (canvas.height / r.height) };
  }
  canvas.addEventListener('pointerdown', e => {
    drawing = true; last = pos(e); canvas.setPointerCapture(e.pointerId);
    canvas.dataset.hasDrawing = '1'; e.preventDefault();
  });
  canvas.addEventListener('pointermove', e => {
    if (!drawing) return;
    const p = pos(e);
    ctx.beginPath(); ctx.moveTo(last.x, last.y); ctx.lineTo(p.x, p.y); ctx.stroke();
    last = p;
  });
  ['pointerup','pointercancel','pointerleave'].forEach(ev => canvas.addEventListener(ev, () => { drawing = false; }));
}
function _clearSignaturePad(fid, selector) {
  const canvas = document.querySelector((selector || '.sig-canvas') + '[data-fid="' + fid + '"]');
  if (!canvas) return;
  canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
  canvas.dataset.hasDrawing = '';
}
function _showSignatureFull(src) {
  openModal('Signature', `<div style="text-align:center;padding:10px"><img src="${src}" style="max-width:100%;border:1px solid var(--border);border-radius:8px;background:#fff"/></div>`);
}

// ── Comité : soumettre une réponse au nom d'un membre (même après l'échéance) ──
async function openRespondForMember(formId) {
  const form = (window._formResultsData && window._formResultsData.id === formId) ? window._formResultsData : await api('/forms/' + formId);
  let allUsers = [];
  try { allUsers = await api('/users'); } catch {}
  const fields = form.fields || [];

  const fieldsHtml = fields.map(f => {
    let opts = [];
    try { opts = JSON.parse(f.options_json || '[]'); } catch {}
    const req = f.obligatoire ? ' required' : '';
    let inputHtml = '';
    switch (f.type) {
      case 'email': inputHtml = `<input type="email" data-fid="${f.id}" class="rfm-field"${req}/>`; break;
      case 'telephone': inputHtml = `<input type="tel" data-fid="${f.id}" class="rfm-field"${req}/>`; break;
      case 'textarea': inputHtml = `<textarea data-fid="${f.id}" class="rfm-field" rows="3"${req}></textarea>`; break;
      case 'number': inputHtml = `<input type="number" data-fid="${f.id}" class="rfm-field"${req}/>`; break;
      case 'date': inputHtml = `<input type="date" data-fid="${f.id}" class="rfm-field"${req}/>`; break;
      case 'select':
        inputHtml = `<select data-fid="${f.id}" class="rfm-field"${req}><option value="">-- Choisir --</option>` +
          opts.map(o => `<option value="${escHtml(o)}">${escHtml(o)}</option>`).join('') + `</select>`;
        break;
      case 'radio':
        inputHtml = `<div>` + opts.map((o,i) => `<label style="display:block;font-size:.85rem;margin-bottom:4px"><input type="radio" name="rfm_radio_${f.id}" value="${escHtml(o)}" data-fid="${f.id}" class="rfm-field-radio"${i===0&&f.obligatoire?' required':''}/> ${escHtml(o)}</label>`).join('') + `</div>`;
        break;
      case 'checkbox':
        inputHtml = `<div>` + opts.map(o => `<label style="display:block;font-size:.85rem;margin-bottom:4px"><input type="checkbox" value="${escHtml(o)}" data-fid="${f.id}" class="rfm-field-check"/> ${escHtml(o)}</label>`).join('') + `</div>`;
        break;
      case 'signature':
        inputHtml = `<div>
          <canvas class="rfm-sig-canvas" data-fid="${f.id}" width="500" height="150" style="width:100%;max-width:500px;height:150px;border:1.5px dashed #bbb;border-radius:8px;background:#fff;touch-action:none;cursor:crosshair;display:block"></canvas>
          <button type="button" onclick="_clearSignaturePad(${f.id},'.rfm-sig-canvas')" style="margin-top:6px;background:var(--off);border:1px solid var(--border);padding:5px 12px;border-radius:6px;font-size:.78rem;cursor:pointer">Effacer</button>
        </div>`;
        break;
      default: inputHtml = `<input type="text" data-fid="${f.id}" class="rfm-field"${req}/>`;
    }
    return `<div class="form-group"><label>${escHtml(f.label)}${f.obligatoire ? ' *' : ''}</label>${f.description ? `<small style="color:var(--muted);display:block;margin-bottom:4px">${escHtml(f.description)}</small>` : ''}${inputHtml}</div>`;
  }).join('');

  openModal('Répondre pour un membre — ' + escHtml(form.titre), `
    <form id="rfmForm">
      <div class="form-group"><label>Membre *</label>
        <select id="rfm_user" required>
          <option value="">-- Choisir un membre --</option>
          ${allUsers.filter(u => u.actif).map(u => `<option value="${u.id}">${escHtml(u.prenom)} ${escHtml(u.nom)}</option>`).join('')}
        </select>
      </div>
      ${fieldsHtml}
      <div class="form-actions">
        <button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>
        <button type="submit" class="btn btn-primary">Enregistrer la réponse</button>
      </div>
    </form>
  `);
  document.querySelectorAll('.rfm-sig-canvas').forEach(_wireSignaturePad);

  document.getElementById('rfmForm').onsubmit = async e => {
    e.preventDefault();
    const userId = parseInt(document.getElementById('rfm_user').value);
    if (!userId) { toast('Choisissez un membre', 'error'); return; }
    const missingSig = fields.find(f => f.type === 'signature' && f.obligatoire &&
      document.querySelector('.rfm-sig-canvas[data-fid="' + f.id + '"]')?.dataset.hasDrawing !== '1');
    if (missingSig) { toast('Signature requise : ' + missingSig.label, 'error'); return; }
    const answers = [];
    fields.forEach(f => {
      let val = '';
      if (f.type === 'checkbox') {
        val = Array.from(document.querySelectorAll('.rfm-field-check[data-fid="' + f.id + '"]:checked')).map(el => el.value).join(', ');
      } else if (f.type === 'radio') {
        const sel = document.querySelector('.rfm-field-radio[data-fid="' + f.id + '"]:checked');
        val = sel ? sel.value : '';
      } else if (f.type === 'signature') {
        const canvas = document.querySelector('.rfm-sig-canvas[data-fid="' + f.id + '"]');
        val = (canvas && canvas.dataset.hasDrawing === '1') ? canvas.toDataURL('image/png') : '';
      } else {
        const el = document.querySelector('.rfm-field[data-fid="' + f.id + '"]');
        val = el ? el.value : '';
      }
      if (val) answers.push({ field_id: f.id, valeur: val });
    });
    try {
      await api('/forms/' + formId + '/respond-for', { method: 'POST', body: JSON.stringify({ user_id: userId, answers }) });
      closeModal();
      toast('Réponse enregistrée');
      viewFormResults(formId);
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

function _filterFormResults() {
  var q = (document.getElementById('fr_search')?.value || '').toLowerCase();
  var from = document.getElementById('fr_dateFrom')?.value || '';
  var to = document.getElementById('fr_dateTo')?.value || '';
  var shown = 0;
  document.querySelectorAll('.fr-row').forEach(function(row) {
    var d = (row.dataset.date || '').slice(0, 10);
    var text = row.textContent.toLowerCase();
    var matchDate = (!from || d >= from) && (!to || d <= to);
    var matchSearch = !q || text.includes(q);
    var visible = matchDate && matchSearch;
    row.style.display = visible ? '' : 'none';
    if (visible) shown++;
  });
  var cnt = document.getElementById('fr_count');
  if (cnt) cnt.textContent = shown + ' réponse(s) affichée(s)';
}

var _frSortDir = 'desc';
function _sortFormResults(col) {
  _frSortDir = _frSortDir === 'desc' ? 'asc' : 'desc';
  var tbody = document.getElementById('fr_tbody');
  if (!tbody) return;
  var rows = Array.from(tbody.querySelectorAll('.fr-row'));
  rows.sort(function(a, b) {
    var va, vb;
    if (col === 'date') { va = a.dataset.date || ''; vb = b.dataset.date || ''; }
    else if (col === 'nom') { va = a.cells[1]?.textContent || ''; vb = b.cells[1]?.textContent || ''; }
    else if (col === 'email') { va = a.cells[2]?.textContent || ''; vb = b.cells[2]?.textContent || ''; }
    else if (col === 'tel') { va = a.cells[3]?.textContent || ''; vb = b.cells[3]?.textContent || ''; }
    else { va = ''; vb = ''; }
    va = va.toLowerCase(); vb = vb.toLowerCase();
    return _frSortDir === 'asc' ? (va > vb ? 1 : -1) : (va < vb ? 1 : -1);
  });
  rows.forEach(function(r) { tbody.appendChild(r); });
}

// ══════════════════════════════════════════════════════════════════════════════
// ── BOUTIQUE EN LIGNE — Gestion des produits & commandes ─────────────────────
// ══════════════════════════════════════════════════════════════════════════════

async function shopMgmtView() {
  var tab = window._shopTab || 'products';
  var products = [];
  var orders = [];
  try { products = await api('/shop/products-all'); } catch(e) { products = []; }
  try { orders = await api('/shop/orders'); } catch(e) { orders = []; }
  window._shopProducts = products;
  window._shopOrders = orders;

  function shopStatusPill(s) {
    var colors = { en_attente:'#ff9800', confirmee:'#2196f3', expediee:'#9c27b0', livree:'#4caf50', annulee:'#f44336' };
    var labels = { en_attente:'En attente', confirmee:'Confirmee', expediee:'Expediee', livree:'Livree', annulee:'Annulee' };
    return '<span style="background:' + (colors[s]||'#999') + ';color:#fff;padding:3px 10px;border-radius:12px;font-size:.75rem;font-weight:700">' + (labels[s]||s) + '</span>';
  }

  var productsHtml = '<div class="table-wrapper"><table><thead><tr>' +
    '<th>Image</th><th>Nom</th><th>Prix</th><th>Stock</th><th>Categorie</th><th>Actif</th><th>Actions</th>' +
    '</tr></thead><tbody>' +
    (products.length ? products.map(function(p) {
      return '<tr>' +
        '<td>' + (p.image_path ? '<img src="' + escHtml(p.image_path) + '" style="width:48px;height:48px;object-fit:cover;border-radius:8px" onerror="this.style.display=\'none\'"/>' : '-') + '</td>' +
        '<td><strong>' + escHtml(p.nom) + '</strong></td>' +
        '<td>' + (p.prix ? p.prix.toFixed(2) + ' $' : '-') + '</td>' +
        '<td>' + p.stock + '</td>' +
        '<td>' + escHtml(p.categorie || 'general') + '</td>' +
        '<td>' + (p.actif ? '<span style="color:#4caf50;font-weight:700">Oui</span>' : '<span style="color:#f44336">Non</span>') + '</td>' +
        '<td style="white-space:nowrap">' +
          '<button class="btn btn-ghost" style="font-size:.78rem;padding:4px 10px" onclick="_shopEditProduct(' + p.id + ')">Modifier</button> ' +
          '<button class="btn btn-ghost" style="font-size:.78rem;padding:4px 10px;color:#f44336" onclick="_shopDeleteProduct(' + p.id + ')">Supprimer</button>' +
        '</td></tr>';
    }).join('') : '<tr><td colspan="7" style="text-align:center">Aucun produit</td></tr>') +
    '</tbody></table></div>';

  var ordersHtml = '<div class="table-wrapper"><table><thead><tr>' +
    '<th>#</th><th>Acheteur</th><th>Total</th><th>Methode</th><th>Statut</th><th>Date</th><th>Articles</th><th>Actions</th>' +
    '</tr></thead><tbody>' +
    (orders.length ? orders.map(function(o) {
      var itemsStr = (o.items || []).map(function(i) { return escHtml(i.produit_nom) + ' x' + i.quantite; }).join(', ');
      return '<tr>' +
        '<td>' + o.id + '</td>' +
        '<td>' + escHtml(o.acheteur_nom || o.user_nom || '-') + '</td>' +
        '<td>' + (o.total ? o.total.toFixed(2) + ' $' : '-') + '</td>' +
        '<td>' + escHtml(o.methode || 'interac') + '</td>' +
        '<td>' + shopStatusPill(o.statut) + '</td>' +
        '<td>' + fmt(o.date_commande) + '</td>' +
        '<td style="font-size:.8rem;max-width:200px">' + escHtml(itemsStr) + '</td>' +
        '<td><select onchange="_shopUpdateOrderStatus(' + o.id + ',this.value)" style="font-size:.78rem;padding:3px 6px;border-radius:6px;border:1px solid var(--border)">' +
          ['en_attente','confirmee','expediee','livree','annulee'].map(function(s) {
            return '<option value="' + s + '"' + (o.statut===s?' selected':'') + '>' + s.charAt(0).toUpperCase()+s.slice(1) + '</option>';
          }).join('') +
        '</select></td></tr>';
    }).join('') : '<tr><td colspan="8" style="text-align:center">Aucune commande</td></tr>') +
    '</tbody></table></div>';

  setContent(
    '<div class="page-header">' +
      '<div><h2>Boutique en ligne</h2><p>' + products.length + ' produit(s) &mdash; ' + orders.length + ' commande(s)</p></div>' +
      '<div class="page-actions"><button class="btn btn-primary" onclick="_shopAddProduct()">+ Ajouter un produit</button></div>' +
    '</div>' +
    '<div style="display:flex;gap:8px;margin-bottom:18px">' +
      '<button class="btn ' + (tab==='products'?'btn-primary':'btn-ghost') + '" onclick="window._shopTab=\'products\';shopMgmtView()">Produits</button>' +
      '<button class="btn ' + (tab==='orders'?'btn-primary':'btn-ghost') + '" onclick="window._shopTab=\'orders\';shopMgmtView()">Commandes</button>' +
    '</div>' +
    (tab === 'products' ? productsHtml : ordersHtml)
  );
}

function _shopAddProduct() {
  openModal('Ajouter un produit',
    '<form id="shopProdForm" enctype="multipart/form-data">' +
    '<div class="form-group"><label>Nom *</label><input id="sp_nom" required/></div>' +
    '<div class="form-group"><label>Description</label><textarea id="sp_desc" rows="3"></textarea></div>' +
    '<div class="form-row">' +
      '<div class="form-group"><label>Prix ($) *</label><input type="number" id="sp_prix" step="0.01" min="0" required/></div>' +
      '<div class="form-group"><label>Stock</label><input type="number" id="sp_stock" value="0" min="0"/></div>' +
    '</div>' +
    '<div class="form-row">' +
      '<div class="form-group"><label>Categorie</label><input id="sp_cat" value="general"/></div>' +
      '<div class="form-group"><label>Image</label><input type="file" id="sp_image" accept="image/*"/></div>' +
    '</div>' +
    '<div class="form-actions">' +
      '<button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>' +
      '<button type="submit" class="btn btn-primary">Ajouter</button>' +
    '</div></form>'
  );
  document.getElementById('shopProdForm').onsubmit = async function(e) {
    e.preventDefault();
    var fd = new FormData();
    fd.append('nom', document.getElementById('sp_nom').value);
    fd.append('description', document.getElementById('sp_desc').value);
    fd.append('prix', document.getElementById('sp_prix').value);
    fd.append('stock', document.getElementById('sp_stock').value);
    fd.append('categorie', document.getElementById('sp_cat').value);
    var img = document.getElementById('sp_image').files[0];
    if (img) fd.append('image', img);
    try {
      await fetch(API + '/shop/products', { method:'POST', headers:{ 'Authorization':'Bearer ' + TOKEN }, body:fd });
      toast('Produit ajoute !');
      closeModal();
      shopMgmtView();
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function _shopEditProduct(id) {
  var p = (window._shopProducts || []).find(function(x) { return x.id === id; });
  if (!p) return;
  openModal('Modifier le produit',
    '<form id="shopProdForm" enctype="multipart/form-data">' +
    '<div class="form-group"><label>Nom *</label><input id="sp_nom" value="' + escHtml(p.nom) + '" required/></div>' +
    '<div class="form-group"><label>Description</label><textarea id="sp_desc" rows="3">' + escHtml(p.description || '') + '</textarea></div>' +
    '<div class="form-row">' +
      '<div class="form-group"><label>Prix ($) *</label><input type="number" id="sp_prix" step="0.01" min="0" value="' + p.prix + '" required/></div>' +
      '<div class="form-group"><label>Stock</label><input type="number" id="sp_stock" value="' + p.stock + '" min="0"/></div>' +
    '</div>' +
    '<div class="form-row">' +
      '<div class="form-group"><label>Categorie</label><input id="sp_cat" value="' + escHtml(p.categorie || 'general') + '"/></div>' +
      '<div class="form-group"><label>Image</label><input type="file" id="sp_image" accept="image/*"/></div>' +
    '</div>' +
    '<div class="form-group"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="sp_actif" style="width:auto"' + (p.actif ? ' checked' : '') + '/> Produit actif</label></div>' +
    '<div class="form-actions">' +
      '<button type="button" class="btn btn-ghost" onclick="closeModal()">Annuler</button>' +
      '<button type="submit" class="btn btn-primary">Enregistrer</button>' +
    '</div></form>'
  );
  document.getElementById('shopProdForm').onsubmit = async function(e) {
    e.preventDefault();
    var fd = new FormData();
    fd.append('nom', document.getElementById('sp_nom').value);
    fd.append('description', document.getElementById('sp_desc').value);
    fd.append('prix', document.getElementById('sp_prix').value);
    fd.append('stock', document.getElementById('sp_stock').value);
    fd.append('categorie', document.getElementById('sp_cat').value);
    fd.append('actif', document.getElementById('sp_actif').checked ? '1' : '0');
    var img = document.getElementById('sp_image').files[0];
    if (img) fd.append('image', img);
    try {
      await fetch(API + '/shop/products/' + id, { method:'PUT', headers:{ 'Authorization':'Bearer ' + TOKEN }, body:fd });
      toast('Produit mis a jour !');
      closeModal();
      shopMgmtView();
    } catch(ex) { toast(ex.message, 'error'); }
  };
}

async function _shopDeleteProduct(id) {
  if (!confirm('Supprimer ce produit ?')) return;
  try {
    await api('/shop/products/' + id, { method:'DELETE' });
    toast('Produit supprime');
    shopMgmtView();
  } catch(ex) { toast(ex.message, 'error'); }
}

async function _shopUpdateOrderStatus(orderId, statut) {
  try {
    await api('/shop/orders/' + orderId + '/status', { method:'PUT', body: JSON.stringify({ statut: statut }) });
    toast('Statut mis a jour');
  } catch(ex) { toast(ex.message, 'error'); }
}

