function openCmSignModal(meetingId) {
  openModal('✍️ Signer la rencontre comité', `
    <p style="font-size:.85rem;color:var(--muted);margin-bottom:12px">Dessinez votre signature dans la zone ci-dessous. Elle sera horodatée et liée à votre compte.<br>
    <strong style="color:#1b5e20">⚠️ La personne qui a créé la rencontre doit signer en premier ; 2 autres membres du comité peuvent ensuite signer. Après 3 signatures, la rencontre sera verrouillée — et l'ordre du jour lié sera automatiquement verrouillé par les mêmes signataires.</strong></p>
    <canvas id="cmSigCanvas" width="540" height="160" style="border:1px solid #ccc;border-radius:8px;cursor:crosshair;display:block;width:100%;touch-action:none"></canvas>
    <div style="margin-top:8px;display:flex;gap:8px">
      <button class="btn btn-sm btn-ghost" onclick="_clearCmCanvas()">🗑 Effacer</button>
    </div>
    <div style="margin-top:16px;display:flex;gap:8px">
      <button class="btn btn-primary" onclick="_saveCmSignature(${meetingId})">✅ Signer le document</button>
      <button class="btn btn-outline" onclick="closeModal()">Annuler</button>
    </div>
  `);
  setTimeout(() => {
    const canvas = document.getElementById('cmSigCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let drawing = false;
    const getPos = e => {
      const r = canvas.getBoundingClientRect();
      const src = e.touches ? e.touches[0] : e;
      return { x: (src.clientX - r.left) * (canvas.width / r.width), y: (src.clientY - r.top) * (canvas.height / r.height) };
    };
    canvas.addEventListener('mousedown', e => { drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('mousemove', e => { if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); });
    canvas.addEventListener('mouseup', () => { drawing = false; });
    canvas.addEventListener('touchstart', e => { e.preventDefault(); drawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }, { passive: false });
    canvas.addEventListener('touchmove', e => { e.preventDefault(); if (!drawing) return; const p = getPos(e); ctx.lineWidth = 2.5; ctx.strokeStyle = '#1b5e20'; ctx.lineCap = 'round'; ctx.lineTo(p.x, p.y); ctx.stroke(); }, { passive: false });
    canvas.addEventListener('touchend', () => { drawing = false; });
  }, 50);
}

function _clearCmCanvas() {
  const c = document.getElementById('cmSigCanvas');
  if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height);
}

async function _saveCmSignature(meetingId) {
  const canvas = document.getElementById('cmSigCanvas');
  if (!canvas) return;
  const blank = document.createElement('canvas'); blank.width = canvas.width; blank.height = canvas.height;
  if (canvas.toDataURL() === blank.toDataURL()) return toast('Veuillez dessiner votre signature', true);
  const signature_data = canvas.toDataURL('image/png');
  try {
    const r = await api('/committee-meetings/' + meetingId + '/sign', { method:'POST', body: JSON.stringify({ signature_data }) });
    closeModal();
    if (r.verrouille) {
      toast('🔒 Rencontre verrouillée : ' + r.nb_signatures + ' signatures collectées' + (r.agenda_verrouille ? ' — ordre du jour lié verrouillé aussi' : ''));
    } else {
      toast('✅ Signature enregistrée (' + r.nb_signatures + '/3 pour verrouiller)');
    }
    committeeMeetingDetail(meetingId);
  } catch(e) { toast(e.message, true); }
}

async function committeeMeetingDelete(id) {
  if (!confirm('Supprimer cette rencontre définitivement ?')) return;
  try {
    await api('/committee-meetings/' + id, { method:'DELETE' });
    toast('Rencontre supprimée');
    committeeMeetingsView();
  } catch(e) { toast(e.message, true); }
}

// ══ ALERTES URGENTES ════════════════════════════════════════════════════════
async function alertesUrgentesView() {
  const alertes = await api('/alertes-urgentes');
  const cats = { transport:'🚗 Transport', logement:'🏠 Logement', alimentaire:'🍽️ Alimentaire', sante:'🏥 Santé', emploi:'💼 Emploi', autre:'📢 Autre' };
  const rows = alertes.length ? alertes.map(a => `
    <tr>
      <td><span style="font-size:1.1rem">${cats[a.categorie]||'📢'}</span></td>
      <td><strong>${escHtml(a.titre)}</strong><br/><small style="color:var(--muted)">${escHtml(a.description).substring(0,80)}…</small></td>
      <td>${escHtml(a.prenom||'')} ${escHtml(a.nom||'')}</td>
      <td>${a.contact ? `<a href="tel:${escHtml(a.contact)}">${escHtml(a.contact)}</a>` : '—'}</td>
      <td>${fmt(a.date_creation)}</td>
      <td>
        ${can.executive() ? `<button class="btn btn-sm" onclick="_alerteResoudre(${a.id})">✅ Résoudre</button>` : ''}
        <button class="btn btn-sm" style="background:var(--danger);color:#fff" onclick="_alerteSupprimer(${a.id})">🗑</button>
      </td>
    </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--muted)">Aucune alerte active</td></tr>';

  setContent(`
    <div class="view-header">
      <h1>🚨 Alertes urgentes</h1>
      <button class="btn btn-primary" onclick="_alerteNouvelle()">+ Nouvelle alerte</button>
    </div>
    <div class="card" style="margin-bottom:16px;background:#fff8e1;border:1px solid #ffe082">
      <p style="margin:0;font-size:.85rem;color:#5d4037">⚠️ Cet espace permet aux membres d'exprimer un besoin urgent d'entraide (transport, logement, repas, etc.). Soyez bienveillants et discrets.</p>
    </div>

    <div class="desktop-page-only card">
      <table class="data-table">
        <thead><tr><th>Type</th><th>Demande</th><th>Membre</th><th>Contact</th><th>Date</th><th>Actions</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>

    <div class="mobile-page-only">
      <div class="m-chiprow" id="auChips">
        <span class="m-chip active" data-f="" onclick="_auChipClick(this)">Toutes</span>
        ${Object.entries(cats).map(([k,l]) => `<span class="m-chip" data-f="${k}" onclick="_auChipClick(this)">${l}</span>`).join('')}
      </div>
      <div id="auListMobile">
      ${alertes.length ? alertes.map(a => `
        <div class="m-item au-entry" data-cat="${a.categorie||'autre'}">
          <div class="m-item-top"><div class="m-item-title">${cats[a.categorie]||'📢'} ${escHtml(a.titre)}</div></div>
          <div class="m-item-sub">${escHtml(a.description)}</div>
          <div class="m-item-sub">👤 ${escHtml(a.prenom||'')} ${escHtml(a.nom||'')} · ${fmt(a.date_creation)}${a.contact ? ` · <a href="tel:${escHtml(a.contact)}">📞 ${escHtml(a.contact)}</a>` : ''}</div>
          <div class="m-item-actions">
            ${can.executive() ? `<button class="btn btn-sm btn-primary" onclick="_alerteResoudre(${a.id})">✅ Résoudre</button>` : ''}
            <button class="btn btn-sm btn-ghost" style="color:#c62828" onclick="_alerteSupprimer(${a.id})">🗑 Supprimer</button>
          </div>
        </div>`).join('') : '<div class="m-empty">Aucune alerte active</div>'}
      </div>
    </div>`);
}

function _auChipClick(chip) {
  chip.parentElement.querySelectorAll('.m-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  const f = chip.dataset.f;
  document.querySelectorAll('.au-entry').forEach(el => {
    el.style.display = (!f || el.dataset.cat === f) ? '' : 'none';
  });
}

function _alerteNouvelle() {
  const cats = { transport:'🚗 Transport', logement:'🏠 Logement', alimentaire:'🍽️ Alimentaire', sante:'🏥 Santé', emploi:'💼 Emploi', autre:'📢 Autre' };
  openModal('🚨 Nouvelle alerte urgente', `
    <div class="form-group"><label>Titre de la demande *</label>
      <input id="au_titre" class="form-control" placeholder="Ex: Besoin de transport samedi matin" maxlength="120"/></div>
    <div class="form-group"><label>Description *</label>
      <textarea id="au_desc" class="form-control" rows="3" placeholder="Expliquez votre besoin..."></textarea></div>
    <div class="form-group"><label>Catégorie</label>
      <select id="au_cat" class="form-control">
        ${Object.entries(cats).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}
      </select></div>
    <div class="form-group"><label>Contact (téléphone ou info)</label>
      <input id="au_contact" class="form-control" placeholder="Optionnel"/></div>
    <button class="btn btn-primary" onclick="_alerteSauver()">Envoyer l'alerte</button>
  `);
}

async function _alerteSauver() {
  const titre = document.getElementById('au_titre')?.value.trim();
  const description = document.getElementById('au_desc')?.value.trim();
  if (!titre || !description) return toast('Titre et description requis', true);
  try {
    await api('/alertes-urgentes', { method:'POST', body: JSON.stringify({
      titre, description,
      categorie: document.getElementById('au_cat')?.value || 'autre',
      contact: document.getElementById('au_contact')?.value.trim() || ''
    })});
    toast('Alerte envoyée — la communauté vous répond !');
    closeModal();
    alertesUrgentesView();
  } catch(e) { toast(e.message, true); }
}

async function _alerteResoudre(id) {
  if (!confirm('Marquer cette alerte comme résolue ?')) return;
  try {
    await api('/alertes-urgentes/' + id + '/resoudre', { method:'PUT' });
    toast('Alerte résolue');
    alertesUrgentesView();
  } catch(e) { toast(e.message, true); }
}

async function _alerteSupprimer(id) {
  if (!confirm('Supprimer cette alerte ?')) return;
  try {
    await api('/alertes-urgentes/' + id, { method:'DELETE' });
    toast('Alerte supprimée');
    alertesUrgentesView();
  } catch(e) { toast(e.message, true); }
}

// ══ MUR DE FIERTÉ ════════════════════════════════════════════════════════════
const FIERTE_CATS = {
  diplome:'🎓 Diplôme', emploi:'💼 Emploi / Promotion',
  arts:'🎨 Arts & Culture', sport:'⚽ Sport',
  entreprise:'🚀 Entrepreneuriat', communaute:'🤝 Communauté'
};

async function fierteMgmtView() {
  if (!document.getElementById('miseEnValeurHubBody')) { return miseEnValeurHubView('fierte'); }
  const entries = await api('/fierte');
  const rows = entries.length ? entries.map(e => `
    <tr>
      <td><strong>${escHtml(e.nom)}</strong></td>
      <td>${escHtml(FIERTE_CATS[e.categorie] || e.categorie)}</td>
      <td style="max-width:260px;font-size:.82rem;color:var(--muted)">${escHtml(e.texte).substring(0,90)}…</td>
      <td>${e.date_realisation ? fmt(e.date_realisation) : '—'}</td>
      <td style="font-size:.78rem;color:var(--muted)">${escHtml(e.cree_prenom||'')} ${escHtml(e.cree_nom||'')}</td>
      <td><button class="btn btn-sm" style="background:var(--danger);color:#fff" onclick="_fierteSupprimer(${e.id})">🗑</button></td>
    </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--muted)">Aucune réalisation publiée</td></tr>';

  document.getElementById('miseEnValeurHubBody').innerHTML = `
    <div class="page-actions" style="margin-bottom:14px">
      <a href="/fierte.html" target="_blank" class="btn">Voir la page publique ↗</a>
      <button class="btn btn-primary" onclick="_fierteNouveau()">+ Ajouter une réalisation</button>
    </div>
    <div class="card">
      <table class="data-table">
        <thead><tr><th>Membre</th><th>Catégorie</th><th>Texte</th><th>Date</th><th>Publié par</th><th></th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

function _fierteNouveau() {
  openModal('🏆 Nouvelle réalisation', `
    <div class="form-group"><label>Nom complet *</label>
      <input id="fi_nom" class="form-control" placeholder="Ex: Marie-Josée B."/></div>
    <div class="form-group"><label>Initiales (pour l'avatar)</label>
      <input id="fi_init" class="form-control" placeholder="Ex: MJ" maxlength="3" style="width:80px"/></div>
    <div class="form-group"><label>Catégorie *</label>
      <select id="fi_cat" class="form-control">
        ${Object.entries(FIERTE_CATS).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}
      </select></div>
    <div class="form-group"><label>Titre du badge</label>
      <input id="fi_badge" class="form-control" placeholder="Ex: 🎓 Diplôme, 💼 Promotion…"/></div>
    <div class="form-group"><label>Description de la réalisation *</label>
      <textarea id="fi_texte" class="form-control" rows="4" placeholder="Décrivez la réalisation de ce membre…"></textarea></div>
    <div class="form-group"><label>Date de la réalisation</label>
      <input id="fi_date" class="form-control" type="month"/></div>
    <button class="btn btn-primary" onclick="_fierteSauver()">Publier sur le mur</button>
  `);
}

async function _fierteSauver() {
  const nom = document.getElementById('fi_nom')?.value.trim();
  const texte = document.getElementById('fi_texte')?.value.trim();
  const categorie = document.getElementById('fi_cat')?.value;
  if (!nom || !texte) return toast('Nom et description requis', true);

  const dateVal = document.getElementById('fi_date')?.value;
  let date_realisation = null;
  if (dateVal) {
    const [y, m] = dateVal.split('-');
    const months = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
    date_realisation = `${months[parseInt(m)-1]} ${y}`;
  }

  try {
    await api('/fierte', { method:'POST', body: JSON.stringify({
      nom, texte, categorie,
      initiales: document.getElementById('fi_init')?.value.trim() || nom.split(' ').map(w=>w[0]).join('').substring(0,3).toUpperCase(),
      titre_badge: document.getElementById('fi_badge')?.value.trim() || FIERTE_CATS[categorie],
      date_realisation
    })});
    toast('Réalisation publiée sur le mur de fierté !');
    closeModal();
    fierteMgmtView();
  } catch(e) { toast(e.message, true); }
}

async function _fierteSupprimer(id) {
  if (!confirm('Supprimer cette réalisation du mur ?')) return;
  try {
    await api('/fierte/' + id, { method:'DELETE' });
    toast('Réalisation supprimée');
    fierteMgmtView();
  } catch(e) { toast(e.message, true); }
}
